import hashlib
import json
import subprocess
import sys
import tempfile
from pathlib import Path, PurePosixPath

MARCA_DO_DADO = "#"
PREFIXO_DO_ARQUIVO = MARCA_DO_DADO + "["
PREFIXO_DO_FECHO = MARCA_DO_DADO + "fim "
TAMANHO_DA_VERSAO = 10
NOME_DA_PASTA = "atlas-{}"
MENSAGEM_DO_COMMIT = "camada {}"
IDENTIDADE_DO_COMMIT = ("-c", "user.name=camada", "-c", "user.email=camada@invalid",
                        "-c", "commit.gpgsign=false")
SEM_CONVERSAO_DE_FIM_DE_LINHA = ("-c", "core.autocrlf=false", "-c", "core.safecrlf=false")
INICIO_SEM_AVISO = ("-c", "init.defaultBranch=main")

SEM_A_CAMADA = (
    "Este e o molde, sem a camada dentro: ela entra nele quando o repositorio "
    "e publicado.\n"
    "Abra o camada-em-um-arquivo.py do repositorio publico em modo raw, "
    "selecione tudo, copie e salve com este nome. Depois rode de novo.")
CHEGOU_INCOMPLETO = (
    "O pacote chegou incompleto ou alterado: {}.\n"
    "Nada foi gravado. Abra o raw de novo, selecione tudo (Ctrl+A), copie e "
    "salve por cima deste arquivo.")
FALTA_O_FECHO = "falta a ultima linha, a do fecho, ou ela veio cortada"
CONTAGEM_NAO_BATE = "o fecho diz {} arquivo(s) e chegaram {}"
HASH_NAO_BATE = "o conteudo nao bate com o hash do fecho"
ILEGIVEL = "o arquivo nao se le como texto ({})"
CAMINHO_PROIBIDO = ("O pacote traz um caminho que sairia da pasta: {}\n"
                    "Nada foi gravado.")
PASTA_OCUPADA = (
    "A pasta {} ja existe e nao guarda esta versao da camada.\n"
    "Nada foi gravado. Escolha outra: python {} <pasta nova>")
EM_DIA = "A camada {} ja esta em {}, sem mudanca."
GIT_FALHOU = "git {} falhou:\n{}"
GIT_AUSENTE = "O git nao esta no PATH, e a pasta precisa ser um repositorio git."
PRONTO = (
    "Camada {versao} reconstruida em {pasta}: {quantos} arquivo(s), num "
    "repositorio git com um commit.\n"
    "De dentro do repositorio que vai recebe-la, rode:\n"
    "    python {montar}\n"
    "Se ele ja tem a camada, rode:\n"
    "    python {montar} --atualizar")


def git(pasta: Path, *argumentos) -> str:
    try:
        feito = subprocess.run(["git", *argumentos], cwd=str(pasta),
                               capture_output=True, text=True,
                               encoding="utf-8", errors="replace")
    except OSError:
        sys.exit(GIT_AUSENTE)
    if feito.returncode != 0:
        sys.exit(GIT_FALHOU.format(" ".join(argumentos),
                                   (feito.stderr or feito.stdout).strip()))
    return feito.stdout.strip()


def linhas_do_pacote(pacote: Path) -> list:
    try:
        return pacote.read_text(encoding="utf-8-sig").splitlines()
    except (UnicodeDecodeError, OSError) as erro:
        sys.exit(CHEGOU_INCOMPLETO.format(ILEGIVEL.format(erro)))


def arquivos_conferidos(linhas: list) -> tuple:
    dados = [linha[1:] for linha in linhas if linha.startswith(PREFIXO_DO_ARQUIVO)]
    fechos = [linha for linha in linhas if linha.startswith(PREFIXO_DO_FECHO)]
    if not dados and not fechos:
        sys.exit(SEM_A_CAMADA)
    partes_do_fecho = fechos[-1][len(PREFIXO_DO_FECHO):].split() if fechos else []
    if len(partes_do_fecho) != 2 or not partes_do_fecho[0].isdigit():
        sys.exit(CHEGOU_INCOMPLETO.format(FALTA_O_FECHO))
    quantos, esperado = partes_do_fecho
    if int(quantos) != len(dados):
        sys.exit(CHEGOU_INCOMPLETO.format(
            CONTAGEM_NAO_BATE.format(quantos, len(dados))))
    if hash_dos_dados(dados) != esperado:
        sys.exit(CHEGOU_INCOMPLETO.format(HASH_NAO_BATE))
    return [json.loads(linha) for linha in dados], esperado[:TAMANHO_DA_VERSAO]


def hash_dos_dados(dados: list) -> str:
    return hashlib.sha256("\n".join(dados).encode("ascii")).hexdigest()


def caminho_sai_da_pasta(caminho: str) -> bool:
    partes = PurePosixPath(caminho).parts
    return (not partes or caminho.startswith("/") or ":" in caminho
            or "\\" in caminho or ".." in partes or partes[0] == ".git")


def pasta_em_dia(pasta: Path, versao: str) -> bool:
    if not (pasta / ".git").exists():
        return False
    return (git(pasta, "log", "-1", "--format=%s") == MENSAGEM_DO_COMMIT.format(versao)
            and git(pasta, "status", "--porcelain") == "")


def reconstruir(pacote: Path, pasta_pedida: str) -> int:
    arquivos, versao = arquivos_conferidos(linhas_do_pacote(pacote))
    proibidos = [caminho for caminho, _ in arquivos if caminho_sai_da_pasta(caminho)]
    if proibidos:
        sys.exit(CAMINHO_PROIBIDO.format(proibidos[0]))

    pasta = (Path(pasta_pedida) if pasta_pedida
             else pacote.parent / NOME_DA_PASTA.format(versao)).resolve()
    if pasta.exists() and any(pasta.iterdir()):
        if pasta_em_dia(pasta, versao):
            print(EM_DIA.format(versao, pasta))
            return 0
        sys.exit(PASTA_OCUPADA.format(pasta, pacote.name))

    for caminho, texto in arquivos:
        alvo = pasta / caminho
        alvo.parent.mkdir(parents=True, exist_ok=True)
        alvo.write_bytes(texto.encode("utf-8"))
    git(pasta, *INICIO_SEM_AVISO, "init", "-q")
    git(pasta, *SEM_CONVERSAO_DE_FIM_DE_LINHA, "add", "-A")
    git(pasta, *IDENTIDADE_DO_COMMIT, "commit", "-q", "--no-verify",
        "-m", MENSAGEM_DO_COMMIT.format(versao))
    print(PRONTO.format(versao=versao, pasta=pasta, quantos=len(arquivos),
                        montar=pasta / "montar.py"))
    return 0


def pacote_com_a_camada(molde: str, arquivos: dict) -> str:
    dados = [json.dumps([caminho, arquivos[caminho]], ensure_ascii=True)
             for caminho in sorted(arquivos)]
    fecho = "{}{} {}".format(PREFIXO_DO_FECHO, len(dados), hash_dos_dados(dados))
    linhas = [MARCA_DO_DADO + dado for dado in dados] + [fecho]
    return molde.rstrip("\n") + "\n\n" + "\n".join(linhas) + "\n"


def molde_sem_a_camada(pacote: Path) -> str:
    return "\n".join(linha for linha in pacote.read_text(encoding="utf-8-sig").splitlines()
                     if not linha.startswith(MARCA_DO_DADO)) + "\n"


BANDEIRA_DE_TESTE = "--testar"
ARQUIVOS_DE_TESTE = {
    "montar.py": "print('instalador de mentira')\n",
    "conhecimento/acentua" + chr(0xe7) + chr(0xe3) + "o.md":
        "A" + chr(0xe7) + chr(0xe3) + "o e cora" + chr(0xe7) + chr(0xe3) + "o\n",
    "sub/pasta/com-retorno.txt": "linha com retorno\r\nde carro dentro\r\n",
}
TRECHO_CORTADO_DO_ULTIMO_DADO = 12
QUANTOS_CASOS = 4
TETO_DE_CADA_RODADA_S = 60
FALHA_DO_CASO = "  FALHOU - {}: {!r}"
RESUMO_OK = ("OK: {} casos - o pacote volta byte a byte, aguenta a colagem no "
             "Windows, recusa o que chegou cortado ou alterado e nao pisa pasta")
RESUMO_FALHOU = "FALHOU: {} de {} casos"


def rodada(pacote: Path, pasta: Path):
    return subprocess.run([sys.executable, str(pacote), str(pasta)],
                          capture_output=True, text=True, encoding="utf-8",
                          errors="replace", timeout=TETO_DE_CADA_RODADA_S)


def diferencas_da_reconstrucao(pasta: Path) -> list:
    if not (pasta / ".git").is_dir():
        return ["a pasta nao virou repositorio git"]
    rastreados = set(git(pasta, "-c", "core.quotePath=false", "ls-files").splitlines())
    diferencas = sorted(set(ARQUIVOS_DE_TESTE) ^ rastreados)
    for caminho, texto in ARQUIVOS_DE_TESTE.items():
        alvo = pasta / caminho
        if not alvo.is_file() or alvo.read_bytes() != texto.encode("utf-8"):
            diferencas.append(caminho)
    return diferencas


def testar() -> int:
    falhas = []

    def caso(rotulo, condicao, devolvido):
        if not condicao:
            falhas.append(FALHA_DO_CASO.format(rotulo, devolvido))

    pacote = pacote_com_a_camada(molde_sem_a_camada(Path(__file__).resolve()),
                                 ARQUIVOS_DE_TESTE)
    with tempfile.TemporaryDirectory(prefix="camada-em-um-arquivo-") as pasta:
        raiz = Path(pasta)
        em_lf = raiz / "em-lf.py"
        em_lf.write_bytes(pacote.encode("ascii"))
        feito = rodada(em_lf, raiz / "ida")
        caso("ida e volta: cada arquivo volta byte a byte, com acento e retorno "
             "de carro dentro, num repositorio git que rastreia so eles",
             feito.returncode == 0 and not diferencas_da_reconstrucao(raiz / "ida"),
             (feito.returncode, feito.stderr[-300:]))

        colado = raiz / "colado-no-windows.py"
        colado.write_bytes((chr(0xfeff) + pacote.replace("\n", "\r\n")).encode("utf-8"))
        feito = rodada(colado, raiz / "colado")
        caso("o pacote salvo em CRLF e com BOM, como sai de colar no Windows, "
             "reconstroi igual",
             feito.returncode == 0 and not diferencas_da_reconstrucao(raiz / "colado"),
             (feito.returncode, feito.stderr[-300:]))

        linha_do_fecho = pacote.rstrip("\n").rsplit("\n", 1)[1]
        cortado = raiz / "cortado.py"
        cortado.write_bytes(
            pacote[:-(len(linha_do_fecho) + TRECHO_CORTADO_DO_ULTIMO_DADO)].encode("ascii"))
        no_cortado = rodada(cortado, raiz / "cortada")
        alterado = raiz / "alterado.py"
        alterado.write_bytes(pacote.replace("de mentira", "de verdade").encode("ascii"))
        no_alterado = rodada(alterado, raiz / "alterada")
        caso("o pacote cortado no fim ou alterado no meio e recusado com o "
             "recado de copiar de novo, e nenhuma pasta nasce",
             no_cortado.returncode != 0 and "incompleto" in no_cortado.stderr
             and not (raiz / "cortada").exists()
             and no_alterado.returncode != 0 and "alterado" in no_alterado.stderr
             and not (raiz / "alterada").exists(),
             (no_cortado.returncode, no_cortado.stderr[-200:],
              no_alterado.returncode, no_alterado.stderr[-200:]))

        montar = raiz / "ida" / "montar.py"
        antes = montar.stat().st_mtime_ns
        de_novo = rodada(em_lf, raiz / "ida")
        alheia = raiz / "alheia"
        alheia.mkdir()
        (alheia / "meu.txt").write_text("meu", encoding="utf-8")
        na_alheia = rodada(em_lf, alheia)
        caso("de novo sobre a pasta em dia sai em dia sem regravar, e a pasta "
             "alheia e recusada intacta",
             de_novo.returncode == 0 and "ja esta" in de_novo.stdout
             and montar.stat().st_mtime_ns == antes
             and na_alheia.returncode != 0
             and sorted(p.name for p in alheia.iterdir()) == ["meu.txt"],
             (de_novo.returncode, de_novo.stdout[-200:], na_alheia.returncode))

    if falhas:
        for falha in falhas:
            print(falha)
        print(RESUMO_FALHOU.format(len(falhas), QUANTOS_CASOS))
        return 1
    print(RESUMO_OK.format(QUANTOS_CASOS))
    return 0


if __name__ == "__main__":
    for canal in (sys.stdout, sys.stderr):
        if hasattr(canal, "reconfigure"):
            canal.reconfigure(encoding="utf-8", errors="replace")
    if BANDEIRA_DE_TESTE in sys.argv:
        sys.exit(testar())
    sys.exit(reconstruir(Path(__file__).resolve(),
                         sys.argv[1] if len(sys.argv) > 1 else ""))

#[".agents/.claude-plugin/plugin.json", "{\"name\": \"atlas\", \"version\": \"0.1.0\", \"description\": \"Skills da camada atlas, empacotadas para o claude plugin eval.\", \"author\": {\"name\": \"atlas\"}}\n"]
#[".agents/auditor/auditor.py", "import argparse\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nDESCRICAO_DA_CLI = (\n    \"l\u00ea a pasta de evid\u00eancias de um trabalho e relata o que a execu\u00e7\u00e3o \"\n    \"provou, o que ela deixou por provar, e o que isso sugere\")\n\nAQUI = Path(__file__).resolve().parent\nINSTRUMENTO_QUE_ANCORA = \"verificar/verificar.py\"\n\n\ndef _achar_a_camada() -> Path:\n    for base in (AQUI.parent, *AQUI.parents):\n        if (base / INSTRUMENTO_QUE_ANCORA).is_file():\n            return base\n        if (base / \".agents\" / INSTRUMENTO_QUE_ANCORA).is_file():\n            return base / \".agents\"\n    return AQUI.parent\n\n\nVERIFICADOR = _achar_a_camada() / INSTRUMENTO_QUE_ANCORA\nGLOB_DE_EVIDENCIA = \"*.json\"\nNOME_DA_EVIDENCIA = re.compile(r\"^(\\d+)-(.+)-c(\\d+)\\.json$\")\nACUSACAO_ROTULADA = re.compile(r\"^ACUSA \\[([^\\]]+)\\]\")\nPREFIXO_DA_ACUSACAO = \"ACUSA \"\nPASTA_DA_JANELA = \"verificacoes\"\nARQUIVO_DO_AMBIENTE = \"ambiente.json\"\nVARIAVEIS_QUE_A_REEXECUCAO_RECEBE = (\"PROJETO\", \"ISSUE\", \"ASSUNTO\")\nLINHAS_DO_FIM = 12\n\nVEREDITO_SEGUE = \"segue\"\nVEREDITO_PARA = \"para\"\nVEREDITO_PERGUNTA = \"pergunta\"\nORIGEM_DO_MOTOR = \"encadeador\"\nBANDEIRA_DE_TESTE = \"--testar\"\nTEMPO_DA_VERIFICACAO = 900\n\nTIPO_DEFEITO = \"defeito\"\nTIPO_MELHORIA = \"melhoria\"\nACHADO_PROVA_NAO_REPRODUZ = \"prova-que-nao-reproduz\"\nACHADO_CICLO_REPETIDO = \"etapa-que-repete-ciclo\"\nACHADO_EVIDENCIA_SINTETICA = \"evidencia-escrita-pelo-motor\"\nACHADO_SEGUIU_SEM_PROVA = \"etapa-que-segue-sem-prova\"\nACHADO_EVIDENCIA_ILEGIVEL = \"evidencia-que-nao-abre\"\nACHADO_PROVA_SUPERADA = \"prova-superada-pelo-mundo\"\n\nTITULO_PROVADO = \"PROVADO \u2014 o que a execu\u00e7\u00e3o deixou no disco\"\nTITULO_ILEGIVEL = \"ILEG\u00cdVEL \u2014 n\u00e3o auditado, n\u00e3o \u00e9 caixa vazia\"\nTITULO_REEXECUCAO = \"RE-EXECU\u00c7\u00c3O \u2014 a prova ainda reproduz?\"\nTITULO_SUPOSTO = \"SUPOSTO \u2014 leitura, n\u00e3o fato\"\nLINHA_DA_ETAPA = \"  {:>3} {:<26} {:<9} ciclo {}/{}  {}\"\nLINHA_DO_TOTAL = \"  {:<30} {}\"\nLINHA_SIMPLES = \"  {}\"\nLINHA_ILEGIVEL = \"  {}: {}\"\nSEM_EVIDENCIA = \"Nenhuma evid\u00eancia em {} \u2014 nada a auditar.\"\nTUDO_ILEGIVEL = (\"Nenhuma evid\u00eancia leg\u00edvel em {} \u2014 {} arquivo(s) que n\u00e3o \"\n                 \"abrem, e isso \u00e9 n\u00e3o auditado, n\u00e3o \u00e9 caixa vazia:\")\nSEM_FORMA_DE_EVIDENCIA = \"JSON v\u00e1lido sem forma de evid\u00eancia: falta a etapa\"\nPASTA_INEXISTENTE = \"Pasta que n\u00e3o existe: {}\"\nCABECALHO = (\"\\nAUDITORIA DO TRABALHO {} \u2014 {} etapa(s) em {} arquivo(s), \"\n             \"{} ileg\u00edvel(is)\")\n\nSUPOSTO_PAROU_EM = (\"a execu\u00e7\u00e3o parou em {!r}: \u00e9 a \u00faltima etapa com veredito \"\n                    \"{} e nada depois dela ficou registrado\")\nSUPOSTO_PERGUNTOU = \"a execu\u00e7\u00e3o devolveu a decis\u00e3o em {!r} e ficou esperando\"\nSUPOSTO_REPETIU = (\"{} etapa(s) gastaram mais de um ciclo \u2014 {}. Etapa que \"\n                   \"repete \u00e9 etapa cujo crit\u00e9rio n\u00e3o estava claro na primeira \"\n                   \"passada\")\nSUPOSTO_SINTETICA = (\"{} evid\u00eancia(s) foram escritas pelo motor, n\u00e3o pela \"\n                     \"etapa ({}). Isso \u00e9 o motor dando nome a um estado que a \"\n                     \"etapa n\u00e3o conseguiu declarar\")\nSUPOSTO_ILEGIVEL = (\"{} arquivo(s) de evid\u00eancia n\u00e3o abriram \u2014 {}. O que est\u00e1 \"\n                    \"ali ficou fora de toda contagem acima: \u00e9 n\u00e3o auditado, \"\n                    \"n\u00e3o \u00e9 caixa vazia\")\nSUPOSTO_SEM_PROVA = (\"{} etapa(s) seguiram sem nenhum item provado \u2014 {}. \"\n                     \"Veredito que segue sem prova \u00e9 a regra 2 sendo \"\n                     \"contornada\")\nSUPOSTO_LIMPO = \"nada a apontar: toda etapa seguiu, com prova e num ciclo s\u00f3\"\nSUPOSTO_PROVA_NAO_REPRODUZ = (\"prova que n\u00e3o reproduz mais \u00e9 o achado \"\n                              \"mais forte desta auditoria: o comando e a sa\u00edda \"\n                              \"estavam declarados e agora d\u00e3o outra coisa. Ou o \"\n                              \"mundo mudou, ou a prova foi redigida em vez de colada\")\nSUPOSTO_PROVA_SUPERADA = (\"prova superada pelo mundo: {} prova(s) n\u00e3o \"\n                          \"reproduzem mais, e o disco mostra que reproduziram \"\n                          \"na hora da etapa \u2014 {}. O mundo andou depois da \"\n                          \"etapa; aqui n\u00e3o cabe falar em prova forjada\")\nSUPERADA_UMA = \"{} ({})\"\nMOTIVO_DA_JANELA = \"verificada na janela em {}\"\nMOTIVO_DO_CICLO = \"o ciclo {} da mesma etapa seguiu depois\"\nVERIFICADOR_AUSENTE = (\"verificador n\u00e3o encontrado em {} \u2014 a re-execu\u00e7\u00e3o n\u00e3o \"\n                       \"rodou, e isso \u00e9 n\u00e3o medido, n\u00e3o \u00e9 aprova\u00e7\u00e3o\")\nVERIFICADOR_OK = \"o verificador re-executou as provas e n\u00e3o acusou diverg\u00eancia\"\nVERIFICADOR_ACUSOU = \"o verificador acusou (sa\u00edda {}):\"\n\nRECUSA_DE_USO = 2\n\n\ndef evidencias_da_pasta(pasta: Path) -> tuple:\n    achadas, ilegiveis = [], []\n    for caminho in sorted(pasta.glob(GLOB_DE_EVIDENCIA)):\n        if not NOME_DA_EVIDENCIA.match(caminho.name):\n            continue\n        try:\n            dado = json.loads(caminho.read_text(encoding=\"utf-8\"))\n        except (OSError, ValueError) as erro:\n            ilegiveis.append((caminho, str(erro)))\n            continue\n        if isinstance(dado, dict) and dado.get(\"etapa\"):\n            achadas.append((caminho, dado))\n        else:\n            ilegiveis.append((caminho, SEM_FORMA_DE_EVIDENCIA))\n    return achadas, ilegiveis\n\n\ndef ordem_da_evidencia(caminho: Path) -> str:\n    achado = NOME_DA_EVIDENCIA.match(caminho.name)\n    return achado.group(1) if achado else \"?\"\n\n\ndef contar(evidencias: list, ilegiveis: list = ()) -> dict:\n    ciclos = [e for _, e in evidencias if (e.get(\"ciclo\") or {}).get(\"i\", 1) > 1]\n    sinteticas = [e for _, e in evidencias\n                  if e.get(\"origem\") == ORIGEM_DO_MOTOR]\n    sem_prova = [e for _, e in evidencias\n                 if e.get(\"veredito\") == VEREDITO_SEGUE and not e.get(\"provado\")]\n    return {\n        \"etapas\": len({e.get(\"etapa\") for _, e in evidencias}),\n        \"arquivos\": len(evidencias),\n        \"segue\": sum(1 for _, e in evidencias\n                     if e.get(\"veredito\") == VEREDITO_SEGUE),\n        \"para\": sum(1 for _, e in evidencias\n                    if e.get(\"veredito\") == VEREDITO_PARA),\n        \"pergunta\": sum(1 for _, e in evidencias\n                        if e.get(\"veredito\") == VEREDITO_PERGUNTA),\n        \"provas\": sum(len(e.get(\"provado\") or []) for _, e in evidencias),\n        \"repetidas\": [e[\"etapa\"] for e in ciclos],\n        \"sinteticas\": [e[\"etapa\"] for e in sinteticas],\n        \"sem_prova\": [e[\"etapa\"] for e in sem_prova],\n        \"ilegiveis\": [(str(caminho), erro) for caminho, erro in ilegiveis],\n    }\n\n\ndef linhas_da_acusacao(saida: str) -> list:\n    return [linha for linha in (saida or \"\").splitlines()\n            if linha.startswith(PREFIXO_DA_ACUSACAO)]\n\n\ndef acusadas(saida: str) -> list:\n    nomes = []\n    for linha in linhas_da_acusacao(saida):\n        rotulada = ACUSACAO_ROTULADA.match(linha)\n        if rotulada and rotulada.group(1) not in nomes:\n            nomes.append(rotulada.group(1))\n    return nomes\n\n\ndef registro_da_janela(pasta: Path, nome: str) -> dict:\n    try:\n        dado = json.loads((pasta / PASTA_DA_JANELA / nome)\n                          .read_text(encoding=\"utf-8\"))\n    except (OSError, ValueError):\n        return {}\n    return dado if isinstance(dado, dict) else {}\n\n\ndef ambiente_da_execucao(pasta: Path) -> dict:\n    try:\n        dado = json.loads((pasta / ARQUIVO_DO_AMBIENTE)\n                          .read_text(encoding=\"utf-8\"))\n    except (OSError, ValueError):\n        return dict(os.environ)\n    gravadas = dado.get(\"variaveis\") if isinstance(dado, dict) else None\n    if not isinstance(gravadas, dict):\n        return dict(os.environ)\n    return dict(os.environ, **{\n        nome: str(gravadas[nome])\n        for nome in VARIAVEIS_QUE_A_REEXECUCAO_RECEBE\n        if isinstance(gravadas.get(nome), (str, int))})\n\n\ndef _ciclo_que_seguiu_depois(evidencias: list, nome: str) -> str:\n    acusada = NOME_DA_EVIDENCIA.match(nome)\n    if not acusada:\n        return \"\"\n    for caminho, dado in evidencias:\n        outra = NOME_DA_EVIDENCIA.match(caminho.name)\n        if (outra and outra.group(2) == acusada.group(2)\n                and int(outra.group(3)) > int(acusada.group(3))\n                and dado.get(\"veredito\") == VEREDITO_SEGUE):\n            return outra.group(3)\n    return \"\"\n\n\ndef superacao(pasta: Path, evidencias: list, nome: str) -> str:\n    registro = registro_da_janela(pasta, nome)\n    if isinstance(registro.get(\"exit\"), int):\n        return (MOTIVO_DA_JANELA.format(registro.get(\"quando\") or \"?\")\n                if registro[\"exit\"] == 0 else \"\")\n    ciclo = _ciclo_que_seguiu_depois(evidencias, nome)\n    return MOTIVO_DO_CICLO.format(ciclo) if ciclo else \"\"\n\n\ndef julgar_a_janela(pasta: Path, evidencias: list, saida: str) -> dict:\n    superadas, fortes = [], []\n    for nome in acusadas(saida):\n        motivo = superacao(pasta, evidencias, nome)\n        if motivo:\n            superadas.append(SUPERADA_UMA.format(nome, motivo))\n        else:\n            fortes.append(nome)\n    return {\"superadas\": superadas, \"fortes\": fortes}\n\n\ndef _lido(texto: str, identidade: str = \"\", tipo: str = \"\") -> dict:\n    return {\"texto\": texto, \"id\": identidade, \"tipo\": tipo}\n\n\ndef lidos_da_execucao(evidencias: list, conta: dict,\n                      reproduz: bool = True, janela: dict = None) -> list:\n    lidos = []\n    superadas = (janela or {}).get(\"superadas\") or []\n    fortes = (janela or {}).get(\"fortes\") or []\n    if not reproduz and (fortes or not superadas):\n        lidos.append(_lido(SUPOSTO_PROVA_NAO_REPRODUZ,\n                           ACHADO_PROVA_NAO_REPRODUZ, TIPO_DEFEITO))\n    if not reproduz and superadas:\n        lidos.append(_lido(\n            SUPOSTO_PROVA_SUPERADA.format(len(superadas),\n                                          \", \".join(superadas)),\n            ACHADO_PROVA_SUPERADA, TIPO_MELHORIA))\n    if conta[\"ilegiveis\"]:\n        lidos.append(_lido(SUPOSTO_ILEGIVEL.format(\n            len(conta[\"ilegiveis\"]),\n            \", \".join(Path(caminho).name\n                      for caminho, _ in conta[\"ilegiveis\"])),\n            ACHADO_EVIDENCIA_ILEGIVEL, TIPO_DEFEITO))\n    ultima = evidencias[-1][1] if evidencias else {}\n    if ultima.get(\"veredito\") == VEREDITO_PARA:\n        lidos.append(_lido(SUPOSTO_PAROU_EM.format(ultima.get(\"etapa\"),\n                                                   VEREDITO_PARA)))\n    if ultima.get(\"veredito\") == VEREDITO_PERGUNTA:\n        lidos.append(_lido(SUPOSTO_PERGUNTOU.format(ultima.get(\"etapa\"))))\n    if conta[\"repetidas\"]:\n        lidos.append(_lido(SUPOSTO_REPETIU.format(\n            len(conta[\"repetidas\"]), \", \".join(conta[\"repetidas\"])),\n            ACHADO_CICLO_REPETIDO, TIPO_MELHORIA))\n    if conta[\"sinteticas\"]:\n        lidos.append(_lido(SUPOSTO_SINTETICA.format(\n            len(conta[\"sinteticas\"]), \", \".join(conta[\"sinteticas\"])),\n            ACHADO_EVIDENCIA_SINTETICA, TIPO_DEFEITO))\n    if conta[\"sem_prova\"]:\n        lidos.append(_lido(SUPOSTO_SEM_PROVA.format(\n            len(conta[\"sem_prova\"]), \", \".join(conta[\"sem_prova\"])),\n            ACHADO_SEGUIU_SEM_PROVA, TIPO_DEFEITO))\n    return lidos or [_lido(SUPOSTO_LIMPO)]\n\n\ndef supostos(evidencias: list, conta: dict, reproduz: bool = True,\n             janela: dict = None) -> list:\n    return [um[\"texto\"]\n            for um in lidos_da_execucao(evidencias, conta, reproduz, janela)]\n\n\ndef os_que_sabe_nomear(lidos: list) -> list:\n    return [um for um in lidos if um[\"id\"]]\n\n\ndef reexecutar(pasta: Path, cwd: str) -> tuple:\n    if not VERIFICADOR.is_file():\n        return None, VERIFICADOR_AUSENTE.format(VERIFICADOR)\n    comando = [sys.executable, str(VERIFICADOR), \"trabalho\", str(pasta)]\n    if cwd:\n        comando += [\"--cwd\", cwd]\n    try:\n        pronto = subprocess.run(comando, capture_output=True, text=True, encoding=\"utf-8\", errors=\"replace\",\n                                env=ambiente_da_execucao(pasta),\n                                timeout=TEMPO_DA_VERIFICACAO)\n    except (OSError, subprocess.SubprocessError) as erro:\n        return None, str(erro)\n    return pronto.returncode, (pronto.stdout + pronto.stderr).strip()\n\n\ndef auditar(pasta: Path, cwd: str = \"\") -> int:\n    return auditar_e_nomear(pasta, cwd)[0]\n\n\ndef auditar_e_nomear(pasta: Path, cwd: str = \"\") -> tuple:\n    if not pasta.is_dir():\n        print(PASTA_INEXISTENTE.format(pasta))\n        return 2, []\n    evidencias, ilegiveis = evidencias_da_pasta(pasta)\n    if not evidencias:\n        print(TUDO_ILEGIVEL.format(pasta, len(ilegiveis)) if ilegiveis\n              else SEM_EVIDENCIA.format(pasta))\n        for caminho, erro in ilegiveis:\n            print(LINHA_ILEGIVEL.format(caminho, erro))\n        return 2, []\n\n    conta = contar(evidencias, ilegiveis)\n    print(CABECALHO.format(pasta.name, conta[\"etapas\"], conta[\"arquivos\"],\n                           len(conta[\"ilegiveis\"])))\n\n    print(f\"\\n{TITULO_PROVADO}\")\n    for caminho, dado in evidencias:\n        ciclo = dado.get(\"ciclo\") or {}\n        faltas = dado.get(\"faltas\") or []\n        print(LINHA_DA_ETAPA.format(\n            ordem_da_evidencia(caminho), dado.get(\"etapa\", \"?\")[:26],\n            dado.get(\"veredito\", \"?\"), ciclo.get(\"i\", \"?\"),\n            ciclo.get(\"teto\", \"?\"),\n            f\"{len(faltas)} falta(s)\" if faltas else \"\"))\n    for rotulo, chave in ((\"seguiram\", \"segue\"), (\"pararam\", \"para\"),\n                          (\"perguntaram\", \"pergunta\"),\n                          (\"itens provados\", \"provas\")):\n        print(LINHA_DO_TOTAL.format(rotulo, conta[chave]))\n    print(LINHA_DO_TOTAL.format(\"ileg\u00edveis\", len(conta[\"ilegiveis\"])))\n\n    if conta[\"ilegiveis\"]:\n        print(f\"\\n{TITULO_ILEGIVEL}\")\n        for caminho, erro in conta[\"ilegiveis\"]:\n            print(LINHA_ILEGIVEL.format(caminho, erro))\n\n    print(f\"\\n{TITULO_REEXECUCAO}\")\n    codigo, saida = reexecutar(pasta, cwd)\n    janela = {}\n    if codigo is None:\n        print(LINHA_SIMPLES.format(saida))\n    elif codigo == 0:\n        print(LINHA_SIMPLES.format(VERIFICADOR_OK))\n    else:\n        janela = julgar_a_janela(pasta, evidencias, saida)\n        print(LINHA_SIMPLES.format(VERIFICADOR_ACUSOU.format(codigo)))\n        for linha in (linhas_da_acusacao(saida)\n                      or saida.split(\"\\n\")[-LINHAS_DO_FIM:]):\n            print(LINHA_SIMPLES.format(linha))\n\n    lidos = lidos_da_execucao(evidencias, conta, codigo in (0, None), janela)\n    print(f\"\\n{TITULO_SUPOSTO}\")\n    for lido in lidos:\n        print(LINHA_SIMPLES.format(lido[\"texto\"]))\n\n    houve_falha = (conta[\"para\"] > 0 or bool(conta[\"ilegiveis\"])\n                   or (codigo not in (0, None)))\n    return (1 if houve_falha else 0), os_que_sabe_nomear(lidos)\n\n\ndef _evidencia(etapa, veredito=VEREDITO_SEGUE, ciclo=1, provado=None,\n               origem=None, faltas=None) -> dict:\n    dado = {\"etapa\": etapa, \"trabalho\": \"t\", \"quando\": \"2000-01-01T00:00:00Z\",\n            \"veredito\": veredito, \"provado\": provado or [], \"suposto\": [],\n            \"faltas\": faltas or [], \"ciclo\": {\"i\": ciclo, \"teto\": 3}}\n    if origem:\n        dado[\"origem\"] = origem\n    return dado\n\n\ndef _escrever(pasta: Path, ordem, etapa, **troca) -> None:\n    ciclo = troca.get(\"ciclo\", 1)\n    alvo = pasta / f\"{ordem:02d}-{etapa}-c{ciclo}.json\"\n    alvo.write_text(json.dumps(_evidencia(etapa, **troca), ensure_ascii=False),\n                    encoding=\"utf-8\")\n\n\nFALSO_VERIFICADOR = \"\"\"import os\nimport sys\n\nsys.stdout.reconfigure(encoding=\"utf-8\")\nsys.stdout.write(os.environ[\"AUDITOR_TESTE_SAIDA\"])\nsys.exit(4)\n\"\"\"\n\nVERIFICADOR_QUE_RELATA_O_AMBIENTE = \"\"\"import os\nimport sys\n\nfor nome in (\"PROJETO\", \"GH_TOKEN\"):\n    sys.stdout.write(nome + \"=\" + os.environ.get(nome, \"<ausente>\") + chr(10))\nsys.exit(4)\n\"\"\"\nAMBIENTE_COM_SEGREDO_INFILTRADO = {\n    \"variaveis\": {\"PROJETO\": \"alvo-gravado\", \"ISSUE\": \"68\",\n                  \"ASSUNTO\": \"forja\", \"GH_TOKEN\": \"ghp_contrabando\"}}\nALVO_DO_SHELL = \"alvo-do-shell-que-nao-manda\"\nQUANDO_DA_JANELA = \"2000-01-02T00:00:00Z\"\n\n\ndef testar() -> int:\n    import contextlib\n    import io\n    import os\n    import tempfile\n    falhas, rodados = [], []\n\n    def caso(rotulo, condicao):\n        rodados.append(rotulo)\n        if not condicao:\n            falhas.append(rotulo)\n\n    def falado(*argumentos, **troca):\n        conversa = io.StringIO()\n        with contextlib.redirect_stdout(conversa):\n            codigo = auditar(*argumentos, **troca)\n        return codigo, conversa.getvalue()\n\n    def falado_e_nomeado(*argumentos, **troca):\n        with contextlib.redirect_stdout(io.StringIO()):\n            return auditar_e_nomear(*argumentos, **troca)\n\n    with tempfile.TemporaryDirectory(prefix=\"auditor-teste-\") as pasta:\n        vazia = Path(pasta) / \"vazia\"\n        vazia.mkdir()\n        caso(\"pasta sem evid\u00eancia n\u00e3o vira auditoria\",\n             auditar(vazia) == 2)\n        caso(\"pasta que n\u00e3o existe \u00e9 recusada\",\n             auditar(Path(pasta) / \"nao-existe\") == 2)\n\n        boa = Path(pasta) / \"boa\"\n        boa.mkdir()\n        _escrever(boa, 1, \"abrir\", provado=[{\"afirmacao\": \"a\", \"comando\": \"true\",\n                                             \"saida\": \"\"}])\n        _escrever(boa, 2, \"fechar\", provado=[{\"afirmacao\": \"b\", \"comando\": \"true\",\n                                              \"saida\": \"\"}])\n        evidencias, _ = evidencias_da_pasta(boa)\n        conta = contar(evidencias)\n        caso(\"conta as etapas e os itens provados\",\n             conta[\"etapas\"] == 2 and conta[\"provas\"] == 2)\n        caso(\"execu\u00e7\u00e3o limpa n\u00e3o gera suposto inventado\",\n             supostos(evidencias, conta) == [SUPOSTO_LIMPO])\n\n        suja = Path(pasta) / \"suja\"\n        suja.mkdir()\n        _escrever(suja, 1, \"tentar\", ciclo=2,\n                  provado=[{\"afirmacao\": \"a\", \"comando\": \"true\", \"saida\": \"\"}])\n        _escrever(suja, 2, \"seguir-sem-prova\")\n        _escrever(suja, 3, \"morrer\", veredito=VEREDITO_PARA,\n                  origem=ORIGEM_DO_MOTOR, faltas=[\"estourou\"])\n        evidencias, _ = evidencias_da_pasta(suja)\n        conta = contar(evidencias)\n        lidos = \" \".join(supostos(evidencias, conta))\n        caso(\"aponta a etapa que repetiu ciclo\", \"tentar\" in lidos)\n        caso(\"aponta a evid\u00eancia escrita pelo motor\", \"morrer\" in lidos)\n        caso(\"aponta quem seguiu sem prova nenhuma\",\n             \"seguir-sem-prova\" in lidos)\n        caso(\"diz onde a execu\u00e7\u00e3o parou\", SUPOSTO_PAROU_EM.split(\"{\")[0] in lidos)\n        caso(\"execu\u00e7\u00e3o que parou devolve sa\u00edda diferente de zero\",\n             auditar(suja) == 1)\n\n        perguntou = Path(pasta) / \"perguntou\"\n        perguntou.mkdir()\n        _escrever(perguntou, 1, \"decidir\", veredito=VEREDITO_PERGUNTA)\n        evidencias, _ = evidencias_da_pasta(perguntou)\n        caso(\"pergunta n\u00e3o \u00e9 falha: a execu\u00e7\u00e3o devolveu a decis\u00e3o\",\n             SUPOSTO_PERGUNTOU.split(\"{\")[0]\n             in \" \".join(supostos(evidencias, contar(evidencias))))\n\n        caso(\"a ordem sai do nome do arquivo\",\n             ordem_da_evidencia(Path(\"07-etapa-c1.json\")) == \"07\")\n        caso(\"nome fora do padr\u00e3o n\u00e3o derruba a leitura\",\n             ordem_da_evidencia(Path(\"solto.json\")) == \"?\")\n\n        com_estado = Path(pasta) / \"com-estado\"\n        com_estado.mkdir()\n        _escrever(com_estado, 1, \"unica\",\n                  provado=[{\"afirmacao\": \"a\", \"comando\": \"true\",\n                            \"saida\": \"\"}])\n        (com_estado / \"estado.json\").write_text(\n            json.dumps({\"etapa\": \"unica\", \"trabalho\": \"t\"}),\n            encoding=\"utf-8\")\n        caso(\"o estado do motor n\u00e3o \u00e9 lido como evid\u00eancia\",\n             len(evidencias_da_pasta(com_estado)[0]) == 1)\n        corrompida = Path(pasta) / \"corrompida\"\n        corrompida.mkdir()\n        _escrever(corrompida, 1, \"legivel\",\n                  provado=[{\"afirmacao\": \"a\", \"comando\": \"true\",\n                            \"saida\": \"\"}])\n        (corrompida / \"02-bytes-c1.json\").write_bytes(b\"\\xff\\xfe nao e utf-8\")\n        (corrompida / \"03-json-partido-c1.json\").write_text(\n            '{\"etapa\": \"meia', encoding=\"utf-8\")\n        (corrompida / \"04-lista-c1.json\").write_text(\n            json.dumps([\"isto n\u00e3o \u00e9 evid\u00eancia\"]), encoding=\"utf-8\")\n        (corrompida / \"05-sem-etapa-c1.json\").write_text(\n            json.dumps({\"veredito\": VEREDITO_SEGUE}), encoding=\"utf-8\")\n        legiveis, nao_abriram = evidencias_da_pasta(corrompida)\n        nomeados_ilegiveis = [c.name for c, _ in nao_abriram]\n        caso(\"bytes inv\u00e1lidos n\u00e3o somem: viram ileg\u00edvel com caminho e erro\",\n             len(legiveis) == 1\n             and all(erro for _, erro in nao_abriram)\n             and \"02-bytes-c1.json\" in nomeados_ilegiveis)\n        caso(\"JSON partido no meio n\u00e3o some: vira ileg\u00edvel nomeado\",\n             \"03-json-partido-c1.json\" in nomeados_ilegiveis)\n        caso(\"JSON v\u00e1lido sem forma de evid\u00eancia n\u00e3o \u00e9 descarte calado\",\n             [c.name for c, erro in nao_abriram\n              if erro == SEM_FORMA_DE_EVIDENCIA]\n             == [\"04-lista-c1.json\", \"05-sem-etapa-c1.json\"])\n        conta_ilegivel = contar(legiveis, nao_abriram)\n        caso(\"o ileg\u00edvel entra na contagem em vez de sumir dela\",\n             len(conta_ilegivel[\"ilegiveis\"]) == 4\n             and conta_ilegivel[\"arquivos\"] == 1)\n        dito_suposto = \" \".join(supostos(legiveis, conta_ilegivel))\n        caso(\"o ileg\u00edvel vira suposto que nomeia cada arquivo\",\n             sum(nome in dito_suposto for nome in nomeados_ilegiveis) == 4)\n\n        global VERIFICADOR\n        guardado = VERIFICADOR\n        VERIFICADOR = Path(pasta) / \"sem-verificador.py\"\n        try:\n            codigo, dito = falado(corrompida)\n            caso(\"o relat\u00f3rio nomeia cada ileg\u00edvel, um por linha\",\n                 sum(dito.count(LINHA_ILEGIVEL.format(\n                     corrompida / nome, \"\").rstrip())\n                     for nome in nomeados_ilegiveis) == 4)\n            caso(\"o cabe\u00e7alho conta os ileg\u00edveis junto com os arquivos\",\n                 CABECALHO.format(corrompida.name, 1, 1, 4) in dito)\n            caso(\"evid\u00eancia ileg\u00edvel sozinha j\u00e1 faz o auditor sair n\u00e3o zero\",\n                 codigo == 1)\n\n            toda_ilegivel = Path(pasta) / \"toda-ilegivel\"\n            toda_ilegivel.mkdir()\n            (toda_ilegivel / \"01-unica-c1.json\").write_bytes(b\"\\xff nao abre\")\n            codigo_ilegivel, dito_ilegivel = falado(toda_ilegivel)\n            codigo_vazia, dito_vazia = falado(vazia)\n            caso(\"pasta toda ileg\u00edvel n\u00e3o se confunde com pasta vazia\",\n                 dito_ilegivel != dito_vazia\n                 and SEM_EVIDENCIA.split(\"{\")[0] in dito_vazia\n                 and SEM_EVIDENCIA.split(\"{\")[0] not in dito_ilegivel)\n            caso(\"pasta toda ileg\u00edvel nomeia o arquivo e sai diferente de 0\",\n                 codigo_ilegivel != 0 and codigo_vazia != 0\n                 and \"01-unica-c1.json\" in dito_ilegivel)\n        finally:\n            VERIFICADOR = guardado\n\n        limpa, _ = evidencias_da_pasta(boa)\n        caso(\"prova que n\u00e3o reproduz vira o suposto mais forte\",\n             supostos(limpa, contar(limpa), reproduz=False)[0]\n             == SUPOSTO_PROVA_NAO_REPRODUZ)\n        caso(\"e quando reproduz, ele n\u00e3o aparece\",\n             SUPOSTO_PROVA_NAO_REPRODUZ\n             not in supostos(limpa, contar(limpa)))\n\n        janela = Path(pasta) / \"janela\"\n        janela.mkdir()\n        uma_prova = [{\"afirmacao\": \"a\", \"comando\": \"true\", \"saida\": \"\"}]\n        _escrever(janela, 1, \"superada\", provado=uma_prova)\n        _escrever(janela, 2, \"sem-registro\", provado=uma_prova)\n        _escrever(janela, 3, \"acusou-na-janela\", provado=uma_prova)\n        _escrever(janela, 4, \"repetida\", ciclo=1, provado=uma_prova)\n        _escrever(janela, 4, \"repetida\", ciclo=2, provado=uma_prova)\n        (janela / PASTA_DA_JANELA).mkdir()\n        for nome, saiu in ((\"01-superada-c1.json\", 0),\n                           (\"03-acusou-na-janela-c1.json\", 4)):\n            (janela / PASTA_DA_JANELA / nome).write_text(\n                json.dumps({\"alvo\": nome, \"quando\": QUANDO_DA_JANELA,\n                            \"exit\": saiu}), encoding=\"utf-8\")\n        acusou = \"\\n\".join(\n            f\"ACUSA [{nome}] sa\u00edda diverge em 'git log': o mundo andou\"\n            for nome in (\"01-superada-c1.json\", \"02-sem-registro-c1.json\",\n                         \"03-acusou-na-janela-c1.json\",\n                         \"04-repetida-c1.json\")) + \"\\n\\n4 acusa\u00e7\u00f5es.\"\n        de_janela, _ = evidencias_da_pasta(janela)\n        julgado = julgar_a_janela(janela, de_janela, acusou)\n        caso(\"a acusa\u00e7\u00e3o diz de qual evid\u00eancia ela \u00e9, sem repetir nome\",\n             acusadas(acusou + \"\\n\" + acusou)\n             == [\"01-superada-c1.json\", \"02-sem-registro-c1.json\",\n                 \"03-acusou-na-janela-c1.json\", \"04-repetida-c1.json\"])\n        caso(\"registro de janela com exit 0 \u00e9 prova superada, e cita o quando\",\n             SUPERADA_UMA.format(\"01-superada-c1.json\",\n                                 MOTIVO_DA_JANELA.format(QUANDO_DA_JANELA))\n             in julgado[\"superadas\"])\n        caso(\"ciclo mais novo da mesma etapa que seguiu tamb\u00e9m \u00e9 supera\u00e7\u00e3o\",\n             SUPERADA_UMA.format(\"04-repetida-c1.json\",\n                                 MOTIVO_DO_CICLO.format(\"2\"))\n             in julgado[\"superadas\"])\n        caso(\"registro de janela ausente mant\u00e9m o achado forte\",\n             \"02-sem-registro-c1.json\" in julgado[\"fortes\"])\n        caso(\"registro de janela que j\u00e1 acusou na hora mant\u00e9m o achado forte\",\n             \"03-acusou-na-janela-c1.json\" in julgado[\"fortes\"])\n        dito_janela = supostos(de_janela, contar(de_janela), reproduz=False,\n                               janela=julgado)\n        caso(\"prova superada vira achado pr\u00f3prio, ao lado do achado forte\",\n             any(SUPOSTO_PROVA_SUPERADA.split(\"{\")[0] in um\n                 for um in dito_janela)\n             and SUPOSTO_PROVA_NAO_REPRODUZ in dito_janela)\n        so_superadas = julgar_a_janela(\n            janela, de_janela, \"ACUSA [01-superada-c1.json] sa\u00edda diverge\")\n        caso(\"acusa\u00e7\u00e3o toda superada tira a frase de forja do relat\u00f3rio\",\n             SUPOSTO_PROVA_NAO_REPRODUZ\n             not in supostos(de_janela, contar(de_janela), reproduz=False,\n                             janela=so_superadas))\n        caso(\"prova superada pelo mundo \u00e9 achado de melhoria, nomeado\",\n             {um[\"id\"]: um[\"tipo\"] for um in os_que_sabe_nomear(\n                 lidos_da_execucao(de_janela, contar(de_janela),\n                                   reproduz=False, janela=julgado))}\n             .get(ACHADO_PROVA_SUPERADA) == TIPO_MELHORIA)\n\n        falso_verificador = Path(pasta) / \"falso_verificador.py\"\n        falso_verificador.write_text(FALSO_VERIFICADOR, encoding=\"utf-8\")\n        longe_do_fim = (\"ACUSA [01-superada-c1.json] sa\u00edda diverge em \"\n                        \"'git log': o mundo andou\")\n        os.environ[\"AUDITOR_TESTE_SAIDA\"] = \"\\n\".join(\n            [longe_do_fim] + [f\"linha de enchimento {n}\" for n in range(20)])\n        VERIFICADOR = falso_verificador\n        try:\n            _, relato = falado(janela)\n            caso(\"acusa\u00e7\u00e3o longe do fim n\u00e3o \u00e9 cortada do relat\u00f3rio\",\n                 longe_do_fim in relato)\n            caso(\"e o relat\u00f3rio fecha a supera\u00e7\u00e3o citando o quando da janela\",\n                 SUPOSTO_PROVA_SUPERADA.split(\"{\")[0] in relato\n                 and QUANDO_DA_JANELA in relato)\n        finally:\n            VERIFICADOR = guardado\n            os.environ.pop(\"AUDITOR_TESTE_SAIDA\", None)\n\n        com_ambiente = Path(pasta) / \"com-ambiente\"\n        com_ambiente.mkdir()\n        _escrever(com_ambiente, 1, \"abrir\",\n                  provado=[{\"afirmacao\": \"a\", \"comando\": \"true\", \"saida\": \"\"}])\n        gravado = com_ambiente / ARQUIVO_DO_AMBIENTE\n        gravado.write_text(json.dumps(AMBIENTE_COM_SEGREDO_INFILTRADO),\n                           encoding=\"utf-8\")\n        relator = Path(pasta) / \"relator_do_ambiente.py\"\n        relator.write_text(VERIFICADOR_QUE_RELATA_O_AMBIENTE,\n                           encoding=\"utf-8\")\n        chamariz = os.environ.get(\"PROJETO\")\n        token_de_quem_audita = os.environ.pop(\"GH_TOKEN\", None)\n        os.environ[\"PROJETO\"] = ALVO_DO_SHELL\n        VERIFICADOR = relator\n        try:\n            _, com_gravado = falado(com_ambiente)\n            caso(\"a re-execu\u00e7\u00e3o recebe o PROJETO que a execu\u00e7\u00e3o gravou, \"\n                 \"n\u00e3o o do shell que audita\",\n                 \"PROJETO=alvo-gravado\" in com_gravado)\n            caso(\"ambiente gravado s\u00f3 entrega o que a lista permite: segredo \"\n                 \"que apare\u00e7a no arquivo n\u00e3o chega \u00e0 re-execu\u00e7\u00e3o\",\n                 \"GH_TOKEN=<ausente>\" in com_gravado)\n            gravado.unlink()\n            _, sem_gravado = falado(com_ambiente)\n            caso(\"evid\u00eancia sem ambiente gravado re-executa como antes\",\n                 f\"PROJETO={ALVO_DO_SHELL}\" in sem_gravado)\n        finally:\n            VERIFICADOR = guardado\n            os.environ.pop(\"PROJETO\", None)\n            if chamariz is not None:\n                os.environ[\"PROJETO\"] = chamariz\n            if token_de_quem_audita is not None:\n                os.environ[\"GH_TOKEN\"] = token_de_quem_audita\n\n        evidencias, _ = evidencias_da_pasta(suja)\n        conta = contar(evidencias)\n        nomeados = os_que_sabe_nomear(\n            lidos_da_execucao(evidencias, conta, reproduz=False))\n        porid = {um[\"id\"]: um[\"tipo\"] for um in nomeados}\n        caso(\"prova que n\u00e3o reproduz \u00e9 achado de defeito, nomeado\",\n             porid.get(ACHADO_PROVA_NAO_REPRODUZ) == TIPO_DEFEITO)\n        caso(\"etapa que repetiu ciclo \u00e9 achado de melhoria\",\n             porid.get(ACHADO_CICLO_REPETIDO) == TIPO_MELHORIA)\n        caso(\"evid\u00eancia escrita pelo motor \u00e9 achado de defeito\",\n             porid.get(ACHADO_EVIDENCIA_SINTETICA) == TIPO_DEFEITO)\n        caso(\"etapa que seguiu sem prova \u00e9 achado de defeito\",\n             porid.get(ACHADO_SEGUIU_SEM_PROVA) == TIPO_DEFEITO)\n        nomeados_do_ilegivel = os_que_sabe_nomear(lidos_da_execucao(\n            legiveis, contar(legiveis, nao_abriram)))\n        caso(\"evid\u00eancia que n\u00e3o abre \u00e9 achado de defeito, nomeado\",\n             {um[\"id\"]: um[\"tipo\"] for um in nomeados_do_ilegivel}\n             .get(ACHADO_EVIDENCIA_ILEGIVEL) == TIPO_DEFEITO)\n        caso(\"execu\u00e7\u00e3o que parou n\u00e3o vira achado: fica s\u00f3 impressa\",\n             len(nomeados) == 4\n             and SUPOSTO_PAROU_EM.split(\"{\")[0]\n             in \" \".join(supostos(evidencias, conta, reproduz=False)))\n\n        limpa, _ = evidencias_da_pasta(boa)\n        caso(\"execu\u00e7\u00e3o limpa n\u00e3o promove nada\",\n             os_que_sabe_nomear(\n                 lidos_da_execucao(limpa, contar(limpa))) == [])\n\n        de_outro, _ = evidencias_da_pasta(perguntou)\n        caso(\"execu\u00e7\u00e3o que perguntou tamb\u00e9m n\u00e3o vira achado\",\n             os_que_sabe_nomear(\n                 lidos_da_execucao(de_outro, contar(de_outro))) == [])\n\n        codigo, nomeados_da_suja = falado_e_nomeado(suja)\n        caso(\"auditar_e_nomear devolve o c\u00f3digo da auditoria e os \"\n             \"achados que sabe nomear, para quem promove fora daqui\",\n             codigo == 1 and len(nomeados_da_suja) == 4)\n        saida_da_suja = io.StringIO()\n        with contextlib.redirect_stdout(saida_da_suja):\n            auditar(suja)\n        caso(\"o auditor que viaja n\u00e3o fala em promo\u00e7\u00e3o: verifica e acusa\",\n             \"PROMOVIDO\" not in saida_da_suja.getvalue())\n        bandeira = subprocess.run(\n            [sys.executable, str(Path(__file__).resolve()), str(suja),\n             \"--promover\"], capture_output=True, text=True,\n             encoding=\"utf-8\", errors=\"replace\")\n        caso(\"--promover n\u00e3o existe no auditor: rodar com a bandeira \"\n             \"devolve erro de uso, n\u00e3o promo\u00e7\u00e3o desligada\",\n             bandeira.returncode == RECUSA_DE_USO\n             and \"--promover\" in bandeira.stderr)\n\n    total = len(rodados)\n    if falhas:\n        for falha in falhas:\n            print(f\"  [{falha}]\")\n        print(f\"FALHOU: {len(falhas)} de {total} casos\")\n        return 1\n    print(f\"OK: {total} casos \u2014 leitura da execu\u00e7\u00e3o, contagem e suposto\")\n    return 0\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser(description=DESCRICAO_DA_CLI)\n    ap.add_argument(\"pasta\", help=\"a pasta de evid\u00eancias de um trabalho\")\n    ap.add_argument(\"--cwd\", default=\"\",\n                    help=\"onde re-executar as provas (padr\u00e3o: aqui)\")\n    a = ap.parse_args()\n    return auditar(Path(a.pasta), a.cwd)\n\n\nif __name__ == \"__main__\":\n    for canal in (sys.stdin, sys.stdout, sys.stderr):\n        if not getattr(canal, \"closed\", True) and hasattr(canal, \"reconfigure\"):\n            canal.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    sys.exit(testar() if BANDEIRA_DE_TESTE in sys.argv else main())\n"]
#[".agents/caixa/caixa.py", "import argparse\nimport json\nimport os\nimport re\nimport sys\nfrom datetime import date\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"gh\"))\nimport gh\n\nDESCRICAO_DA_CLI = (\n    \"p\u00f5e, atualiza e poda linha no quadro \u2014 a caixa permanente onde defeito \"\n    \"e melhoria moram juntos, cada linha com a etiqueta do seu tipo. Mesma \"\n    \"identidade, mesma linha: o quadro n\u00e3o vira log. O relat\u00f3rio da rodada \"\n    \"n\u00e3o \u00e9 linha: reescreve o bloco dele no corpo da caixa, o \u00faltimo por cima \"\n    \"do anterior. O que espera pelo dono (`--seu`) abre um coment\u00e1rio que o \"\n    \"marca \u2014 coment\u00e1rio \u00e9 conversa com ele, e mais nada\")\n\nBANDEIRA_DE_TESTE = \"--testar\"\n\nMARCA_ABRE = \"<!-- escrito pelo executor de roteiros -->\"\nMARCA_FECHA = \"<!-- /escrito pelo executor de roteiros -->\"\nNOME_DO_BLOCO_DO_RELATORIO = \"relatorio de rodada do executor de roteiros\"\nTITULO_DO_RELATORIO = \"## Relat\u00f3rio da rodada \u2014 o \u00faltimo, reescrito a cada rodada\"\nSEPARADOR_DO_ITEM = \"|\"\nENDERECO = re.compile(r\"https?://\\S+\")\nLINHA_DO_QUE_ESPERA = \"- {texto}\"\nLINHA_DO_QUE_ESPERA_COM_LINK = \"- {texto} \u2014 {link}\"\nCHAMADA_DO_DONO = (\"a rodada deixou isto para voc\u00ea:\\n\\n{itens}\\n\\nO relat\u00f3rio \"\n                   \"inteiro est\u00e1 no corpo desta issue.\")\n\nDEFEITO = \"defeito\"\nMELHORIA = \"melhoria\"\nTIPOS = (DEFEITO, MELHORIA)\nCAMPO_DA_CAIXA = {DEFEITO: \"defeitos\", MELHORIA: \"melhorias\"}\nPODA = \"podar\"\nRELATO = \"relatar\"\n\nSEPARADOR = \" \u00b7 visto em \"\nLIGA_ASSUNTO_AO_CORPO = \" \u2014 \"\nLINHA_DO_ACHADO = \"- **{id}** `{tipo}` \u2014 {assunto}\" + SEPARADOR + \"{quando}\"\nLEITURA_DA_LINHA = re.compile(\n    r\"^- \\*\\*(?P<id>[a-z0-9][a-z0-9-]*)\\*\\* `(?P<tipo>\"\n    + \"|\".join(TIPOS) + r\")` \u2014 (?P<assunto>.+?)\"\n    + re.escape(SEPARADOR) + r\"(?P<quando>\\d{4}-\\d{2}-\\d{2})$\")\nCOMECO_DA_LINHA = re.compile(r\"^- \\*\\*\")\nPADRAO_DA_IDENTIDADE = re.compile(r\"^[a-z0-9][a-z0-9-]*$\")\nPADRAO_DA_DATA = re.compile(r\"^\\d{4}-\\d{2}-\\d{2}$\")\nESPACO_DEMAIS = re.compile(r\"\\s+\")\nPALAVRA_COM_DIGITO_COLADO = re.compile(r\"\\S*(?:[^\\W\\d_]\\d|\\d[^\\W\\d_])\\S*\")\nTRECHO_QUE_NAO_SE_LE = re.compile(r\"`[^`]*`|https?://\\S+\")\nAVISO_DE_DIGITO_COLADO = (\n    \"AVISO: {quantas} palavra(s) com d\u00edgito colado a letra \u2014 {exemplos}. \"\n    \"Se \u00e9 engano de digita\u00e7\u00e3o, corrija antes de gravar; se \u00e9 sigla ou \"\n    \"unidade, siga.\\n\")\n\nRECUSA_IDENTIDADE = (\n    \"erro de uso: a identidade {valor!r} n\u00e3o serve. Ela \u00e9 a chave que faz o \"\n    \"mesmo achado virar UMA linha entre rodadas \u2014 use min\u00fasculas, d\u00edgitos e \"\n    \"h\u00edfen, e nomeie o ASSUNTO, nunca a ocorr\u00eancia\")\nRECUSA_SEM_ASSUNTO = (\n    \"erro de uso: --assunto vazio. A linha precisa dizer o que \u00e9, ou o \"\n    \"quadro guarda uma chave que ningu\u00e9m entende\")\nRECUSA_DATA = (\n    \"erro de uso: --quando {valor!r} n\u00e3o \u00e9 uma data AAAA-MM-DD\")\nRECUSA_SEM_BLOCO = (\n    \"erro de ambiente: o corpo da caixa n\u00e3o tem o bloco marcado. O \"\n    \"instrumento s\u00f3 escreve entre {abre} e {fecha} \u2014 sem os dois ele n\u00e3o \"\n    \"escreve nada, para n\u00e3o apagar texto que gente p\u00f4s \u00e0 m\u00e3o\")\nRECUSA_LINHA_QUE_NAO_LEIO = (\n    \"erro de ambiente: a caixa {issue} tem no bloco uma linha que eu n\u00e3o sei \"\n    \"ler, e reescrever o bloco a apagaria. Passe-a para o formato de hoje \"\n    \"({formato}) e rode de novo. A primeira que achei: {linha}\")\nRECUSA_LINHA_QUE_NAO_EXISTE = (\n    \"erro de uso: n\u00e3o achei a linha {id} no quadro da(s) caixa(s) {issues}. \"\n    \"Poda-se o que est\u00e1 l\u00e1 \u2014 veja a identidade e rode de novo\")\nRECUSA_SEM_CORPO = (\n    \"erro de uso: --corpo vazio. O relat\u00f3rio \u00e9 o bloco inteiro no corpo da \"\n    \"caixa: sem texto eu n\u00e3o escrevo nada nela\")\nRECUSA_SEU_SEM_LINK = (\n    \"erro de uso: `--seu` sem link: `{item}`. O que espera pelo dono carrega \"\n    \"o endere\u00e7o que o abre \u2014 n\u00famero solto obriga a garimpar\")\n\nARQUIVO_DO_EXECUTOR = \"nucleo/executor.json\"\nCAMPO_DAS_CAIXAS = \"caixas\"\nCAMPO_DAS_ISSUES = \"issues\"\nCAMPO_DO_REPOSITORIO = \"repositorio\"\nCAMPO_DA_CONTA = \"conta_gh\"\nMARCA_DE_VALOR_POR_PREENCHER = \"${\"\nTENTATIVAS_DE_GRAVACAO = 3\n\nRECUSA_TIPO = \"erro de uso: tipo {valor!r} n\u00e3o existe. Os que existem: {tipos}\"\nRECUSA_QUADRO = (\n    \"erro de uso: --quadro {valor!r} n\u00e3o \u00e9 n\u00famero de issue. Aponte o \"\n    \"instrumento para o quadro de outro assunto com o n\u00famero dele \u2014 o \"\n    \"reposit\u00f3rio e a conta continuam vindo da configura\u00e7\u00e3o, porque o quadro \"\n    \"do cliente nasce no mesmo reposit\u00f3rio\")\nRECUSA_SEM_CONFIGURACAO = (\n    \"erro de ambiente: n\u00e3o li {alvo} ({erro}). \u00c9 l\u00e1 que moram os n\u00fameros das \"\n    \"caixas, e \u00e9 por ele ser local que eles n\u00e3o entram em texto rastreado\")\nRECUSA_SEM_CAIXAS = (\n    \"erro de ambiente: {alvo} n\u00e3o declara {campo}. Declare {campo}.defeitos \"\n    \"e {campo}.melhorias, cada um com o n\u00famero da sua issue permanente \u2014 sem \"\n    \"isso n\u00e3o escrevo em lugar nenhum, e n\u00e3o invento issue\")\nRECUSA_SEM_O_TIPO = (\n    \"erro de ambiente: {alvo} n\u00e3o declara {campo}.{qual}, que \u00e9 o n\u00famero da \"\n    \"caixa de {qual} \u2014 sem ele n\u00e3o escrevo em lugar nenhum\")\nRECUSA_SEM_REPOSITORIO = (\n    \"erro de ambiente: {alvo} n\u00e3o declara {campo}.{qual}, e sem ele n\u00e3o sei \"\n    \"em que reposit\u00f3rio a caixa mora\")\nFALHA_AO_LER = \"erro de ambiente: n\u00e3o li a caixa {issue} \u2014 {motivo}\"\nFALHA_AO_GRAVAR = \"erro de ambiente: n\u00e3o gravei na caixa {issue} \u2014 {motivo}\"\nFALHA_AO_RELATAR = (\n    \"erro de ambiente: n\u00e3o gravei o relat\u00f3rio na caixa {issue} \u2014 {motivo}. \"\n    \"Nada foi escrito: o quadro n\u00e3o mudou\")\nNAO_ESTA_LA = (\n    \"erro de ambiente: gravei na caixa {issue} e reli, e a linha {id} N\u00c3O \"\n    \"est\u00e1 l\u00e1. Duas sess\u00f5es escrevendo ao mesmo tempo \u00e9 a explica\u00e7\u00e3o mais \"\n    \"prov\u00e1vel: quem grava por \u00faltimo vence. Rode de novo e confesse isto na \"\n    \"evid\u00eancia\")\nAINDA_ESTA_LA = (\n    \"erro de ambiente: podei na caixa {issue} e reli, e a linha {id} AINDA \"\n    \"est\u00e1 l\u00e1. Rode de novo e confesse isto na evid\u00eancia\")\n\nRECADO_POSTO = \"posto na caixa {issue}: {id}\"\nRECADO_ATUALIZADO = \"atualizado na caixa {issue}: {id}\"\nRECADO_JA_ESTAVA = \"j\u00e1 estava igual na caixa {issue}: {id} \u2014 n\u00e3o regravei\"\nRECADO_DO_ENSAIO = \"ensaio \u2014 o bloco da caixa {issue} ficaria assim:{miolo}\"\nRECADO_PODADO = (\n    \"podado do quadro da caixa {issue}: {id} \u2014 o corpo n\u00e3o guarda \"\n    \"fechamento; o motivo mora no commit e no hist\u00f3rico em disco:\\n\"\n    \"{registro}\")\nRECADO_DO_ENSAIO_DA_PODA = (\n    \"ensaio \u2014 a linha {id} sairia do quadro da caixa {issue}; o registro, \"\n    \"que vai ao commit e n\u00e3o ao corpo, seria:\\n{registro}\")\nRECADO_RELATADO = \"relat\u00f3rio reescrito no bloco dele, no corpo da caixa {issue}\"\nRECADO_CHAMOU_O_DONO = (\"coment\u00e1rio na caixa {issue} chamando o dono: {quantos} \"\n                        \"item(ns) espera(m) por ele\")\nFALHA_AO_CHAMAR_O_DONO = (\n    \"erro de ambiente: o relat\u00f3rio est\u00e1 no corpo da caixa {issue}, mas o \"\n    \"coment\u00e1rio ao dono n\u00e3o subiu \u2014 {motivo}. Rode de novo: o bloco igual n\u00e3o \"\n    \"se regrava, e s\u00f3 o coment\u00e1rio sai\")\nRECADO_DO_ENSAIO_DO_RELATO = (\n    \"ensaio \u2014 o relat\u00f3rio reescreveria o bloco dele no corpo da caixa \"\n    \"{issue}, e seria:\\n{corpo}\")\nRECADO_DO_ENSAIO_DA_CHAMADA = (\n    \"\\n\\ne o coment\u00e1rio ao dono, com a marca da configura\u00e7\u00e3o local, seria:\\n\"\n    \"{chamada}\")\n\nREGISTRO_DA_PODA = \"- {quando} \u00b7 podado: **{id}** `{tipo}`\"\nMOTIVO_DA_PODA = \" \u00b7 motivo: {motivo}\"\n\nAJUDA_ACAO = (\"em que caixa a linha entra, `\" + PODA + \"` para tirar a \"\n              \"linha do quadro, ou `\" + RELATO + \"` para reescrever o bloco \"\n              \"do relat\u00f3rio da rodada no corpo\")\nAJUDA_ID = \"a identidade est\u00e1vel do achado, em kebab min\u00fasculo\"\nAJUDA_ASSUNTO = \"o que a linha diz \u2014 o assunto, nunca a ocorr\u00eancia\"\nAJUDA_MOTIVO = (\"por que a linha saiu \u2014 sai no recado da poda, para o commit; \"\n                \"o corpo n\u00e3o o guarda\")\nAJUDA_QUANDO = \"a data do avistamento (padr\u00e3o: hoje)\"\nAJUDA_CORPO = (\"em `\" + RELATO + \"`, o relat\u00f3rio inteiro, que reescreve o \"\n               \"bloco dele no corpo; em defeito e melhoria, o detalhe que \"\n               \"entra na linha atr\u00e1s do assunto \u2014 nunca \u00e9 descartado\")\nAJUDA_SEU = (\"em `\" + RELATO + \"`, `o que|link` por item que espera pelo \"\n             \"dono: abre um coment\u00e1rio que o marca; repita a bandeira\")\nAJUDA_CWD = \"a raiz onde mora \" + ARQUIVO_DO_EXECUTOR + \" (padr\u00e3o: aqui)\"\nAJUDA_ENSAIO = \"mostra o que subiria, sem escrever na caixa\"\nAJUDA_QUADRO = (\"n\u00famero da issue do quadro, quando n\u00e3o for o declarado na \"\n                \"configura\u00e7\u00e3o \u2014 \u00e9 assim que um assunto com quadro pr\u00f3prio \"\n                \"recebe as linhas dele\")\n\n\ndef identidade_serve(valor) -> bool:\n    return bool(valor and PADRAO_DA_IDENTIDADE.match(valor))\n\n\ndef na_linha(texto: str) -> str:\n    return ESPACO_DEMAIS.sub(\" \", (texto or \"\").strip())\n\n\ndef achado(tipo: str, identidade: str, assunto: str, quando: str,\n           corpo: str = \"\") -> dict:\n    return {\"id\": identidade, \"tipo\": tipo,\n            \"assunto\": na_linha(assunto_com_o_corpo(assunto, corpo)),\n            \"quando\": quando}\n\n\ndef assunto_com_o_corpo(assunto: str, corpo: str) -> str:\n    if not (corpo or \"\").strip():\n        return assunto\n    return assunto + LIGA_ASSUNTO_AO_CORPO + corpo\n\n\ndef partes_do_corpo(corpo: str) -> tuple:\n    return gh.partes_do_bloco(corpo, MARCA_ABRE, MARCA_FECHA)\n\n\ndef e_achado(item) -> bool:\n    return isinstance(item, dict)\n\n\ndef so_espaco(item) -> bool:\n    return not e_achado(item) and not item.strip()\n\n\ndef itens_do_miolo(miolo: str) -> list:\n    itens = []\n    for linha in miolo.splitlines():\n        encontrado = LEITURA_DA_LINHA.match(linha.strip())\n        itens.append(encontrado.groupdict() if encontrado else linha)\n    while itens and so_espaco(itens[0]):\n        itens.pop(0)\n    while itens and so_espaco(itens[-1]):\n        itens.pop()\n    return itens\n\n\ndef achados_do_miolo(miolo: str) -> list:\n    return [item for item in itens_do_miolo(miolo) if e_achado(item)]\n\n\ndef linhas_que_nao_leio(miolo: str) -> list:\n    perdidas = []\n    for linha in miolo.splitlines():\n        limpa = linha.strip()\n        if COMECO_DA_LINHA.match(limpa) and not LEITURA_DA_LINHA.match(limpa):\n            perdidas.append(limpa)\n    return perdidas\n\n\ndef o_mesmo_achado(item, identidade: str) -> bool:\n    return e_achado(item) and item[\"id\"] == identidade\n\n\ndef com_o_achado(itens: list, novo: dict) -> list:\n    trocados = [dict(novo) if o_mesmo_achado(item, novo[\"id\"]) else item\n                for item in itens]\n    if not any(o_mesmo_achado(item, novo[\"id\"]) for item in itens):\n        trocados.append(dict(novo))\n    return trocados\n\n\ndef miolo_com(itens: list) -> str:\n    if not itens:\n        return \"\\n\"\n    return \"\\n\" + \"\".join(\n        (LINHA_DO_ACHADO.format(**item) if e_achado(item) else item) + \"\\n\"\n        for item in itens)\n\n\ndef corpo_com(corpo: str, novo: dict) -> str:\n    partes = partes_do_corpo(corpo)\n    if not partes:\n        return \"\"\n    antes, miolo, depois = partes\n    return antes + miolo_com(com_o_achado(itens_do_miolo(miolo), novo)) \\\n        + depois\n\n\ndef corpo_sem(corpo: str, identidade: str) -> str:\n    partes = partes_do_corpo(corpo)\n    if not partes:\n        return \"\"\n    antes, miolo, depois = partes\n    sobrando = [item for item in itens_do_miolo(miolo)\n                if not o_mesmo_achado(item, identidade)]\n    return antes + miolo_com(sobrando) + depois\n\n\ndef preenchido(valor) -> bool:\n    if valor is None or valor == \"\":\n        return False\n    return MARCA_DE_VALOR_POR_PREENCHER not in str(valor)\n\n\ndef endereco_da_caixa(tipo: str, cwd: str = \"\", quadro: str = \"\") -> tuple:\n    if tipo not in TIPOS:\n        return {}, RECUSA_TIPO.format(valor=tipo, tipos=\", \".join(TIPOS))\n    pedido = str(quadro).strip()\n    if quadro and not (pedido.isascii() and pedido.isdigit()):\n        return {}, RECUSA_QUADRO.format(valor=quadro)\n    alvo = (Path(cwd) if cwd else Path.cwd()) / ARQUIVO_DO_EXECUTOR\n    try:\n        dado = json.loads(alvo.read_text(encoding=\"utf-8\"))\n    except (OSError, ValueError) as erro:\n        return {}, RECUSA_SEM_CONFIGURACAO.format(alvo=ARQUIVO_DO_EXECUTOR,\n                                                  erro=erro)\n    caixas = dado.get(CAMPO_DAS_CAIXAS) if isinstance(dado, dict) else None\n    if not isinstance(caixas, dict):\n        return {}, RECUSA_SEM_CAIXAS.format(alvo=ARQUIVO_DO_EXECUTOR,\n                                            campo=CAMPO_DAS_CAIXAS)\n    qual = CAMPO_DA_CAIXA[tipo]\n    if not preenchido(caixas.get(qual)):\n        return {}, RECUSA_SEM_O_TIPO.format(alvo=ARQUIVO_DO_EXECUTOR,\n                                            campo=CAMPO_DAS_CAIXAS, qual=qual)\n    issues = dado.get(CAMPO_DAS_ISSUES)\n    issues = issues if isinstance(issues, dict) else {}\n    if not preenchido(issues.get(CAMPO_DO_REPOSITORIO)):\n        return {}, RECUSA_SEM_REPOSITORIO.format(alvo=ARQUIVO_DO_EXECUTOR,\n                                                 campo=CAMPO_DAS_ISSUES,\n                                                 qual=CAMPO_DO_REPOSITORIO)\n    return {\"issue\": int(quadro) if quadro else caixas[qual],\n            \"repositorio\": issues[CAMPO_DO_REPOSITORIO],\n            \"conta\": issues.get(CAMPO_DA_CONTA) or \"\",\n            \"quem_se_marca\": gh.quem_se_marca(dado)}, \"\"\n\n\ndef enderecos_das_caixas(cwd: str = \"\", quadro: str = \"\") -> tuple:\n    enderecos, primeiro_erro = [], \"\"\n    for tipo in TIPOS:\n        endereco, erro = endereco_da_caixa(tipo, cwd, quadro)\n        if erro:\n            primeiro_erro = primeiro_erro or erro\n        elif endereco[\"issue\"] not in [um[\"issue\"] for um in enderecos]:\n            enderecos.append(endereco)\n    return enderecos, \"\" if enderecos else primeiro_erro\n\n\ndef ler_corpo(endereco: dict) -> tuple:\n    feito = gh.na_conta(endereco[\"conta\"],\n                         [\"issue\", \"view\", str(endereco[\"issue\"]),\n                          \"--repo\", endereco[\"repositorio\"],\n                          \"--json\", \"body\"])\n    if feito is None or feito.returncode != 0:\n        return \"\", FALHA_AO_LER.format(issue=endereco[\"issue\"],\n                                       motivo=gh.berro(feito))\n    try:\n        return json.loads(feito.stdout).get(\"body\") or \"\", \"\"\n    except (ValueError, AttributeError) as erro:\n        return \"\", FALHA_AO_LER.format(issue=endereco[\"issue\"], motivo=erro)\n\n\ndef gravar_corpo(endereco: dict, corpo: str) -> str:\n    feito = gh.na_conta(endereco[\"conta\"],\n                         [\"issue\", \"edit\", str(endereco[\"issue\"]),\n                          \"--repo\", endereco[\"repositorio\"],\n                          \"--body-file\", \"-\"], entrada=corpo)\n    if feito is None or feito.returncode != 0:\n        return FALHA_AO_GRAVAR.format(issue=endereco[\"issue\"],\n                                      motivo=gh.berro(feito))\n    return \"\"\n\n\ndef _achados_do_corpo(corpo: str) -> list:\n    partes = partes_do_corpo(corpo)\n    return achados_do_miolo(partes[1]) if partes else []\n\n\ndef _identidades_do_corpo(corpo: str) -> set:\n    return {um[\"id\"] for um in _achados_do_corpo(corpo)}\n\n\ndef a_linha(corpo: str, identidade: str) -> dict:\n    achadas = [um for um in _achados_do_corpo(corpo)\n               if um[\"id\"] == identidade]\n    return achadas[0] if achadas else {}\n\n\ndef recusa_do_bloco(corpo: str, issue) -> str:\n    partes = partes_do_corpo(corpo)\n    if not partes:\n        return RECUSA_SEM_BLOCO.format(abre=MARCA_ABRE, fecha=MARCA_FECHA)\n    perdidas = linhas_que_nao_leio(partes[1])\n    if perdidas:\n        return RECUSA_LINHA_QUE_NAO_LEIO.format(issue=issue,\n                                                formato=LINHA_DO_ACHADO,\n                                                linha=perdidas[0])\n    return \"\"\n\n\ndef gravar_relendo(endereco: dict, corpo: str, refazer, o_que) -> tuple:\n    esperadas = _identidades_do_corpo(refazer(corpo, o_que))\n    tiradas = _identidades_do_corpo(corpo) - esperadas\n    gravacoes = 0\n    while True:\n        atual, erro = ler_corpo(endereco)\n        if erro:\n            return gravacoes, set(), erro\n        erro = recusa_do_bloco(atual, endereco[\"issue\"])\n        if erro:\n            return gravacoes, set(), erro\n        presentes = _identidades_do_corpo(atual)\n        divergentes = (esperadas - presentes) | (tiradas & presentes)\n        proposto = refazer(atual, o_que)\n        if proposto == atual or gravacoes == TENTATIVAS_DE_GRAVACAO:\n            return gravacoes, divergentes, \"\"\n        esperadas |= _identidades_do_corpo(proposto)\n        tiradas |= presentes - _identidades_do_corpo(proposto)\n        erro = gravar_corpo(endereco, proposto)\n        if erro:\n            return gravacoes, set(), erro\n        gravacoes += 1\n\n\ndef por_na_caixa(endereco: dict, novo: dict, ensaio: bool = False) -> tuple:\n    corpo, erro = ler_corpo(endereco)\n    if erro:\n        return 2, erro\n    erro = recusa_do_bloco(corpo, endereco[\"issue\"])\n    if erro:\n        return 2, erro\n    if ensaio:\n        return 0, RECADO_DO_ENSAIO.format(\n            issue=endereco[\"issue\"],\n            miolo=partes_do_corpo(corpo_com(corpo, novo))[1])\n    ja_estava = any(um[\"id\"] == novo[\"id\"] for um in _achados_do_corpo(corpo))\n    gravacoes, divergentes, erro = gravar_relendo(endereco, corpo, corpo_com,\n                                                  novo)\n    if erro:\n        return 2, erro\n    if divergentes:\n        return 2, NAO_ESTA_LA.format(issue=endereco[\"issue\"],\n                                     id=\", \".join(sorted(divergentes)))\n    if not gravacoes:\n        return 0, RECADO_JA_ESTAVA.format(issue=endereco[\"issue\"],\n                                          id=novo[\"id\"])\n    recado = RECADO_ATUALIZADO if ja_estava else RECADO_POSTO\n    return 0, recado.format(issue=endereco[\"issue\"], id=novo[\"id\"])\n\n\ndef rodar(tipo: str, identidade: str, assunto: str, quando: str,\n          cwd: str = \"\", ensaio: bool = False, quadro: str = \"\",\n          corpo: str = \"\") -> tuple:\n    if not identidade_serve(identidade):\n        return 2, RECUSA_IDENTIDADE.format(valor=identidade)\n    if not na_linha(assunto):\n        return 2, RECUSA_SEM_ASSUNTO\n    if not PADRAO_DA_DATA.match(quando or \"\"):\n        return 2, RECUSA_DATA.format(valor=quando)\n    endereco, erro = endereco_da_caixa(tipo, cwd, quadro)\n    if erro:\n        return 2, erro\n    return por_na_caixa(endereco,\n                        achado(tipo, identidade, assunto, quando, corpo),\n                        ensaio)\n\n\ndef achar_a_linha(enderecos: list, identidade: str) -> tuple:\n    for endereco in enderecos:\n        corpo, erro = ler_corpo(endereco)\n        if erro:\n            return {}, \"\", erro\n        erro = recusa_do_bloco(corpo, endereco[\"issue\"])\n        if erro:\n            return {}, \"\", erro\n        if a_linha(corpo, identidade):\n            return endereco, corpo, \"\"\n    return {}, \"\", RECUSA_LINHA_QUE_NAO_EXISTE.format(\n        id=identidade,\n        issues=\", \".join(str(um[\"issue\"]) for um in enderecos))\n\n\ndef registro_da_poda(alvo: dict, quando: str, motivo: str) -> str:\n    escrito = REGISTRO_DA_PODA.format(quando=quando, id=alvo[\"id\"],\n                                      tipo=alvo[\"tipo\"])\n    limpo = na_linha(motivo)\n    return escrito + (MOTIVO_DA_PODA.format(motivo=limpo) if limpo else \"\")\n\n\ndef podar_da_caixa(endereco: dict, corpo: str, identidade: str,\n                   registro: str, ensaio: bool = False) -> tuple:\n    if ensaio:\n        return 0, RECADO_DO_ENSAIO_DA_PODA.format(issue=endereco[\"issue\"],\n                                                  id=identidade,\n                                                  registro=registro)\n\n    _, divergentes, erro = gravar_relendo(endereco, corpo, corpo_sem,\n                                          identidade)\n    if erro:\n        return 2, erro\n    if identidade in divergentes:\n        return 2, AINDA_ESTA_LA.format(issue=endereco[\"issue\"], id=identidade)\n    if divergentes:\n        return 2, NAO_ESTA_LA.format(issue=endereco[\"issue\"],\n                                     id=\", \".join(sorted(divergentes)))\n    return 0, RECADO_PODADO.format(issue=endereco[\"issue\"], id=identidade,\n                                   registro=registro)\n\n\ndef podar(identidade: str, quando: str, cwd: str = \"\", motivo: str = \"\",\n          ensaio: bool = False, quadro: str = \"\") -> tuple:\n    if not identidade_serve(identidade):\n        return 2, RECUSA_IDENTIDADE.format(valor=identidade)\n    if not PADRAO_DA_DATA.match(quando or \"\"):\n        return 2, RECUSA_DATA.format(valor=quando)\n    enderecos, erro = enderecos_das_caixas(cwd, quadro)\n    if erro:\n        return 2, erro\n    endereco, corpo, erro = achar_a_linha(enderecos, identidade)\n    if erro:\n        return 2, erro\n    return podar_da_caixa(\n        endereco, corpo, identidade,\n        registro_da_poda(a_linha(corpo, identidade), quando, motivo), ensaio)\n\n\ndef aviso_de_digito_colado(corpo: str) -> str:\n    legivel = TRECHO_QUE_NAO_SE_LE.sub(\" \", corpo)\n    coladas = sorted(set(PALAVRA_COM_DIGITO_COLADO.findall(legivel)))\n    if not coladas:\n        return \"\"\n    return AVISO_DE_DIGITO_COLADO.format(quantas=len(coladas),\n                                         exemplos=\", \".join(coladas[:5]))\n\n\ndef linha_do_que_espera(item: str) -> str:\n    texto, _, link = item.partition(SEPARADOR_DO_ITEM)\n    return (LINHA_DO_QUE_ESPERA_COM_LINK.format(texto=texto.strip(),\n                                                link=link.strip())\n            if link.strip() else LINHA_DO_QUE_ESPERA.format(texto=item.strip()))\n\n\ndef relatar(corpo: str, cwd: str = \"\", ensaio: bool = False,\n            quadro: str = \"\", seu=()) -> tuple:\n    if not (corpo or \"\").strip():\n        return 2, RECUSA_SEM_CORPO\n    itens = [item.strip() for item in seu or [] if item.strip()]\n    for item in itens:\n        if not ENDERECO.search(item):\n            return 2, RECUSA_SEU_SEM_LINK.format(item=item)\n    enderecos, erro = enderecos_das_caixas(cwd, quadro)\n    if erro:\n        return 2, erro\n    endereco = enderecos[0]\n    aviso = aviso_de_digito_colado(corpo)\n    texto = TITULO_DO_RELATORIO + \"\\n\\n\" + corpo.strip()\n    chamada = CHAMADA_DO_DONO.format(\n        itens=\"\\n\".join(linha_do_que_espera(item) for item in itens))\n    if ensaio:\n        return 0, aviso + RECADO_DO_ENSAIO_DO_RELATO.format(\n            issue=endereco[\"issue\"], corpo=texto) + (\n                RECADO_DO_ENSAIO_DA_CHAMADA.format(chamada=chamada)\n                if itens else \"\")\n    ficou, dito = gh.gravar_o_bloco(endereco[\"conta\"],\n                                    endereco[\"repositorio\"],\n                                    endereco[\"issue\"],\n                                    NOME_DO_BLOCO_DO_RELATORIO, texto)\n    if not ficou:\n        return 2, FALHA_AO_RELATAR.format(issue=endereco[\"issue\"],\n                                          motivo=dito)\n    recados = [aviso + RECADO_RELATADO.format(issue=endereco[\"issue\"]), dito]\n    if itens:\n        comentou, falha, sem_marca = gh.comentar_para_o_dono(\n            endereco[\"conta\"], endereco[\"repositorio\"], endereco[\"issue\"],\n            chamada, endereco[\"quem_se_marca\"])\n        if not comentou:\n            return 2, FALHA_AO_CHAMAR_O_DONO.format(issue=endereco[\"issue\"],\n                                                    motivo=falha)\n        recados += [RECADO_CHAMOU_O_DONO.format(issue=endereco[\"issue\"],\n                                                quantos=len(itens)),\n                    sem_marca]\n    return 0, \" \u00b7 \".join(recado for recado in recados if recado)\n\n\nFALSO_GH = \"\"\"import json\nimport os\nimport sys\nfrom pathlib import Path\n\nCORPO = Path(os.environ[\"CAIXA_TESTE_CORPO\"])\nLOG = Path(os.environ[\"CAIXA_TESTE_LOG\"])\nCOMENTARIOS = Path(os.environ[\"CAIXA_TESTE_COMENTARIOS\"])\nsys.stdin.reconfigure(encoding=\"utf-8\")\n\nwith LOG.open(\"a\", encoding=\"utf-8\") as registro:\n    registro.write(\" \".join(sys.argv[1:]) + chr(10))\nrota = sys.argv[4] if sys.argv[1:3] == [\"api\", \"--method\"] else \"\"\nif rota.endswith(\"/comments\") and sys.argv[3] == \"POST\":\n    if os.environ.get(\"CAIXA_TESTE_RECUSA_COMENTARIO\"):\n        sys.exit(2)\n    with COMENTARIOS.open(\"a\", encoding=\"utf-8\") as escrito:\n        escrito.write(json.loads(sys.stdin.read())[\"body\"] + chr(10))\nelif rota and sys.argv[3] == \"GET\" and \"/comments\" not in rota:\n    print(json.dumps({\"body\": CORPO.read_text(encoding=\"utf-8\")}))\nelif rota and sys.argv[3] == \"PATCH\" and \"/comments\" not in rota:\n    if not os.environ.get(\"CAIXA_TESTE_ENGOLE\"):\n        CORPO.write_text(json.loads(sys.stdin.read())[\"body\"],\n                         encoding=\"utf-8\")\nelif \"view\" in sys.argv:\n    print(json.dumps({\"body\": CORPO.read_text(encoding=\"utf-8\")}))\nelif \"comment\" in sys.argv:\n    if os.environ.get(\"CAIXA_TESTE_RECUSA_COMENTARIO\"):\n        sys.exit(2)\n    with COMENTARIOS.open(\"a\", encoding=\"utf-8\") as escrito:\n        escrito.write(sys.stdin.read() + chr(10))\nelif \"api\" in sys.argv and \"PATCH\" in sys.argv:\n    if os.environ.get(\"CAIXA_TESTE_RECUSA_COMENTARIO\"):\n        sys.exit(2)\n    COMENTARIOS.write_text(json.loads(sys.stdin.read())[\"body\"] + chr(10),\n                           encoding=\"utf-8\")\nelif \"api\" in sys.argv:\n    texto = COMENTARIOS.read_text(encoding=\"utf-8\")\n    print(json.dumps([{\"id\": 1, \"body\": texto}] if texto.strip() else []))\nelif \"edit\" in sys.argv and not os.environ.get(\"CAIXA_TESTE_ENGOLE\"):\n    CORPO.write_text(sys.stdin.read(), encoding=\"utf-8\")\n\"\"\"\n\n\ndef testar() -> int:\n    import tempfile\n    falhas, rodados = [], []\n\n    def caso(rotulo, condicao):\n        rodados.append(rotulo)\n        if not condicao:\n            falhas.append(rotulo)\n\n    molde = (\"prosa de gente antes\\n\\n\" + MARCA_ABRE + \"\\n\" + MARCA_FECHA\n             + \"\\n\\nprosa de gente depois\\n\")\n    hoje = \"2026-08-22\"\n    amanha = \"2026-08-23\"\n    um = achado(DEFEITO, \"prova-nao-reproduz\",\n                \"a prova declarada d\u00e1 outra coisa\", hoje)\n    velha = \"- **linha-velha** \u2014 sem etiqueta nenhuma\" + SEPARADOR + hoje\n\n    com_corpo = achado(DEFEITO, \"com-corpo\", \"o assunto curto\", hoje,\n                       corpo=\"a receita de repetir\\ne o contorno\")\n    caso(\"--corpo n\u00e3o \u00e9 descartado: o detalhe entra na linha, atr\u00e1s do \"\n         \"assunto, e a linha continua de uma linha s\u00f3\",\n         com_corpo[\"assunto\"] == \"o assunto curto \u2014 a receita de repetir \"\n         \"e o contorno\")\n    caso(\"sem corpo, o assunto sai como sempre\",\n         achado(DEFEITO, \"sem-corpo\", \"s\u00f3 o assunto\", hoje)[\"assunto\"]\n         == \"s\u00f3 o assunto\")\n    caso(\"identidade em kebab min\u00fasculo serve\",\n         identidade_serve(\"prova-nao-reproduz\"))\n    caso(\"identidade com espa\u00e7o n\u00e3o serve\", not identidade_serve(\"prova nao\"))\n    caso(\"identidade com mai\u00fascula n\u00e3o serve\",\n         not identidade_serve(\"Prova\"))\n    caso(\"identidade vazia n\u00e3o serve\", not identidade_serve(\"\"))\n    caso(\"corpo com d\u00edgito colado a letra recebe aviso que nomeia a palavra\",\n         \"exatamente12pontos\" in aviso_de_digito_colado(\n             \"Entra hoje: exatamente12pontos e 3daPython\"))\n    caso(\"corpo com os espa\u00e7os no lugar n\u00e3o recebe aviso\",\n         aviso_de_digito_colado(\n             \"exatamente 12 pontos, 3 da Python, 16 PRs\") == \"\")\n    caso(\"hash entre crases e link n\u00e3o contam como d\u00edgito colado\",\n         aviso_de_digito_colado(\n             \"commit `a41d2f25` em https://x.invalid/issues/315#c1\") == \"\")\n\n    posto = corpo_com(molde, um)\n    caso(\"o achado posto vira uma linha no bloco\",\n         len(achados_do_miolo(partes_do_corpo(posto)[1])) == 1)\n\n    de_novo = corpo_com(posto, um)\n    caso(\"o mesmo achado, posto duas vezes, deixa UMA linha\",\n         len(achados_do_miolo(partes_do_corpo(de_novo)[1])) == 1)\n    caso(\"e posto duas vezes o corpo nem muda\", de_novo == posto)\n\n    mudou = corpo_com(posto, achado(DEFEITO, \"prova-nao-reproduz\",\n                                    \"agora reproduz noutra m\u00e1quina\", amanha))\n    lidos = achados_do_miolo(partes_do_corpo(mudou)[1])\n    caso(\"achado que mudou de estado atualiza a linha, n\u00e3o acrescenta outra\",\n         len(lidos) == 1 and lidos[0][\"quando\"] == amanha)\n\n    outro = corpo_com(posto, achado(MELHORIA, \"seguiu-sem-prova\",\n                                    \"etapa sem prova\", hoje))\n    lidos = achados_do_miolo(partes_do_corpo(outro)[1])\n    caso(\"achado de outra identidade entra sem apagar o que j\u00e1 estava\",\n         [um[\"id\"] for um in lidos]\n         == [\"prova-nao-reproduz\", \"seguiu-sem-prova\"])\n\n    caso(\"a linha escrita traz a etiqueta do tipo\",\n         \"`\" + DEFEITO + \"`\" in posto)\n    caso(\"defeito e melhoria moram no mesmo bloco, cada um com sua etiqueta\",\n         [um[\"tipo\"] for um in lidos] == [DEFEITO, MELHORIA])\n\n    virou = corpo_com(posto, achado(MELHORIA, \"prova-nao-reproduz\",\n                                    \"a prova declarada d\u00e1 outra coisa\", hoje))\n    lidos = achados_do_miolo(partes_do_corpo(virou)[1])\n    caso(\"a mesma identidade com outro tipo troca a etiqueta, sem duplicar\",\n         len(lidos) == 1 and lidos[0][\"tipo\"] == MELHORIA)\n\n    caso(\"linha sem etiqueta de tipo n\u00e3o se l\u00ea como achado\",\n         achados_do_miolo(\"\\n\" + velha + \"\\n\") == [])\n    caso(\"e ela \u00e9 nomeada como linha que o instrumento n\u00e3o sabe ler\",\n         linhas_que_nao_leio(\"\\n\" + velha + \"\\n\") == [velha])\n    caso(\"linha que o instrumento sabe ler n\u00e3o entra nessa lista\",\n         linhas_que_nao_leio(partes_do_corpo(posto)[1]) == [])\n\n    estranho = (\"  nota indentada debaixo da linha\",\n                \"Prosa solta que algu\u00e9m p\u00f4s no meio do bloco.\",\n                \"<!-- marca que algu\u00e9m deixou aqui -->\")\n    com_estranhas = (MARCA_ABRE + \"\\n\" + LINHA_DO_ACHADO.format(**um) + \"\\n\"\n                     + \"\\n\".join(estranho) + \"\\n\" + MARCA_FECHA + \"\\n\")\n    escrito = corpo_com(com_estranhas, achado(DEFEITO, \"chegou-depois\",\n                                              \"achado novo\", amanha))\n    caso(\"linha que o instrumento n\u00e3o entende sobrevive \u00e0 escrita seguinte\",\n         all(linha in escrito for linha in estranho))\n    caso(\"e a escrita que a preservou tamb\u00e9m p\u00f4s o achado novo\",\n         \"chegou-depois\" in escrito)\n    caso(\"a poda preserva a linha que o instrumento n\u00e3o entende\",\n         all(linha in corpo_sem(com_estranhas, \"prova-nao-reproduz\")\n             for linha in estranho))\n    caso(\"escrever duas vezes n\u00e3o multiplica linha preservada nem em branco\",\n         corpo_com(escrito, achado(DEFEITO, \"chegou-depois\",\n                                   \"achado novo\", amanha)) == escrito)\n\n    tirado = corpo_sem(outro, \"prova-nao-reproduz\")\n    caso(\"a poda tira s\u00f3 a linha pedida e deixa as outras\",\n         [um[\"id\"] for um in achados_do_miolo(partes_do_corpo(tirado)[1])]\n         == [\"seguiu-sem-prova\"])\n    caso(\"e a poda n\u00e3o toca no texto que gente p\u00f4s fora do bloco\",\n         tirado.startswith(\"prosa de gente antes\")\n         and tirado.endswith(\"prosa de gente depois\\n\"))\n\n    atualizado = corpo_com(outro, achado(DEFEITO, \"prova-nao-reproduz\",\n                                         \"de novo\", amanha))\n    caso(\"linha atualizada fica onde estava, n\u00e3o vai para o fim\",\n         [um[\"id\"] for um in achados_do_miolo(partes_do_corpo(atualizado)[1])]\n         == [\"prova-nao-reproduz\", \"seguiu-sem-prova\"])\n\n    caso(\"texto posto \u00e0 m\u00e3o FORA do bloco sobrevive \u00e0 escrita\",\n         posto.startswith(\"prosa de gente antes\")\n         and posto.endswith(\"prosa de gente depois\\n\"))\n    caso(\"e sobrevive \u00e0 segunda escrita tamb\u00e9m\",\n         outro.startswith(\"prosa de gente antes\")\n         and outro.endswith(\"prosa de gente depois\\n\"))\n\n    caso(\"corpo sem o bloco marcado n\u00e3o \u00e9 escrito\",\n         corpo_com(\"s\u00f3 prosa, sem marca nenhuma\\n\", um) == \"\")\n    caso(\"corpo com a marca de abrir e sem a de fechar n\u00e3o \u00e9 escrito\",\n         corpo_com(\"a\\n\" + MARCA_ABRE + \"\\nb\\n\", um) == \"\")\n\n    caso(\"linha que n\u00e3o \u00e9 achado, dentro do bloco, n\u00e3o vira achado\",\n         achados_do_miolo(\"\\n- uma nota de gente\\ntexto solto\\n\") == [])\n\n    quebrado = corpo_com(molde, achado(DEFEITO, \"com-quebra\",\n                                       \"primeira\\nsegunda\", hoje))\n    lidos = achados_do_miolo(partes_do_corpo(quebrado)[1])\n    caso(\"assunto com quebra de linha vira uma linha s\u00f3\",\n         len(lidos) == 1 and lidos[0][\"assunto\"] == \"primeira segunda\")\n\n    com_separador = corpo_com(molde, achado(\n        DEFEITO, \"com-separador\", \"o texto tem\" + SEPARADOR + \"no meio\",\n        hoje))\n    lidos = achados_do_miolo(partes_do_corpo(com_separador)[1])\n    caso(\"assunto que cont\u00e9m o separador ainda se l\u00ea inteiro\",\n         len(lidos) == 1 and lidos[0][\"quando\"] == hoje\n         and lidos[0][\"assunto\"].endswith(\"no meio\"))\n\n    escrito = registro_da_poda(um, amanha, \"entregue na rodada de hoje\")\n    caso(\"o registro da poda guarda s\u00f3 identidade, tipo e data \u2014 o assunto \"\n         \"inteiro faria o corpo crescer como os coment\u00e1rios cresciam\",\n         um[\"id\"] in escrito and um[\"tipo\"] in escrito and amanha in escrito\n         and um[\"assunto\"] not in escrito)\n    caso(\"e guarda o motivo quando algu\u00e9m deu um\",\n         \"entregue na rodada de hoje\" in escrito)\n    caso(\"sem motivo, o registro n\u00e3o inventa um\",\n         \"motivo\" not in registro_da_poda(um, amanha, \"\"))\n    caso(\"o registro da poda cabe numa linha \u2014 ele vai ao commit\",\n         \"\\n\" not in registro_da_poda(um, amanha, \"motivo com\\nquebra\"))\n\n    with tempfile.TemporaryDirectory(prefix=\"caixa-teste-\") as pasta:\n        base = Path(pasta)\n        (base / \"nucleo\").mkdir()\n        vazia = base / \"sem-configuracao\"\n        vazia.mkdir()\n        corpo = base / \"corpo.md\"\n        registro = base / \"registro.txt\"\n        comentarios = base / \"comentarios.md\"\n        falso_gh = base / \"falso_gh.py\"\n        falso_gh.write_text(FALSO_GH, encoding=\"utf-8\")\n\n        def com_configuracao(dado):\n            (base / ARQUIVO_DO_EXECUTOR).write_text(\n                json.dumps(dado) if isinstance(dado, dict) else dado,\n                encoding=\"utf-8\")\n\n        def do_zero(texto=molde):\n            corpo.write_text(texto, encoding=\"utf-8\")\n            registro.write_text(\"\", encoding=\"utf-8\")\n            comentarios.write_text(\"\", encoding=\"utf-8\")\n\n        COMENTARIO_NO_REGISTRO = \"/comments --input\"\n\n        def chamadas(qual):\n            return registro.read_text(encoding=\"utf-8\").count(qual)\n\n        def no_quadro(identidade):\n            return any(um[\"id\"] == identidade for um in _achados_do_corpo(\n                corpo.read_text(encoding=\"utf-8\")))\n\n        guardado = dict(os.environ)\n        os.environ[gh.VARIAVEL_DO_GH] = gh.linha_de_comando(sys.executable,\n                                                           falso_gh)\n        os.environ[\"CAIXA_TESTE_CORPO\"] = str(corpo)\n        os.environ[\"CAIXA_TESTE_LOG\"] = str(registro)\n        os.environ[\"CAIXA_TESTE_COMENTARIOS\"] = str(comentarios)\n        try:\n            declarada = {\"caixas\": {\"defeitos\": 7, \"melhorias\": 8},\n                         \"issues\": {\"repositorio\": \"exemplo/exemplo\"}}\n            quadro = {\"caixas\": {\"defeitos\": 7, \"melhorias\": 7},\n                      \"issues\": {\"repositorio\": \"exemplo/exemplo\"}}\n\n            com_configuracao({\"issues\": {\"repositorio\": \"exemplo/exemplo\"}})\n            do_zero()\n            codigo, recado = rodar(DEFEITO, \"sem-caixas\", \"o que for\", hoje,\n                                   cwd=str(base))\n            caso(\"sem `caixas` declarada, o instrumento sai diferente de zero\",\n                 codigo != 0)\n            caso(\"a recusa nomeia o campo que falta\",\n                 CAMPO_DAS_CAIXAS in recado)\n            caso(\"e recusando, n\u00e3o chama o GitHub nenhuma vez\",\n                 chamadas(\"issue\") == 0)\n\n            com_configuracao(quadro)\n            do_zero()\n            codigo, recado = rodar(DEFEITO, \"linha-do-cliente\", \"o que for\",\n                                   hoje, cwd=str(base), quadro=\"99\")\n            caso(\"com --quadro, a linha vai para a issue apontada, n\u00e3o para \"\n                 \"a declarada na configura\u00e7\u00e3o\",\n                 codigo == 0 and chamadas(\"99\") >= 1\n                 and chamadas(\"issue 7\") == 0)\n            caso(\"e o reposit\u00f3rio continua vindo da configura\u00e7\u00e3o \u2014 o quadro \"\n                 \"do cliente nasce no mesmo reposit\u00f3rio\",\n                 chamadas(\"exemplo/exemplo\") >= 1)\n            codigo, recado = rodar(DEFEITO, \"quadro-torto\", \"o que for\",\n                                   hoje, cwd=str(base), quadro=\"nao-e-numero\")\n            caso(\"--quadro que n\u00e3o \u00e9 n\u00famero de issue \u00e9 erro de uso\",\n                 codigo == 2)\n            codigo, _ = rodar(DEFEITO, \"quadro-exotico\", \"o que for\", hoje,\n                              cwd=str(base), quadro=\"\\u00b2\")\n            caso(\"d\u00edgito que n\u00e3o \u00e9 ASCII \u00e9 recusa declarada, n\u00e3o traceback: \"\n                 \"isdigit() aceita o expoente e int() n\u00e3o\",\n                 codigo == 2)\n            caso(\"e recusando, n\u00e3o chama o GitHub\", chamadas(\"nao-e-numero\") == 0)\n            do_zero()\n\n            com_configuracao({\"caixas\": {\"melhorias\": 8},\n                              \"issues\": {\"repositorio\": \"exemplo/exemplo\"}})\n            codigo, recado = rodar(DEFEITO, \"so-a-outra\", \"o que for\", hoje,\n                                   cwd=str(base))\n            caso(\"caixa declarada s\u00f3 para o outro tipo tamb\u00e9m \u00e9 recusa\",\n                 codigo != 0 and \"defeitos\" in recado)\n\n            com_configuracao({\"caixas\": {\"defeitos\": \"${NUMERO}\"},\n                              \"issues\": {\"repositorio\": \"exemplo/exemplo\"}})\n            codigo, _ = rodar(DEFEITO, \"por-preencher\", \"o que for\", hoje,\n                              cwd=str(base))\n            caso(\"n\u00famero ainda por preencher n\u00e3o \u00e9 n\u00famero de caixa\",\n                 codigo != 0)\n\n            com_configuracao({\"caixas\": {\"defeitos\": 7}})\n            codigo, recado = rodar(DEFEITO, \"sem-repositorio\", \"o que for\",\n                                   hoje, cwd=str(base))\n            caso(\"sem o reposit\u00f3rio das issues, recusa e diz qual campo\",\n                 codigo != 0 and CAMPO_DO_REPOSITORIO in recado)\n\n            codigo, recado = rodar(DEFEITO, \"sem-arquivo\", \"o que for\", hoje,\n                                   cwd=str(vazia))\n            caso(\"sem o arquivo de configura\u00e7\u00e3o, recusa nomeando o arquivo\",\n                 codigo != 0 and ARQUIVO_DO_EXECUTOR in recado)\n\n            com_configuracao(\"isto n\u00e3o \u00e9 json\")\n            codigo, _ = rodar(DEFEITO, \"json-quebrado\", \"o que for\", hoje,\n                              cwd=str(base))\n            caso(\"configura\u00e7\u00e3o ileg\u00edvel \u00e9 recusa, n\u00e3o \u00e9 escrita \u00e0s cegas\",\n                 codigo != 0 and chamadas(\"issue\") == 0)\n\n            com_configuracao(declarada)\n            codigo, _ = rodar(\"bilhete\", \"tipo-que-nao-existe\", \"o que for\",\n                              hoje, cwd=str(base))\n            caso(\"tipo que n\u00e3o existe \u00e9 recusado antes de tudo\", codigo != 0)\n\n            do_zero()\n            codigo, recado = rodar(DEFEITO, \"prova-nao-reproduz\",\n                                   \"a prova declarada d\u00e1 outra coisa\", hoje,\n                                   cwd=str(base))\n            caso(\"com a caixa declarada, o achado vira linha no corpo\",\n                 codigo == 0\n                 and len(_achados_do_corpo(corpo.read_text(encoding=\"utf-8\")))\n                 == 1)\n            codigo, recado = rodar(DEFEITO, \"prova-nao-reproduz\",\n                                   \"a prova declarada d\u00e1 outra coisa\", hoje,\n                                   cwd=str(base))\n            caso(\"posto de novo, a caixa continua com UMA linha\",\n                 codigo == 0\n                 and len(_achados_do_corpo(corpo.read_text(encoding=\"utf-8\")))\n                 == 1)\n            caso(\"e a segunda vez nem regrava o corpo\", chamadas(\"edit\") == 1)\n\n            codigo, recado = rodar(DEFEITO, \"prova-nao-reproduz\",\n                                   \"agora d\u00e1 outra coisa ainda\", amanha,\n                                   cwd=str(base))\n            lidos = _achados_do_corpo(corpo.read_text(encoding=\"utf-8\"))\n            caso(\"achado que mudou atualiza a linha na caixa de verdade\",\n                 codigo == 0 and len(lidos) == 1\n                 and lidos[0][\"quando\"] == amanha)\n\n            com_configuracao(quadro)\n            do_zero()\n            rodar(DEFEITO, \"prova-nao-reproduz\", \"a prova d\u00e1 outra coisa\",\n                  hoje, cwd=str(base))\n            rodar(MELHORIA, \"caixa-aprende-a-podar\", \"a poda entra\", hoje,\n                  cwd=str(base))\n            lidos = _achados_do_corpo(corpo.read_text(encoding=\"utf-8\"))\n            caso(\"com as duas caixas na mesma issue, os dois tipos entram no \"\n                 \"mesmo quadro, cada um com sua etiqueta\",\n                 [(um[\"id\"], um[\"tipo\"]) for um in lidos]\n                 == [(\"prova-nao-reproduz\", DEFEITO),\n                     (\"caixa-aprende-a-podar\", MELHORIA)])\n\n            codigo, recado = podar(\"caixa-aprende-a-podar\", amanha,\n                                   cwd=str(base), motivo=\"entregue na #7\")\n            escrito = comentarios.read_text(encoding=\"utf-8\")\n            caso(\"a poda tira a linha do quadro sem ningu\u00e9m dizer o tipo\",\n                 codigo == 0 and not no_quadro(\"caixa-aprende-a-podar\"))\n            caso(\"e a poda n\u00e3o leva junto a linha da vizinha\",\n                 no_quadro(\"prova-nao-reproduz\"))\n            no_corpo = corpo.read_text(encoding=\"utf-8\")\n            caso(\"o corpo n\u00e3o guarda fechamento: a linha sai, nada de \"\n                 \"se\u00e7\u00e3o nova nem coment\u00e1rio, e o registro com o motivo \"\n                 \"vai no recado, para o commit\",\n                 chamadas(COMENTARIO_NO_REGISTRO) == 0 and escrito == \"\"\n                 and \"fechamentos\" not in no_corpo.lower()\n                 and \"caixa-aprende-a-podar\" not in no_corpo\n                 and \"caixa-aprende-a-podar\" in recado\n                 and \"entregue na #7\" in recado)\n\n            codigo, recado = podar(\"nunca-esteve-no-quadro\", amanha,\n                                   cwd=str(base))\n            caso(\"podar linha que n\u00e3o est\u00e1 no quadro \u00e9 recusa, sem escrita\",\n                 codigo != 0 and chamadas(COMENTARIO_NO_REGISTRO) == 0\n                 and chamadas(\"edit\") == 3)\n\n            do_zero()\n            rodar(MELHORIA, \"caixa-aprende-a-podar\", \"a poda entra\", hoje,\n                  cwd=str(base))\n            codigo, recado = podar(\"caixa-aprende-a-podar\", amanha,\n                                   cwd=str(base), ensaio=True)\n            caso(\"o ensaio da poda mostra o que sairia e n\u00e3o toca na caixa\",\n                 codigo == 0 and \"caixa-aprende-a-podar\" in recado\n                 and chamadas(\"comment\") == 0 and chamadas(\"edit\") == 1\n                 and no_quadro(\"caixa-aprende-a-podar\"))\n\n            do_zero()\n            relatorio = \"# A rodada\\n\\nO que ela mediu.\\n\"\n            codigo, recado = relatar(relatorio, cwd=str(base), ensaio=True)\n            caso(\"o ensaio do relat\u00f3rio mostra o corpo e n\u00e3o escreve na \"\n                 \"caixa\",\n                 codigo == 0 and relatorio.strip() in recado\n                 and chamadas(COMENTARIO_NO_REGISTRO) == 0\n                 and chamadas(\"api\") == 0 and chamadas(\"edit\") == 0)\n\n            def bloco_do_relatorio():\n                return gh.texto_do_bloco(corpo.read_text(encoding=\"utf-8\"),\n                                         NOME_DO_BLOCO_DO_RELATORIO) or \"\"\n\n            codigo, recado = relatar(relatorio, cwd=str(base))\n            caso(\"SEM NADA PARA O DONO: o relat\u00f3rio reescreve o bloco dele no \"\n                 \"corpo da caixa e n\u00e3o abre coment\u00e1rio nenhum\",\n                 codigo == 0 and chamadas(COMENTARIO_NO_REGISTRO) == 0\n                 and \"O que ela mediu.\" in bloco_do_relatorio()\n                 and not comentarios.read_text(encoding=\"utf-8\").strip())\n            caso(\"o relat\u00f3rio no corpo n\u00e3o vira linha do quadro\",\n                 not _achados_do_corpo(corpo.read_text(encoding=\"utf-8\")))\n\n            outro = \"# Outra rodada\\n\\nO que mudou.\\n\"\n            codigo, recado = relatar(outro, cwd=str(base))\n            escrito = corpo.read_text(encoding=\"utf-8\")\n            caso(\"relatar de novo reescreve o MESMO bloco: o relat\u00f3rio velho \"\n                 \"sai do corpo, e continua no hist\u00f3rico de edi\u00e7\u00e3o\",\n                 codigo == 0 and chamadas(COMENTARIO_NO_REGISTRO) == 0\n                 and \"O que mudou.\" in bloco_do_relatorio()\n                 and \"O que ela mediu.\" not in escrito\n                 and escrito.count(gh.marcas_do_bloco(\n                     NOME_DO_BLOCO_DO_RELATORIO)[0]) == 1)\n\n            com_configuracao({**quadro, \"issues\": {\n                \"repositorio\": \"exemplo/exemplo\",\n                \"quem_se_marca\": \"a-pessoa\"}})\n            do_zero()\n            codigo, recado = relatar(relatorio, cwd=str(base),\n                                     seu=[\"decidir o rumo|https://x/issues/7\"])\n            dito = comentarios.read_text(encoding=\"utf-8\")\n            caso(\"COM ALGO PARA O DONO: o relat\u00f3rio vai ao corpo e UM \"\n                 \"coment\u00e1rio abre marcando o login da configura\u00e7\u00e3o local\",\n                 codigo == 0 and chamadas(COMENTARIO_NO_REGISTRO) == 1\n                 and dito.startswith(\"@a-pessoa \")\n                 and \"https://x/issues/7\" in dito\n                 and \"O que ela mediu.\" in bloco_do_relatorio())\n\n            com_configuracao(quadro)\n            do_zero()\n            codigo, recado = relatar(relatorio, cwd=str(base),\n                                     seu=[\"decidir o rumo|https://x/issues/7\"])\n            dito = comentarios.read_text(encoding=\"utf-8\")\n            caso(\"SEM LOGIN CONFIGURADO: o coment\u00e1rio sai sem marca, e o \"\n                 \"recado avisa o campo que falta\",\n                 codigo == 0 and chamadas(COMENTARIO_NO_REGISTRO) == 1\n                 and \"@\" not in dito and \"quem_se_marca\" in recado)\n\n            do_zero()\n            codigo, recado = relatar(relatorio, cwd=str(base),\n                                     seu=[\"decidir o rumo sem endere\u00e7o\"])\n            caso(\"o que espera pelo dono sem link \u00e9 recusado antes de \"\n                 \"escrever: n\u00famero solto obriga a garimpar\",\n                 codigo == 2 and \"--seu\" in recado and chamadas(\"issue\") == 0)\n\n            for vazio in (\"\", \"   \\n\\t \"):\n                codigo, recado = relatar(vazio, cwd=str(base))\n                caso(f\"corpo vazio ({vazio!r}) \u00e9 recusado com recado, sem \"\n                     \"chamar o GitHub\",\n                     codigo == 2 and recado == RECUSA_SEM_CORPO\n                     and chamadas(\"issue\") == 0)\n\n            do_zero()\n            os.environ[\"CAIXA_TESTE_RECUSA_COMENTARIO\"] = \"1\"\n            codigo, recado = relatar(relatorio, cwd=str(base),\n                                     seu=[\"decidir o rumo|https://x/issues/7\"])\n            del os.environ[\"CAIXA_TESTE_RECUSA_COMENTARIO\"]\n            caso(\"coment\u00e1rio ao dono que n\u00e3o subiu vira erro confessado, e o \"\n                 \"recado diz que o relat\u00f3rio j\u00e1 est\u00e1 no corpo\",\n                 codigo == 2 and \"n\u00e3o subiu\" in recado\n                 and \"O que ela mediu.\" in bloco_do_relatorio())\n\n            do_zero()\n            os.environ[\"CAIXA_TESTE_ENGOLE\"] = \"1\"\n            codigo, recado = relatar(relatorio, cwd=str(base))\n            del os.environ[\"CAIXA_TESTE_ENGOLE\"]\n            caso(\"relat\u00f3rio que n\u00e3o ficou no corpo vira erro confessado, \"\n                 \"nunca relat\u00f3rio dado por escrito\",\n                 codigo == 2 and recado.startswith(\n                     FALHA_AO_RELATAR.split(\"{motivo}\")[0].format(issue=7)))\n\n            com_configuracao({\"issues\": {\"repositorio\": \"exemplo/exemplo\"}})\n            codigo, recado = relatar(relatorio, cwd=str(base))\n            caso(\"sem `caixas` declarada, relatar recusa e n\u00e3o comenta\",\n                 codigo == 2 and CAMPO_DAS_CAIXAS in recado)\n            com_configuracao(quadro)\n            do_zero()\n            rodar(MELHORIA, \"caixa-aprende-a-podar\", \"a poda entra\", hoje,\n                  cwd=str(base))\n\n            os.environ[\"CAIXA_TESTE_ENGOLE\"] = \"1\"\n            codigo, recado = podar(\"caixa-aprende-a-podar\", amanha,\n                                   cwd=str(base))\n            del os.environ[\"CAIXA_TESTE_ENGOLE\"]\n            caso(\"poda que se perdeu \u00e9 confessada, n\u00e3o \u00e9 dada por feita\",\n                 codigo != 0 and \"caixa-aprende-a-podar\" in recado\n                 and no_quadro(\"caixa-aprende-a-podar\"))\n\n            do_zero(molde.replace(MARCA_FECHA, velha + \"\\n\" + MARCA_FECHA))\n            codigo, recado = rodar(DEFEITO, \"com-linha-velha\", \"o que for\",\n                                   hoje, cwd=str(base))\n            caso(\"linha que o instrumento n\u00e3o sabe ler trava a escrita, em \"\n                 \"vez de sumir na reescrita do bloco\",\n                 codigo != 0 and chamadas(\"edit\") == 0\n                 and \"n\u00e3o sei ler\" in recado\n                 and velha in corpo.read_text(encoding=\"utf-8\"))\n            codigo, recado = podar(\"linha-velha\", amanha, cwd=str(base))\n            caso(\"e trava a poda tamb\u00e9m, sem comentar nada\",\n                 codigo != 0 and chamadas(\"edit\") == 0\n                 and chamadas(\"comment\") == 0 and \"n\u00e3o sei ler\" in recado)\n\n            com_configuracao(declarada)\n            do_zero(\"prosa de gente, sem bloco marcado nenhum\\n\")\n            codigo, recado = rodar(DEFEITO, \"sem-o-bloco\", \"o que for\", hoje,\n                                   cwd=str(base))\n            caso(\"caixa sem o bloco marcado n\u00e3o \u00e9 escrita\",\n                 codigo != 0 and chamadas(\"edit\") == 0)\n\n            do_zero()\n            codigo, recado = rodar(DEFEITO, \"no-ensaio\", \"o que for\", hoje,\n                                   cwd=str(base), ensaio=True)\n            caso(\"o ensaio mostra o bloco e n\u00e3o escreve\",\n                 codigo == 0 and \"no-ensaio\" in recado\n                 and chamadas(\"edit\") == 0)\n\n            do_zero()\n            os.environ[\"CAIXA_TESTE_ENGOLE\"] = \"1\"\n            codigo, recado = rodar(DEFEITO, \"escrita-perdida\", \"o que for\",\n                                   hoje, cwd=str(base))\n            caso(\"escrita que se perdeu \u00e9 confessada, n\u00e3o \u00e9 dada por feita\",\n                 codigo != 0 and \"escrita-perdida\" in recado)\n        finally:\n            os.environ.clear()\n            os.environ.update(guardado)\n\n    este_modulo = sys.modules[__name__]\n    de_verdade = (este_modulo.ler_corpo, este_modulo.gravar_corpo)\n    gravado = {\"corpo\": \"\"}\n    endereco = {\"issue\": 40, \"repositorio\": \"exemplo/exemplo\", \"conta\": \"\"}\n    de_a = achado(MELHORIA, \"linha-da-sessao-a\", \"posta pela sess\u00e3o A\", hoje)\n    de_b = achado(DEFEITO, \"linha-da-sessao-b\", \"posta pela sess\u00e3o B\", hoje)\n\n    def com_a_leitura_atrasada(atrasado, que_some=\"\"):\n        leituras = {\"quantas\": 0}\n\n        def ler(_endereco):\n            leituras[\"quantas\"] += 1\n            return (atrasado if leituras[\"quantas\"] == 1\n                    else gravado[\"corpo\"]), \"\"\n\n        def gravar(_endereco, escrito):\n            gravado[\"corpo\"] = (corpo_sem(escrito, que_some) if que_some\n                                else escrito)\n            return \"\"\n\n        este_modulo.ler_corpo, este_modulo.gravar_corpo = ler, gravar\n\n    def identidades_gravadas():\n        return sorted(um[\"id\"] for um in _achados_do_corpo(gravado[\"corpo\"]))\n\n    try:\n        gravado[\"corpo\"] = corpo_com(molde, de_b)\n        com_a_leitura_atrasada(molde)\n        codigo, recado = por_na_caixa(endereco, de_a)\n        caso(\"sess\u00e3o que leu o quadro atrasada p\u00f5e a linha dela sem apagar \"\n             \"a linha da outra sess\u00e3o\",\n             codigo == 0 and identidades_gravadas()\n             == [\"linha-da-sessao-a\", \"linha-da-sessao-b\"])\n\n        gravado[\"corpo\"] = corpo_com(molde, de_b)\n        com_a_leitura_atrasada(gravado[\"corpo\"],\n                               que_some=\"linha-da-sessao-b\")\n        codigo, recado = por_na_caixa(endereco, de_a)\n        caso(\"linha de outra sess\u00e3o que some entre a grava\u00e7\u00e3o e a releitura \"\n             \"sai com c\u00f3digo 2, nunca 0\",\n             codigo == 2 and \"linha-da-sessao-b\" in recado)\n\n        gravado[\"corpo\"] = corpo_com(corpo_com(molde, de_a), de_b)\n        com_a_leitura_atrasada(corpo_com(molde, de_a))\n        onde, atrasado, _ = achar_a_linha([endereco], \"linha-da-sessao-a\")\n        codigo, recado = podar_da_caixa(onde, atrasado, \"linha-da-sessao-a\",\n                                        \"o registro do fechamento\")\n        caso(\"a poda que leu o quadro atrasada tira a linha pedida sem \"\n             \"apagar a linha da outra sess\u00e3o\",\n             codigo == 0 and identidades_gravadas()\n             == [\"linha-da-sessao-b\"])\n    finally:\n        este_modulo.ler_corpo, este_modulo.gravar_corpo = de_verdade\n\n    total = len(rodados)\n    if falhas:\n        for falha in falhas:\n            print(f\"  [{falha}]\")\n        print(f\"FALHOU: {len(falhas)} de {total} casos\")\n        return 1\n    print(f\"OK: {total} casos \u2014 identidade, etiqueta do tipo, bloco marcado, \"\n          \"recusa, escrita e poda\")\n    return 0\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser(description=DESCRICAO_DA_CLI)\n    ap.add_argument(\"acao\", choices=TIPOS + (PODA, RELATO), help=AJUDA_ACAO)\n    ap.add_argument(\"--id\", default=\"\", dest=\"identidade\", help=AJUDA_ID)\n    ap.add_argument(\"--assunto\", default=\"\", help=AJUDA_ASSUNTO)\n    ap.add_argument(\"--corpo\", default=\"\", help=AJUDA_CORPO)\n    ap.add_argument(\"--motivo\", default=\"\", help=AJUDA_MOTIVO)\n    ap.add_argument(\"--quando\", default=date.today().isoformat(),\n                    help=AJUDA_QUANDO)\n    ap.add_argument(\"--cwd\", default=\"\", help=AJUDA_CWD)\n    ap.add_argument(\"--ensaio\", action=\"store_true\", help=AJUDA_ENSAIO)\n    ap.add_argument(\"--quadro\", default=\"\", help=AJUDA_QUADRO)\n    ap.add_argument(\"--seu\", action=\"append\", default=[], help=AJUDA_SEU)\n    a = ap.parse_args()\n    if a.acao == RELATO:\n        codigo, recado = relatar(a.corpo, a.cwd, a.ensaio, a.quadro, a.seu)\n    elif a.acao == PODA:\n        codigo, recado = podar(a.identidade, a.quando, a.cwd, a.motivo,\n                               a.ensaio, a.quadro)\n    else:\n        codigo, recado = rodar(a.acao, a.identidade, a.assunto, a.quando,\n                               a.cwd, a.ensaio, a.quadro, a.corpo)\n    print(recado, file=sys.stderr if codigo else sys.stdout)\n    return codigo\n\n\nif __name__ == \"__main__\":\n    for canal in (sys.stdin, sys.stdout, sys.stderr):\n        if not getattr(canal, \"closed\", True) and hasattr(canal, \"reconfigure\"):\n            canal.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    sys.exit(testar() if BANDEIRA_DE_TESTE in sys.argv else main())\n"]
