#[".agents/evidencia/evidencia.py", "import argparse\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nimport tempfile\nfrom datetime import datetime\nfrom pathlib import Path\n\nAQUI = Path(__file__).resolve().parent\nESQUEMA_PADRAO = AQUI / \"recibo.schema.json\"\n\nBASH_QUE_MORA_AO_LADO_DO_GIT = ((\"bin\", \"bash.exe\"),\n                                (\"usr\", \"bin\", \"bash.exe\"))\n\n\ndef bash_do_sistema():\n    import shutil\n    bash_nu_resolveria_para_o_subsistema_linux = shutil.which(\"bash\")\n    if os.name != \"nt\":\n        return bash_nu_resolveria_para_o_subsistema_linux\n    git = shutil.which(\"git\")\n    for pasta in (Path(git).resolve().parents if git else []):\n        for relativo in BASH_QUE_MORA_AO_LADO_DO_GIT:\n            achado = pasta.joinpath(*relativo)\n            if achado.is_file():\n                return str(achado)\n    return bash_nu_resolveria_para_o_subsistema_linux\n\nMOTIVO_DESLIGADA = \"desligada\"\nMOTIVO_MORTA = \"morta\"\nMOTIVO_RECIBO_INVALIDO = \"recibo-invalido\"\nMOTIVO_TETO_ESGOTADO = \"teto-esgotado\"\nMOTIVOS = (MOTIVO_DESLIGADA, MOTIVO_MORTA, MOTIVO_RECIBO_INVALIDO,\n           MOTIVO_TETO_ESGOTADO)\n\nVEREDITO_SEGUE = \"segue\"\nVEREDITO_PARA = \"para\"\nORIGEM_ENCADEADOR = \"encadeador\"\n\nSUPORTADAS = {\"type\", \"required\", \"properties\", \"additionalProperties\", \"enum\",\n              \"const\", \"pattern\", \"minimum\", \"minLength\", \"maxLength\", \"items\",\n              \"allOf\", \"if\", \"then\", \"else\", \"not\"}\nANOTACOES = {\"$schema\", \"$id\", \"title\", \"$comment\", \"description\"}\nTIPOS = {\"object\": dict, \"array\": list, \"string\": str,\n         \"integer\": int, \"number\": (int, float), \"boolean\": bool}\n\nCAMPOS_DO_CODIGO = (\"etapa\", \"trabalho\", \"quando\", \"ciclo\")\nCAMPOS_CONDICIONAIS = (\"proximo\", \"pergunta\", \"motivo\", \"origem\", \"provado\")\nCAMPOS_RESERVADOS_AO_SINTETICO = (\"origem\", \"motivo\")\nCAMPO_DOS_TURNOS = \"turnos\"\nCAMPO_DO_CUSTO = \"custo\"\nCAMPO_DA_DURACAO = \"duracao\"\nCAMPO_DA_ASSINATURA = \"assinatura\"\n\nORDEM_MINIMA = 1\nORDEM_MAXIMA = 99\nQUANTOS_ERROS_NO_DETALHE = 5\nPREFIXO_TEMPORARIO = \".evidencia-\"\nSUFIXO_TEMPORARIO = \".tmp\"\n\nROTULO_DA_EVIDENCIA = \"evid\u00eancia\"\nROTULO_ARG_ETAPA = \"argumento --etapa\"\nROTULO_ARG_TRABALHO = \"argumento --trabalho\"\nROTULO_ARG_TETO = \"argumento --teto\"\nROTULO_ARG_CUSTO = \"argumento --custo\"\nROTULO_ARG_DURACAO = \"argumento --duracao\"\n\nERRO_PALAVRA_DESCONHECIDA = (\"{}: o validador n\u00e3o conhece {} \u2014 atualize \"\n                             \"evidencia.py junto com o contrato\")\nERRO_TIPO = \"{}: deveria ser {}\"\nERRO_ENUM = \"{}: {!r} n\u00e3o est\u00e1 em {}\"\nERRO_CONST = \"{}: deveria ser {!r}\"\nERRO_PATTERN = \"{}: {!r} n\u00e3o casa com {}\"\nERRO_MIN_LENGTH = \"{}: precisa de ao menos {} caractere\"\nERRO_MAX_LENGTH = \"{}: passa de {} caracteres\"\nERRO_MINIMO = \"{}: {} \u00e9 menor que o m\u00ednimo {}\"\nERRO_CAMPO_OBRIGATORIO = \"{}: falta o campo obrigat\u00f3rio {!r}\"\nERRO_CAMPO_FORA_DO_CONTRATO = \"{}: campo fora do contrato: {}\"\nERRO_CAMPO_PROIBIDO = \"{}: campo proibido neste contexto: {}\"\nERRO_ESQUEMA_PROIBIDO = \"{}: casa com um esquema proibido\"\nERRO_CALENDARIO = (\"evidencia.quando: {!r} n\u00e3o existe no calend\u00e1rio real \"\n                   \"(regra escrita no contrato: fromisoformat al\u00e9m do \"\n                   \"padr\u00e3o)\")\n\nDETALHE_AUSENTE = \"sem detalhe registrado\"\nFALTA_DESLIGADA = (\"etapa desligada no roteiro \u2014 nada executou, nada foi \"\n                   \"colhido (skip sim\u00e9trico)\")\nFALTA_MORTA = \"a etapa morreu sem deixar evid\u00eancia: {}\"\nPROXIMO_MORTA = (\"A etapa {} terminou sem evid\u00eancia ({}). Leia o log da \"\n                 \"etapa, corrija a causa e reexecute o trabalho {} a partir \"\n                 \"dela.\")\nFALTA_RECIBO_INVALIDO = \"a evid\u00eancia devolvida n\u00e3o segue o contrato: {}\"\nPROXIMO_RECIBO_INVALIDO = (\"A etapa {} devolveu evid\u00eancia fora do contrato \"\n                           \"({}). Corrija a etapa para devolver o \"\n                           \"structured_output no contrato recibo.schema.json \"\n                           \"e reexecute o trabalho {} a partir dela.\")\nFALTA_TETO_ESGOTADO = \"o teto de {} ciclos esgotou\"\nPROXIMO_TETO_ESGOTADO = (\"O teto de {} ciclos esgotou no trabalho {}. Este \"\n                         \"para \u00e9 do dono: releia as evid\u00eancias para \"\n                         \"anteriores e decida se o trabalho continua, muda de \"\n                         \"rumo ou morre.\")\n\nERRO_MOTIVO_DESCONHECIDO = \"motivo desconhecido: {!r} (vale: {})\"\nERRO_DEFEITO_NO_SINTETICO = (\"defeito na evid\u00eancia sint\u00e9tica \u2014 corrija \"\n                             \"evidencia.py: {}\")\nERRO_ENTRADA_VAZIA = \"entrada vazia \u2014 a etapa n\u00e3o devolveu evid\u00eancia nenhuma\"\nERRO_NAO_E_OBJETO = \"a entrada n\u00e3o \u00e9 um objeto JSON de evid\u00eancia\"\nERRO_JSON_QUEBRADO = \"JSON quebrado: {}\"\n\nERRO_CONTRATO_ILEGIVEL = \"n\u00e3o consegui ler o contrato em {}: {}\"\nERRO_LEITURA = \"n\u00e3o consegui ler {}: {}\"\nERRO_STDOUT = \"o stdout falhou: {}\"\nERRO_STDOUT_APOS_VALIDA = \"evid\u00eancia v\u00e1lida, mas o stdout falhou: {}\"\nERRO_STDOUT_APOS_ESCRITA = \"evid\u00eancia escrita em {}, mas o stdout falhou: {}\"\nERRO_DE_USO = \"erro de uso: {}\"\nPROBLEMA_ORDEM = (\"argumento --ordem: {} fora de 1..99 (vira o prefixo de \"\n                  \"dois d\u00edgitos do arquivo)\")\nPROBLEMA_CUSTO = \"argumento --custo: n\u00e3o \u00e9 JSON ({})\"\nPROBLEMA_DIR = (\"argumento --dir: vazio ou com quebra de linha \u2014 o caminho \"\n                \"impresso no stdout \u00e9 lido linha a linha\")\nERRO_AMBIENTE_NA_ENTRADA = (\"erro de ambiente ao ler --entrada {}: {} \u2014 nada \"\n                            \"escrito\")\nERRO_COLISAO = (\"colis\u00e3o de evid\u00eancia \u2014 o arquivo j\u00e1 existe, e sobrescrever \"\n                \"seria perder evid\u00eancia em sil\u00eancio (a regra \u00e9 um escritor \"\n                \"s\u00f3): {}\")\nERRO_AMBIENTE_NADA_ESCRITO = \"erro de ambiente \u2014 nada escrito: {}\"\nERRO_DE_AMBIENTE = \"erro de ambiente: {}\"\nOK_EVIDENCIA_VALIDA = \"evid\u00eancia v\u00e1lida\"\n\nAJUDA_VALIDAR = \"valida uma evid\u00eancia contra o contrato\"\nAJUDA_ARQUIVO = \"caminho do JSON, ou - para stdin\"\nAJUDA_DIR = \"diret\u00f3rio-base das evid\u00eancias\"\nAJUDA_MATERIALIZAR = \"escreve a evid\u00eancia a partir do stdout da sess\u00e3o\"\nAJUDA_ENTRADA = \"arquivo com o stdout da sess\u00e3o; - = stdin\"\nAJUDA_TURNOS = (\"turnos que a sess\u00e3o gastou (num_turns); opcional, \"\n                \"carimbado pelo c\u00f3digo na evid\u00eancia\")\nAJUDA_CUSTO = (\"custo que a sess\u00e3o devolveu (total_cost_usd e usage), como \"\n               \"JSON no formato do contrato; opcional, carimbado pelo \"\n               \"c\u00f3digo na evid\u00eancia\")\nAJUDA_DURACAO = (\"segundos de rel\u00f3gio que a etapa levou; opcional, \"\n                 \"carimbado pelo c\u00f3digo na evid\u00eancia\")\nAJUDA_ASSINATURA = (\"resumo do comando e do prompt da etapa no momento da \"\n                    \"prova; opcional, carimbado pelo c\u00f3digo na evid\u00eancia \u2014 \"\n                    \"a retomada s\u00f3 pula a etapa cuja assinatura bate\")\nAJUDA_SINTETICO = \"escreve a evid\u00eancia de etapa desligada/morta/teto\"\nAJUDA_ESQUEMA_SESSAO = \"o contrato enxuto da sess\u00e3o, para --json-schema\"\n\nDETALHE_EXIT = \"exit {}\"\nTESTE_ACEITA_RECUSOU = \"ACEITA [{}]: recusou \u2014 {}\"\nTESTE_RECUSA_ACEITOU = \"RECUSA [{}]: aceitou o que devia recusar\"\nTESTE_RECUSA_MOTIVO_ERRADO = \"RECUSA [{}]: recusou pelo motivo errado \u2014 {}\"\nTESTE_COMPORTAMENTO = \"COMPORTAMENTO [{}]\"\nTESTE_FALHA = \"FALHOU: {}\"\nTESTE_RESUMO_FALHA = \"FALHOU: {} de {} casos\"\nTESTE_RESUMO_OK = (\"OK: {} casos \u2014 {} aceitos, {} recusados, {} de \"\n                   \"comportamento\")\n\n\ndef _casa_padrao(padrao: str, dado: str) -> bool:\n    if padrao.endswith(\"$\") and not padrao.endswith(r\"\\$\"):\n        padrao = padrao[:-1] + r\"\\Z\"\n    return re.search(padrao, dado) is not None\n\n\ndef _tipo_certo(tipo: str, dado) -> bool:\n    if isinstance(dado, bool):\n        return tipo == \"boolean\"\n    if tipo == \"integer\" and isinstance(dado, float):\n        return dado.is_integer()\n    return isinstance(dado, TIPOS[tipo])\n\n\ndef _erros_de_valor(esquema: dict, dado, caminho: str) -> list:\n    erros = []\n    if \"enum\" in esquema and dado not in esquema[\"enum\"]:\n        erros.append(ERRO_ENUM.format(caminho, dado, esquema[\"enum\"]))\n    if \"const\" in esquema and dado != esquema[\"const\"]:\n        erros.append(ERRO_CONST.format(caminho, esquema[\"const\"]))\n    if \"pattern\" in esquema and isinstance(dado, str) \\\n            and not _casa_padrao(esquema[\"pattern\"], dado):\n        erros.append(ERRO_PATTERN.format(caminho, dado, esquema[\"pattern\"]))\n    if \"minLength\" in esquema and isinstance(dado, str) \\\n            and len(dado) < esquema[\"minLength\"]:\n        erros.append(ERRO_MIN_LENGTH.format(caminho, esquema[\"minLength\"]))\n    if \"maxLength\" in esquema and isinstance(dado, str) \\\n            and len(dado) > esquema[\"maxLength\"]:\n        erros.append(ERRO_MAX_LENGTH.format(caminho, esquema[\"maxLength\"]))\n    if \"minimum\" in esquema and isinstance(dado, (int, float)) \\\n            and not isinstance(dado, bool) and dado < esquema[\"minimum\"]:\n        erros.append(ERRO_MINIMO.format(caminho, dado, esquema[\"minimum\"]))\n    return erros\n\n\ndef _erros_de_objeto(esquema: dict, dado, caminho: str) -> list:\n    if not isinstance(dado, dict):\n        return []\n    erros = []\n    for exigido in esquema.get(\"required\", []):\n        if exigido not in dado:\n            erros.append(ERRO_CAMPO_OBRIGATORIO.format(caminho, exigido))\n    propriedades = esquema.get(\"properties\", {})\n    if esquema.get(\"additionalProperties\") is False:\n        sobras = sorted(set(dado) - set(propriedades))\n        if sobras:\n            erros.append(ERRO_CAMPO_FORA_DO_CONTRATO.format(caminho, sobras))\n    for nome, sub in propriedades.items():\n        if nome in dado:\n            erros += _erros(sub, dado[nome], f\"{caminho}.{nome}\")\n    return erros\n\n\ndef _erros_de_lista(esquema: dict, dado, caminho: str) -> list:\n    if not isinstance(dado, list) or \"items\" not in esquema:\n        return []\n    erros = []\n    for n, item in enumerate(dado):\n        erros += _erros(esquema[\"items\"], item, f\"{caminho}[{n}]\")\n    return erros\n\n\ndef _erros_do_proibido(proibido: dict, dado, caminho: str) -> list:\n    if _erros(proibido, dado, caminho):\n        return []\n    if set(proibido) == {\"required\"}:\n        return [ERRO_CAMPO_PROIBIDO.format(caminho, proibido[\"required\"])]\n    return [ERRO_ESQUEMA_PROIBIDO.format(caminho)]\n\n\ndef _erros_de_combinacao(esquema: dict, dado, caminho: str) -> list:\n    erros = []\n    for sub in esquema.get(\"allOf\", []):\n        erros += _erros(sub, dado, caminho)\n    if \"if\" in esquema:\n        casa = not _erros(esquema[\"if\"], dado, caminho)\n        ramo = esquema.get(\"then\") if casa else esquema.get(\"else\")\n        if ramo:\n            erros += _erros(ramo, dado, caminho)\n    if \"not\" in esquema:\n        erros += _erros_do_proibido(esquema[\"not\"], dado, caminho)\n    return erros\n\n\ndef _erros(esquema: dict, dado, caminho: str) -> list:\n    desconhecidas = set(esquema) - SUPORTADAS - ANOTACOES\n    if desconhecidas:\n        return [ERRO_PALAVRA_DESCONHECIDA.format(caminho,\n                                                 sorted(desconhecidas))]\n    tipo = esquema.get(\"type\")\n    if tipo and not _tipo_certo(tipo, dado):\n        return [ERRO_TIPO.format(caminho, tipo)]\n    return (_erros_de_valor(esquema, dado, caminho)\n            + _erros_de_objeto(esquema, dado, caminho)\n            + _erros_de_lista(esquema, dado, caminho)\n            + _erros_de_combinacao(esquema, dado, caminho))\n\n\ndef carregar_esquema(caminho: Path = ESQUEMA_PADRAO) -> dict:\n    try:\n        return json.loads(caminho.read_text(encoding=\"utf-8\"))\n    except (OSError, json.JSONDecodeError) as erro:\n        print(ERRO_CONTRATO_ILEGIVEL.format(caminho, erro), file=sys.stderr)\n        sys.exit(2)\n\n\ndef _sem_comentario(no):\n    if isinstance(no, dict):\n        return {chave: _sem_comentario(valor) for chave, valor in no.items()\n                if chave != \"$comment\"}\n    if isinstance(no, list):\n        return [_sem_comentario(item) for item in no]\n    return no\n\n\ndef projetar_para_sessao(esquema: dict) -> dict:\n    guia = _sem_comentario({chave: valor for chave, valor in esquema.items()\n                            if chave != \"allOf\"})\n    guia[\"required\"] = [campo for campo in guia[\"required\"]\n                        if campo not in CAMPOS_DO_CODIGO]\n    for campo in CAMPOS_CONDICIONAIS:\n        regra = esquema[\"properties\"].get(campo, {}).get(\"$comment\")\n        if regra:\n            guia[\"properties\"][campo][\"description\"] = regra\n    return guia\n\n\ndef _data_existe_no_calendario(quando: str) -> bool:\n    try:\n        datetime.fromisoformat(quando)\n    except ValueError:\n        return False\n    return True\n\n\ndef validar_evidencia(dado, esquema: dict) -> list:\n    erros = _erros(esquema, dado, ROTULO_DA_EVIDENCIA)\n    if not erros and not _data_existe_no_calendario(dado[\"quando\"]):\n        erros.append(ERRO_CALENDARIO.format(dado[\"quando\"]))\n    return erros\n\n\ndef agora() -> str:\n    return datetime.now().astimezone().isoformat(timespec=\"seconds\")\n\n\ndef caminho_da_evidencia(dir_base: str, trabalho: str, ordem: int, etapa: str):\n    pasta = Path(dir_base) / trabalho\n    padrao = re.compile(rf\"{ordem:02d}-{re.escape(etapa)}-c([0-9]+)\\.json\\Z\")\n    existentes = [int(casado.group(1)) for arquivo in pasta.glob(\"*.json\")\n                  if (casado := padrao.fullmatch(arquivo.name))]\n    i = 1 + max(existentes, default=0)\n    return pasta / f\"{ordem:02d}-{etapa}-c{i}.json\", i\n\n\ndef escrever_atomico(caminho: Path, evidencia: dict) -> Path:\n    caminho.parent.mkdir(parents=True, exist_ok=True)\n    texto = json.dumps(evidencia, ensure_ascii=False, indent=2) + \"\\n\"\n    descritor, tmp = tempfile.mkstemp(dir=caminho.parent,\n                                      prefix=PREFIXO_TEMPORARIO,\n                                      suffix=SUFIXO_TEMPORARIO)\n    try:\n        with os.fdopen(descritor, \"w\", encoding=\"utf-8\") as arquivo:\n            arquivo.write(texto)\n            arquivo.flush()\n            os.fsync(arquivo.fileno())\n        os.link(tmp, caminho)\n        os.unlink(tmp)\n    finally:\n        if os.path.exists(tmp):\n            os.unlink(tmp)\n    return caminho\n\n\ndef _carimbo_do_codigo(turnos, custo, duracao, assinatura=None) -> dict:\n    medido = {}\n    if turnos:\n        medido[CAMPO_DOS_TURNOS] = turnos\n    if custo:\n        medido[CAMPO_DO_CUSTO] = custo\n    if duracao is not None:\n        medido[CAMPO_DA_DURACAO] = duracao\n    if assinatura:\n        medido[CAMPO_DA_ASSINATURA] = assinatura\n    return medido\n\n\ndef _corpo_do_motivo(motivo, etapa, trabalho, teto, detalhe) -> dict:\n    dito = detalhe or DETALHE_AUSENTE\n    if motivo == MOTIVO_DESLIGADA:\n        return {\"faltas\": [FALTA_DESLIGADA]}\n    if motivo == MOTIVO_MORTA:\n        return {\"faltas\": [FALTA_MORTA.format(dito)],\n                \"proximo\": PROXIMO_MORTA.format(etapa, dito, trabalho)}\n    if motivo == MOTIVO_RECIBO_INVALIDO:\n        return {\"faltas\": [FALTA_RECIBO_INVALIDO.format(dito)],\n                \"proximo\": PROXIMO_RECIBO_INVALIDO.format(etapa, dito,\n                                                          trabalho)}\n    return {\"faltas\": [FALTA_TETO_ESGOTADO.format(teto)],\n            \"proximo\": PROXIMO_TETO_ESGOTADO.format(teto, trabalho)}\n\n\ndef sintetizar(dir_base, trabalho, etapa, ordem, teto, motivo, detalhe,\n               esquema, turnos=None, custo=None, duracao=None,\n               assinatura=None):\n    if motivo not in MOTIVOS:\n        sys.exit(ERRO_MOTIVO_DESCONHECIDO.format(motivo, \", \".join(MOTIVOS)))\n    caminho, i = caminho_da_evidencia(dir_base, trabalho, ordem, etapa)\n    evidencia = {\n        \"etapa\": etapa,\n        \"trabalho\": trabalho,\n        \"quando\": agora(),\n        \"veredito\": (VEREDITO_SEGUE if motivo == MOTIVO_DESLIGADA\n                     else VEREDITO_PARA),\n        \"provado\": [],\n        \"suposto\": [],\n        \"faltas\": [],\n        \"origem\": ORIGEM_ENCADEADOR,\n        \"motivo\": motivo,\n        \"ciclo\": {\"i\": i, \"teto\": teto},\n    }\n    evidencia.update(_corpo_do_motivo(motivo, etapa, trabalho, teto, detalhe))\n    evidencia.update(_carimbo_do_codigo(turnos, custo, duracao, assinatura))\n\n    erros = validar_evidencia(evidencia, esquema)\n    if erros:\n        print(ERRO_DEFEITO_NO_SINTETICO.format(\"; \".join(erros)),\n              file=sys.stderr)\n        sys.exit(2)\n    return escrever_atomico(caminho, evidencia)\n\n\ndef _candidato_da_entrada(texto: str):\n    texto = (texto or \"\").strip()\n    if not texto:\n        return None, ERRO_ENTRADA_VAZIA\n    try:\n        bruto = json.loads(texto)\n    except (ValueError, RecursionError) as decodificacao:\n        return None, ERRO_JSON_QUEBRADO.format(decodificacao)\n    if isinstance(bruto, dict) and \"structured_output\" in bruto:\n        bruto = bruto[\"structured_output\"]\n    if isinstance(bruto, dict):\n        return bruto, \"\"\n    return None, ERRO_NAO_E_OBJETO\n\n\ndef materializar(dir_base, trabalho, etapa, ordem, teto, texto, esquema,\n                 turnos=None, custo=None, duracao=None, assinatura=None):\n    candidato, erro = _candidato_da_entrada(texto)\n    if candidato is not None:\n        for reservado in CAMPOS_RESERVADOS_AO_SINTETICO:\n            candidato.pop(reservado, None)\n        caminho, i = caminho_da_evidencia(dir_base, trabalho, ordem, etapa)\n        candidato[\"etapa\"] = etapa\n        candidato[\"trabalho\"] = trabalho\n        candidato[\"quando\"] = agora()\n        candidato[\"ciclo\"] = {\"i\": i, \"teto\": teto}\n        for medido in (CAMPO_DOS_TURNOS, CAMPO_DO_CUSTO, CAMPO_DA_DURACAO,\n                       CAMPO_DA_ASSINATURA):\n            candidato.pop(medido, None)\n        candidato.update(_carimbo_do_codigo(turnos, custo, duracao,\n                                            assinatura))\n        erros = validar_evidencia(candidato, esquema)\n        if not erros:\n            return escrever_atomico(caminho, candidato), 0\n        erro = \"; \".join(erros[:QUANTOS_ERROS_NO_DETALHE])\n\n    caminho = sintetizar(dir_base, trabalho, etapa, ordem, teto,\n                         MOTIVO_RECIBO_INVALIDO, erro, esquema,\n                         turnos=turnos, custo=custo, duracao=duracao,\n                         assinatura=assinatura)\n    return caminho, 3\n\n\ndef montar_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(prog=\"evidencia.py\", add_help=True)\n    sub = parser.add_subparsers(dest=\"comando\", required=True)\n\n    valida = sub.add_parser(\"validar\", help=AJUDA_VALIDAR)\n    valida.add_argument(\"arquivo\", help=AJUDA_ARQUIVO)\n\n    def comuns(p):\n        p.add_argument(\"--dir\", required=True, help=AJUDA_DIR)\n        p.add_argument(\"--trabalho\", required=True)\n        p.add_argument(\"--etapa\", required=True)\n        p.add_argument(\"--ordem\", required=True, type=int)\n        p.add_argument(\"--teto\", required=True, type=int)\n\n    def medidas(p):\n        p.add_argument(\"--turnos\", type=int, help=AJUDA_TURNOS)\n        p.add_argument(\"--custo\", help=AJUDA_CUSTO)\n        p.add_argument(\"--duracao\", type=float, help=AJUDA_DURACAO)\n        p.add_argument(\"--assinatura\", help=AJUDA_ASSINATURA)\n\n    materializa = sub.add_parser(\"materializar\", help=AJUDA_MATERIALIZAR)\n    comuns(materializa)\n    medidas(materializa)\n    materializa.add_argument(\"--entrada\", default=\"-\", help=AJUDA_ENTRADA)\n\n    sintetiza = sub.add_parser(\"sintetico\", help=AJUDA_SINTETICO)\n    comuns(sintetiza)\n    medidas(sintetiza)\n    sintetiza.add_argument(\"--motivo\", required=True, choices=MOTIVOS)\n    sintetiza.add_argument(\"--detalhe\", default=\"\")\n\n    sub.add_parser(\"esquema-sessao\", help=AJUDA_ESQUEMA_SESSAO)\n    return parser\n\n\ndef _descartar_stdout():\n    try:\n        os.dup2(os.open(os.devnull, os.O_WRONLY), 1)\n    except OSError:\n        pass\n\n\ndef _dizer_caminho(caminho: Path, codigo: int) -> int:\n    try:\n        print(caminho)\n        sys.stdout.flush()\n    except OSError as saida:\n        print(ERRO_STDOUT_APOS_ESCRITA.format(caminho, saida), file=sys.stderr)\n        _descartar_stdout()\n        return 2\n    return codigo\n\n\ndef _imprimir_esquema_da_sessao(esquema: dict) -> int:\n    guia = projetar_para_sessao(esquema)\n    try:\n        print(json.dumps(guia, ensure_ascii=False))\n        sys.stdout.flush()\n    except OSError as saida:\n        print(ERRO_STDOUT.format(saida), file=sys.stderr)\n        _descartar_stdout()\n        return 2\n    return 0\n\n\ndef _validar_arquivo(pedido: str, esquema: dict) -> int:\n    if pedido == \"-\":\n        texto = sys.stdin.read()\n    else:\n        try:\n            texto = Path(pedido).read_text(encoding=\"utf-8\")\n        except OSError as erro:\n            print(ERRO_LEITURA.format(pedido, erro), file=sys.stderr)\n            return 2\n    try:\n        dado = json.loads(texto)\n    except (ValueError, RecursionError) as erro:\n        print(ERRO_JSON_QUEBRADO.format(erro), file=sys.stderr)\n        return 2\n    erros = validar_evidencia(dado, esquema)\n    if erros:\n        for linha in erros:\n            print(linha, file=sys.stderr)\n        return 2\n    try:\n        print(OK_EVIDENCIA_VALIDA)\n        sys.stdout.flush()\n    except OSError as saida:\n        print(ERRO_STDOUT_APOS_VALIDA.format(saida), file=sys.stderr)\n        _descartar_stdout()\n        return 2\n    return 0\n\n\ndef _custo_do_argumento(texto):\n    if not texto:\n        return None, \"\"\n    try:\n        return json.loads(texto), \"\"\n    except (ValueError, RecursionError) as quebra:\n        return None, PROBLEMA_CUSTO.format(quebra)\n\n\ndef _problemas_dos_argumentos(args, esquema: dict) -> list:\n    problemas = _erros(esquema[\"properties\"][\"etapa\"], args.etapa,\n                       ROTULO_ARG_ETAPA)\n    problemas += _erros(esquema[\"properties\"][\"trabalho\"], args.trabalho,\n                        ROTULO_ARG_TRABALHO)\n    problemas += _erros(esquema[\"properties\"][\"ciclo\"][\"properties\"][\"teto\"],\n                        args.teto, ROTULO_ARG_TETO)\n    if not ORDEM_MINIMA <= args.ordem <= ORDEM_MAXIMA:\n        problemas.append(PROBLEMA_ORDEM.format(args.ordem))\n    if not args.dir or \"\\n\" in args.dir or \"\\r\" in args.dir:\n        problemas.append(PROBLEMA_DIR)\n    custo, problema = _custo_do_argumento(getattr(args, \"custo\", None))\n    if problema:\n        problemas.append(problema)\n    elif custo is not None:\n        problemas += _erros(esquema[\"properties\"][CAMPO_DO_CUSTO], custo,\n                            ROTULO_ARG_CUSTO)\n    duracao = getattr(args, \"duracao\", None)\n    if duracao is not None:\n        problemas += _erros(esquema[\"properties\"][CAMPO_DA_DURACAO], duracao,\n                            ROTULO_ARG_DURACAO)\n    return problemas\n\n\ndef _texto_da_entrada(entrada: str):\n    if entrada == \"-\":\n        return sys.stdin.read()\n    try:\n        return Path(entrada).read_text(encoding=\"utf-8\")\n    except FileNotFoundError:\n        return \"\"\n    except OSError as ambiente:\n        print(ERRO_AMBIENTE_NA_ENTRADA.format(entrada, ambiente),\n              file=sys.stderr)\n        return None\n\n\ndef _materializar_pela_linha_de_comando(args, esquema: dict) -> int:\n    texto = _texto_da_entrada(args.entrada)\n    if texto is None:\n        return 2\n    custo, _ = _custo_do_argumento(args.custo)\n    try:\n        caminho, codigo = materializar(args.dir, args.trabalho, args.etapa,\n                                       args.ordem, args.teto, texto, esquema,\n                                       turnos=args.turnos, custo=custo,\n                                       duracao=args.duracao,\n                                       assinatura=args.assinatura)\n    except FileExistsError as colisao:\n        print(ERRO_COLISAO.format(colisao), file=sys.stderr)\n        return 2\n    except OSError as ambiente:\n        print(ERRO_AMBIENTE_NADA_ESCRITO.format(ambiente), file=sys.stderr)\n        return 2\n    return _dizer_caminho(caminho, codigo)\n\n\ndef _sintetizar_pela_linha_de_comando(args, esquema: dict) -> int:\n    custo, _ = _custo_do_argumento(args.custo)\n    try:\n        caminho = sintetizar(args.dir, args.trabalho, args.etapa, args.ordem,\n                             args.teto, args.motivo, args.detalhe, esquema,\n                             turnos=args.turnos, custo=custo,\n                             duracao=args.duracao,\n                             assinatura=args.assinatura)\n    except FileExistsError as colisao:\n        print(ERRO_COLISAO.format(colisao), file=sys.stderr)\n        return 2\n    except OSError as ambiente:\n        print(ERRO_AMBIENTE_NADA_ESCRITO.format(ambiente), file=sys.stderr)\n        return 2\n    return _dizer_caminho(caminho, 0)\n\n\ndef main(argv) -> int:\n    args = montar_parser().parse_args(argv)\n    esquema = carregar_esquema()\n\n    if args.comando == \"esquema-sessao\":\n        return _imprimir_esquema_da_sessao(esquema)\n    if args.comando == \"validar\":\n        return _validar_arquivo(args.arquivo, esquema)\n\n    problemas = _problemas_dos_argumentos(args, esquema)\n    if problemas:\n        for problema in problemas:\n            print(ERRO_DE_USO.format(problema), file=sys.stderr)\n        return 2\n\n    if args.comando == \"materializar\":\n        return _materializar_pela_linha_de_comando(args, esquema)\n    return _sintetizar_pela_linha_de_comando(args, esquema)\n\n\nEXEMPLO_DA_ISSUE = r'''\n{\n  \"etapa\": \"verificacao-adversarial\",\n  \"trabalho\": \"issue-42\",\n  \"quando\": \"2026-08-16T16:02:47-03:00\",\n  \"veredito\": \"para\",\n  \"provado\": [\n    { \"afirmacao\": \"o endpoint responde 200 no ambiente de teste\",\n      \"comando\": \"python -c \\\"import os, urllib.request; print(urllib.request.urlopen(os.environ['URL_HOMOLOG'] + '/relatorio').status)\\\"\",\n      \"saida\": \"200\" }\n  ],\n  \"suposto\": [],\n  \"faltas\": [\n    \"a issue pedia paginacao e a resposta veio inteira: 3.412 itens num corpo so\"\n  ],\n  \"proximo\": \"Implemente a paginacao pedida na issue-42: parametros pagina e tamanho, teto de 100. Prove com dois comandos: a pagina 2 vindo diferente da 1, e uma pagina alem do fim vindo vazia com 200.\",\n  \"ciclo\": { \"i\": 1, \"teto\": 3 }\n}\n'''\n\n\ndef _base(**troca):\n    evidencia = {\n        \"etapa\": \"fantoche\", \"trabalho\": \"issue-0\",\n        \"quando\": \"2026-08-16T12:00:00-03:00\", \"veredito\": \"segue\",\n        \"provado\": [], \"suposto\": [], \"faltas\": [],\n        \"ciclo\": {\"i\": 1, \"teto\": 3},\n    }\n    evidencia.update(troca)\n    return {chave: valor for chave, valor in evidencia.items()\n            if valor is not ...}\n\n\nACEITA = [\n    (\"o exemplo do corpo da issue\", json.loads(EXEMPLO_DA_ISSUE)),\n    (\"segue m\u00ednimo, listas vazias\", _base()),\n    (\"segue com a assinatura da etapa carimbada pelo c\u00f3digo\",\n     _base(assinatura=\"0123456789ab\")),\n    (\"pergunta com o campo pergunta\", _base(\n        veredito=\"pergunta\",\n        pergunta=\"Recomendo A porque custa um comando; a alternativa B refaz \"\n                 \"a etapa. Sigo com A?\")),\n    (\"skip sint\u00e9tico da etapa desligada\", _base(\n        origem=\"encadeador\", motivo=\"desligada\",\n        faltas=[\"etapa desligada no roteiro \u2014 nada executou\"])),\n    (\"para sint\u00e9tico de etapa morta\", _base(\n        veredito=\"para\", origem=\"encadeador\", motivo=\"morta\",\n        faltas=[\"a etapa morreu sem deixar evid\u00eancia: timeout\"],\n        proximo=\"A etapa fantoche terminou sem evid\u00eancia (timeout). Leia o log, \"\n                \"corrija a causa e reexecute a partir dela.\")),\n    (\"provado com comando e sa\u00edda\", _base(provado=[\n        {\"afirmacao\": \"o teste passa\", \"comando\": \"pytest -q\", \"saida\": \"3 passed\"}])),\n    (\"ciclo 1.0 \u2014 draft-07 aceita inteiro de fra\u00e7\u00e3o zero\",\n     _base(ciclo={\"i\": 1.0, \"teto\": 3})),\n    (\"custo carimbado pelo encadeador\", _base(custo={\n        \"usd\": 0.1234, \"tokens\": {\"entrada\": 10, \"saida\": 2,\n                                  \"cache-lido\": 100, \"cache-criado\": 50}})),\n    (\"dura\u00e7\u00e3o carimbada pelo encadeador\", _base(duracao=93.4)),\n    (\"dura\u00e7\u00e3o zero \u2014 etapa que nem come\u00e7ou\", _base(duracao=0)),\n]\n\nRECUSA = [\n    (\"veredito fora dos 3 valores\", _base(veredito=\"quase\"), \"n\u00e3o est\u00e1 em\"),\n    (\"assinatura fora do padr\u00e3o de doze hexadecimais\", _base(assinatura=\"x\"),\n     \"[0-9a-f]{12}\"),\n    (\"provado sem saida desce para suposto\", _base(provado=[\n        {\"afirmacao\": \"funciona\", \"comando\": \"pytest -q\"}]), \"obrigat\u00f3rio 'saida'\"),\n    (\"proximo em veredito segue\", _base(proximo=\"fa\u00e7a X\"), \"proibido\"),\n    (\"para sem proximo\", {**_base(veredito=\"para\")}, \"obrigat\u00f3rio 'proximo'\"),\n    (\"pergunta sem o campo pergunta\", _base(veredito=\"pergunta\"),\n     \"obrigat\u00f3rio 'pergunta'\"),\n    (\"pergunta em veredito segue\", _base(pergunta=\"sigo?\"), \"proibido\"),\n    (\"etapa com mai\u00fascula (a li\u00e7\u00e3o do painel de controle)\",\n     _base(etapa=\"Cetico\"),\n     \"n\u00e3o casa\"),\n    (\"etapa com quebra de linha no fim (o $ do ECMA n\u00e3o casa)\",\n     _base(etapa=\"cetico\\n\"), \"n\u00e3o casa\"),\n    (\"etapa de 65 caracteres (viraria nome de arquivo)\",\n     _base(etapa=\"a\" * 65), \"passa de 64\"),\n    (\"trabalho com barra (viraria travessia de pasta)\",\n     _base(trabalho=\"a/b\"), \"n\u00e3o casa\"),\n    (\"campo fora do contrato\", _base(cor=\"verde\"), \"fora do contrato\"),\n    (\"ciclo.i zero\", _base(ciclo={\"i\": 0, \"teto\": 3}), \"menor que o m\u00ednimo\"),\n    (\"ciclo sem teto\", _base(ciclo={\"i\": 1}), \"obrigat\u00f3rio 'teto'\"),\n    (\"quando fora do ISO\", _base(quando=\"16/08/2026 16:02\"), \"n\u00e3o casa\"),\n    (\"quando com m\u00eas 13\", _base(quando=\"2026-13-01T00:00:00-03:00\"),\n     \"calend\u00e1rio\"),\n    (\"motivo sem origem encadeador\", _base(motivo=\"morta\"), \"proibido\"),\n    (\"morta que segue (motivo de parada com veredito segue)\",\n     _base(origem=\"encadeador\", motivo=\"morta\"), \"deveria ser 'para'\"),\n    (\"desligada que para\",\n     _base(veredito=\"para\", proximo=\"x\", origem=\"encadeador\",\n           motivo=\"desligada\"), \"deveria ser 'segue'\"),\n    (\"origem encadeador sem motivo\", _base(origem=\"encadeador\"),\n     \"obrigat\u00f3rio 'motivo'\"),\n    (\"provado como texto solto\", _base(provado=\"tudo certo\"),\n     \"deveria ser array\"),\n    (\"suposto com item n\u00e3o-texto\", _base(suposto=[{\"x\": 1}]),\n     \"deveria ser string\"),\n    (\"custo com usd negativo\", _base(custo={\n        \"usd\": -1, \"tokens\": {\"entrada\": 0, \"saida\": 0,\n                              \"cache-lido\": 0, \"cache-criado\": 0}}),\n     \"menor que o m\u00ednimo\"),\n    (\"custo sem tokens\", _base(custo={\"usd\": 0.1}), \"obrigat\u00f3rio 'tokens'\"),\n    (\"dura\u00e7\u00e3o negativa \u2014 rel\u00f3gio que anda para tr\u00e1s\",\n     _base(duracao=-1), \"menor que o m\u00ednimo\"),\n    (\"dura\u00e7\u00e3o como texto\", _base(duracao=\"93s\"), \"deveria ser number\"),\n]\n\nFANTOCHE = \"\"\"\\\nimport json, sys\nprint(json.dumps({\"structured_output\": {\n    \"etapa\": \"mentira\", \"trabalho\": \"mentira\",\n    \"quando\": \"1999-01-01T00:00:00Z\", \"veredito\": \"segue\",\n    \"provado\": [{\"afirmacao\": \"a fantoche rodou\",\n                 \"comando\": \"python fantoche.py\", \"saida\": \"ok\"}],\n    \"suposto\": [], \"faltas\": [], \"ciclo\": {\"i\": 99, \"teto\": 99}}}))\n\"\"\"\n\nFANTOCHE_QUEBRADA = 'print(\"{ isto nao e json\")\\n'\nFANTOCHE_QUE_MORRE = \"import sys; sys.exit(9)\\n\"\nETAPA_DESLIGADA = None\n\n\ndef _cli(argumentos, entrada=None):\n    return subprocess.run(\n        [sys.executable, str(Path(__file__).resolve())] + argumentos,\n        input=entrada, capture_output=True, text=True,\n        encoding=\"utf-8\", errors=\"replace\", timeout=60)\n\n\ndef _rodar_fantoche(pasta, nome, script):\n    arquivo = Path(pasta) / f\"fantoche-{nome}.py\"\n    arquivo.write_text(script, encoding=\"utf-8\")\n    return subprocess.run([sys.executable, str(arquivo)],\n                          capture_output=True, text=True, encoding=\"utf-8\", errors=\"replace\", timeout=60)\n\n\ndef _encadear(pasta, trabalho, etapas):\n    resultados = []\n    for ordem, nome, script in etapas:\n        base = [\"--dir\", str(pasta), \"--trabalho\", trabalho, \"--etapa\", nome,\n                \"--ordem\", str(ordem), \"--teto\", \"3\"]\n        if script is ETAPA_DESLIGADA:\n            saida = _cli([\"sintetico\"] + base + [\"--motivo\", \"desligada\"])\n        else:\n            fantoche = _rodar_fantoche(pasta, nome, script)\n            if fantoche.returncode != 0:\n                saida = _cli([\"sintetico\"] + base +\n                             [\"--motivo\", \"morta\", \"--detalhe\",\n                              DETALHE_EXIT.format(fantoche.returncode)])\n            else:\n                saida = _cli([\"materializar\"] + base, entrada=fantoche.stdout)\n        resultados.append(saida)\n    return resultados\n\n\ndef _ler(pasta, trabalho, nome_arquivo):\n    return json.loads((Path(pasta) / trabalho / nome_arquivo)\n                      .read_text(encoding=\"utf-8\"))\n\n\ndef _o_codigo_manda_nos_campos(pasta, caso):\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-campos\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\": json.loads(EXEMPLO_DA_ISSUE)}))\n    escrito = _ler(pasta, \"t-campos\", \"01-alfa-c1.json\")\n    caso(\"etapa vem do argumento, n\u00e3o do modelo\", escrito[\"etapa\"] == \"alfa\")\n    caso(\"trabalho vem do argumento\", escrito[\"trabalho\"] == \"t-campos\")\n    caso(\"quando vem do rel\u00f3gio daqui\", escrito[\"quando\"] != \"2026-08-16T16:02:47-03:00\")\n    caso(\"ciclo vem da contagem, n\u00e3o do JSON\", escrito[\"ciclo\"][\"i\"] == 1)\n    caso(\"veredito do modelo \u00e9 preservado\", escrito[\"veredito\"] == \"para\")\n\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-campos\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\": json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"contagem de ciclo: segundo evid\u00eancia \u00e9 c2\",\n         (Path(pasta) / \"t-campos\" / \"01-alfa-c2.json\").exists())\n\n    forjado = _base(origem=\"encadeador\", motivo=\"desligada\")\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-forja\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n                    entrada=json.dumps(forjado))\n    escrito = _ler(pasta, \"t-forja\", \"01-alfa-c1.json\")\n    caso(\"modelo n\u00e3o forja evid\u00eancia sint\u00e9tica\",\n         resposta.returncode == 0 and \"origem\" not in escrito)\n\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-turnos\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--turnos\", \"11\"],\n         entrada=json.dumps({\"structured_output\":\n                             json.loads(EXEMPLO_DA_ISSUE)}))\n    escrito = _ler(pasta, \"t-turnos\", \"01-alfa-c1.json\")\n    caso(\"turnos vem do argumento \u2014 o carimbo \u00e9 do c\u00f3digo\",\n         escrito.get(\"turnos\") == 11)\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-sem-turnos\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\":\n                             json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"sem o argumento o campo n\u00e3o nasce \u2014 opcional de verdade\",\n         \"turnos\" not in _ler(pasta, \"t-sem-turnos\", \"01-alfa-c1.json\"))\n    com_forja = dict(json.loads(EXEMPLO_DA_ISSUE), turnos=999)\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-turno-forjado\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\": com_forja}))\n    caso(\"modelo n\u00e3o escreve turnos: o forjado some sem o argumento\",\n         \"turnos\" not in _ler(pasta, \"t-turno-forjado\", \"01-alfa-c1.json\"))\n\n    custo = ('{\"usd\": 0.1234, \"tokens\": {\"entrada\": 10, \"saida\": 2, '\n             '\"cache-lido\": 100, \"cache-criado\": 50}}')\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-custo\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--custo\", custo],\n         entrada=json.dumps({\"structured_output\":\n                             json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"custo vem do argumento \u2014 o carimbo \u00e9 do c\u00f3digo\",\n         _ler(pasta, \"t-custo\", \"01-alfa-c1.json\").get(\"custo\")\n         == json.loads(custo))\n    com_forja = dict(json.loads(EXEMPLO_DA_ISSUE),\n                     custo={\"usd\": 9.9, \"tokens\": {}})\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-custo-forjado\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\": com_forja}))\n    caso(\"modelo n\u00e3o escreve custo: o forjado some sem o argumento\",\n         \"custo\" not in _ler(pasta, \"t-custo-forjado\", \"01-alfa-c1.json\"))\n    resposta = _cli([\"materializar\", \"--dir\", pasta,\n                     \"--trabalho\", \"t-custo-quebrado\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n                     \"--custo\", \"{quebrado\"],\n                    entrada=json.dumps({\"structured_output\":\n                                        json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"--custo que n\u00e3o \u00e9 JSON \u00e9 erro de uso: exit 2 e nada escrito\",\n         resposta.returncode == 2\n         and not (Path(pasta) / \"t-custo-quebrado\").exists())\n\n\ndef _a_duracao_e_o_custo_sao_carimbo_do_codigo(pasta, caso):\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-duracao\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--duracao\", \"93.4\"],\n         entrada=json.dumps({\"structured_output\":\n                             json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"dura\u00e7\u00e3o vem do argumento \u2014 o carimbo \u00e9 do c\u00f3digo\",\n         _ler(pasta, \"t-duracao\", \"01-alfa-c1.json\").get(\"duracao\") == 93.4)\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-duracao-zero\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--duracao\", \"0\"],\n         entrada=json.dumps({\"structured_output\":\n                             json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"dura\u00e7\u00e3o zero \u00e9 medida, n\u00e3o aus\u00eancia \u2014 o falsy n\u00e3o apaga o campo\",\n         _ler(pasta, \"t-duracao-zero\", \"01-alfa-c1.json\").get(\"duracao\") == 0)\n    com_forja = dict(json.loads(EXEMPLO_DA_ISSUE), duracao=0.001)\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-duracao-forjada\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\": com_forja}))\n    caso(\"modelo n\u00e3o escreve dura\u00e7\u00e3o: a forjada some sem o argumento\",\n         \"duracao\" not in _ler(pasta, \"t-duracao-forjada\",\n                               \"01-alfa-c1.json\"))\n    resposta = _cli([\"materializar\", \"--dir\", pasta,\n                     \"--trabalho\", \"t-duracao-quebrada\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n                     \"--duracao\", \"ontem\"],\n                    entrada=json.dumps({\"structured_output\":\n                                        json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"--duracao que n\u00e3o \u00e9 n\u00famero \u00e9 erro de uso: exit 2 e nada escrito\",\n         resposta.returncode == 2\n         and not (Path(pasta) / \"t-duracao-quebrada\").exists())\n    custo = ('{\"usd\": 0.5, \"tokens\": {\"entrada\": 10, \"saida\": 2, '\n             '\"cache-lido\": 100, \"cache-criado\": 50}}')\n    _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-morta-cara\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--motivo\", \"morta\", \"--detalhe\", \"limite de uso da sess\u00e3o\",\n          \"--turnos\", \"7\", \"--custo\", custo, \"--duracao\", \"612.5\"])\n    morta = _ler(pasta, \"t-morta-cara\", \"01-alfa-c1.json\")\n    caso(\"sess\u00e3o morta grava o que gastou: o retrabalho tem pre\u00e7o\",\n         morta.get(\"custo\") == json.loads(custo)\n         and morta.get(\"turnos\") == 7 and morta.get(\"duracao\") == 612.5)\n    caso(\"e continua sendo evid\u00eancia sint\u00e9tica de parada\",\n         morta.get(\"origem\") == \"encadeador\" and morta.get(\"motivo\") == \"morta\"\n         and morta.get(\"veredito\") == \"para\")\n    _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-morta-nao-medida\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--motivo\", \"morta\", \"--detalhe\", \"morreu cedo\"])\n    caso(\"morte sem medi\u00e7\u00e3o n\u00e3o vira zero: os campos ficam ausentes\",\n         all(campo not in _ler(pasta, \"t-morta-nao-medida\",\n                               \"01-alfa-c1.json\")\n             for campo in (\"custo\", \"turnos\", \"duracao\")))\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-assinada\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--assinatura\", \"abcdef012345\"],\n         entrada=json.dumps({\"structured_output\":\n                             json.loads(EXEMPLO_DA_ISSUE)}))\n    caso(\"a assinatura da etapa vem do argumento \u2014 o carimbo \u00e9 do c\u00f3digo\",\n         _ler(pasta, \"t-assinada\", \"01-alfa-c1.json\").get(\"assinatura\")\n         == \"abcdef012345\")\n    com_forja = dict(json.loads(EXEMPLO_DA_ISSUE), assinatura=\"ffffffffffff\")\n    _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-assinatura-forjada\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n         entrada=json.dumps({\"structured_output\": com_forja}))\n    caso(\"modelo n\u00e3o assina a pr\u00f3pria prova: a assinatura forjada some sem \"\n         \"o argumento\",\n         \"assinatura\" not in _ler(pasta, \"t-assinatura-forjada\",\n                                  \"01-alfa-c1.json\"))\n\n\ndef _entrada_ruim_vira_para_sintetico(pasta, caso):\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-quebra\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n                    entrada=\"{ isto nao e json\")\n    escrito = _ler(pasta, \"t-quebra\", \"01-alfa-c1.json\")\n    caso(\"JSON quebrado vira para sint\u00e9tico com exit 3\",\n         resposta.returncode == 3 and escrito[\"veredito\"] == \"para\"\n         and escrito[\"motivo\"] == \"recibo-invalido\")\n\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-vazio\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n                    entrada=\"\")\n    escrito = _ler(pasta, \"t-vazio\", \"01-alfa-c1.json\")\n    caso(\"evid\u00eancia ausente vira para sint\u00e9tico\",\n         resposta.returncode == 3 and escrito[\"motivo\"] == \"recibo-invalido\")\n\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-contrato\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n                    entrada=json.dumps(_base(veredito=\"quase\")))\n    escrito = _ler(pasta, \"t-contrato\", \"01-alfa-c1.json\")\n    caso(\"evid\u00eancia fora do contrato vira para sint\u00e9tico\",\n         resposta.returncode == 3 and escrito[\"motivo\"] == \"recibo-invalido\"\n         and \"veredito\" in escrito[\"faltas\"][0])\n\n    custo_ja_medido = ('{\"usd\": 0.75, \"tokens\": {\"entrada\": 10, \"saida\": 2, '\n                       '\"cache-lido\": 100, \"cache-criado\": 50}}')\n    resposta = _cli([\"materializar\", \"--dir\", pasta,\n                     \"--trabalho\", \"t-quebra-com-carimbo\", \"--etapa\", \"alfa\",\n                     \"--ordem\", \"1\", \"--teto\", \"3\", \"--turnos\", \"7\",\n                     \"--custo\", custo_ja_medido, \"--duracao\", \"12.5\"],\n                    entrada=\"{ isto nao e json\")\n    escrito = _ler(pasta, \"t-quebra-com-carimbo\", \"01-alfa-c1.json\")\n    caso(\"recibo inv\u00e1lido n\u00e3o apaga o que o c\u00f3digo j\u00e1 mediu: a queda para o \"\n         \"sint\u00e9tico carrega turnos, custo e dura\u00e7\u00e3o\",\n         resposta.returncode == 3 and escrito[\"motivo\"] == \"recibo-invalido\"\n         and escrito.get(\"turnos\") == 7 and escrito.get(\"duracao\") == 12.5\n         and (escrito.get(\"custo\") or {}).get(\"usd\") == 0.75)\n\n\ndef _a_escrita_nao_deixa_temporario(pasta, caso):\n    caso(\"nenhum tempor\u00e1rio sobra no diret\u00f3rio\",\n         not list(Path(pasta).rglob(\"*.tmp\")))\n    resposta = _cli([\"validar\", str(Path(pasta) / \"t-quebra\" / \"01-alfa-c1.json\")])\n    caso(\"sint\u00e9tico passa no pr\u00f3prio validador\", resposta.returncode == 0)\n\n\ndef _tres_fantoches_encadeadas(pasta, caso):\n    _encadear(pasta, \"t-skip\", [(1, \"alfa\", FANTOCHE),\n                                (2, \"bravo\", ETAPA_DESLIGADA),\n                                (3, \"charlie\", FANTOCHE)])\n    meio = _ler(pasta, \"t-skip\", \"02-bravo-c1.json\")\n    fim = _ler(pasta, \"t-skip\", \"03-charlie-c1.json\")\n    caso(\"desligar a do meio n\u00e3o impede a terceira\",\n         fim[\"veredito\"] == \"segue\" and \"origem\" not in fim)\n    caso(\"a evid\u00eancia do meio registra o skip\",\n         meio[\"origem\"] == \"encadeador\" and meio[\"motivo\"] == \"desligada\"\n         and meio[\"veredito\"] == \"segue\")\n\n    _encadear(pasta, \"t-lixo\", [(1, \"alfa\", FANTOCHE),\n                                (2, \"bravo\", FANTOCHE_QUEBRADA),\n                                (3, \"charlie\", FANTOCHE)])\n    meio = _ler(pasta, \"t-lixo\", \"02-bravo-c1.json\")\n    caso(\"fantoche que devolve lixo vira para sint\u00e9tico\",\n         meio[\"veredito\"] == \"para\" and meio[\"motivo\"] == \"recibo-invalido\")\n\n\ndef _o_guia_da_sessao_carrega_a_lei_que_julga(caso):\n    resposta = _cli([\"esquema-sessao\"])\n    guia = json.loads(resposta.stdout)\n    caso(\"esquema-sessao tira o allOf e mant\u00e9m o resto\",\n         \"allOf\" not in guia and \"properties\" in guia\n         and \"allOf\" in carregar_esquema())\n\n    lei = carregar_esquema()\n    caso(\"esquema-sessao n\u00e3o manda $comment nem exige campo do c\u00f3digo\",\n         '\"$comment\"' not in resposta.stdout\n         and not set(CAMPOS_DO_CODIGO) & set(guia[\"required\"])\n         and all(campo in guia[\"properties\"] for campo in CAMPOS_DO_CODIGO)\n         and \"$comment\" in lei\n         and set(CAMPOS_DO_CODIGO) <= set(lei[\"required\"]))\n\n    condicionais = (\"proximo\", \"pergunta\", \"motivo\", \"origem\")\n    caso(\"o contrato da sess\u00e3o diz QUANDO cada campo condicional vale\",\n         all(guia[\"properties\"][campo].get(\"description\")\n             for campo in condicionais))\n    caso(\"a regra do proximo chega na sess\u00e3o, n\u00e3o s\u00f3 no allOf\",\n         \"para\" in guia[\"properties\"][\"proximo\"].get(\"description\", \"\"))\n\n    regra_da_prova = guia[\"properties\"][\"provado\"].get(\"description\", \"\")\n    caso(\"a sess\u00e3o recebe COMO se escreve a prova, n\u00e3o s\u00f3 o que provar\",\n         bool(regra_da_prova))\n    caso(\"e a regra chega inteira, as seis frases\",\n         all(m in regra_da_prova for m in (\"(1)\", \"(2)\", \"(3)\", \"(4)\",\n                                           \"(5)\", \"(6)\")))\n    caso(\"comando \u00e9 comando: a regra diz isso com todas as letras\",\n         \"nunca prosa\" in regra_da_prova)\n    caso(\"e o marcador de corte \u00e9 ensinado onde a sess\u00e3o o l\u00ea\",\n         \"(...)\" in regra_da_prova)\n\n\ndef _fantoche_morta_e_json_fundo(pasta, caso):\n    _encadear(pasta, \"t-morte\", [(1, \"alfa\", FANTOCHE),\n                                 (2, \"bravo\", FANTOCHE_QUE_MORRE),\n                                 (3, \"charlie\", FANTOCHE)])\n    meio = _ler(pasta, \"t-morte\", \"02-bravo-c1.json\")\n    caso(\"fantoche morta vira para sint\u00e9tico com motivo morta\",\n         meio[\"veredito\"] == \"para\" and meio[\"motivo\"] == \"morta\"\n         and \"exit 9\" in meio[\"proximo\"])\n\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-fundo\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n                    entrada=\"[\" * 100000)\n    escrito = _ler(pasta, \"t-fundo\", \"01-alfa-c1.json\")\n    caso(\"JSON fundo demais vira para sint\u00e9tico, nunca traceback\",\n         resposta.returncode == 3 and escrito[\"motivo\"] == \"recibo-invalido\")\n\n\ndef _argumento_fora_do_contrato_e_erro_de_uso(pasta, caso):\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-uso\",\n                     \"--etapa\", \"Alfa\", \"--ordem\", \"1\", \"--teto\", \"3\"],\n                    entrada=\"{}\")\n    caso(\"etapa mai\u00fascula no argumento: exit 2 e nada escrito\",\n         resposta.returncode == 2 and \"erro de uso\" in resposta.stderr\n         and not (Path(pasta) / \"t-uso\").exists())\n    resposta = _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-uso\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"0\",\n                     \"--motivo\", \"morta\"])\n    caso(\"teto zero no argumento: exit 2\", resposta.returncode == 2)\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-uso\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"0\", \"--teto\", \"3\"],\n                    entrada=\"{}\")\n    caso(\"ordem fora de 1..99: exit 2\", resposta.returncode == 2)\n\n\ndef _a_contagem_de_ciclo_nao_sobrescreve(pasta, caso):\n    for _ in range(2):\n        _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-buraco\",\n              \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n              \"--motivo\", \"desligada\"])\n    (Path(pasta) / \"t-buraco\" / \"01-alfa-c1.json\").unlink()\n    intacto = _ler(pasta, \"t-buraco\", \"01-alfa-c2.json\")\n    _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-buraco\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--motivo\", \"desligada\"])\n    caso(\"buraco na sequ\u00eancia vira c3 e o c2 fica intacto\",\n         (Path(pasta) / \"t-buraco\" / \"01-alfa-c3.json\").exists()\n         and _ler(pasta, \"t-buraco\", \"01-alfa-c2.json\") == intacto)\n\n    _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-prefixo\",\n          \"--etapa\", \"a-c1\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--motivo\", \"desligada\"])\n    _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-prefixo\",\n          \"--etapa\", \"a\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--motivo\", \"desligada\"])\n    caso(\"contagem n\u00e3o cruza etapas de prefixo parecido\",\n         (Path(pasta) / \"t-prefixo\" / \"01-a-c1.json\").exists())\n\n\ndef _a_colisao_de_caminho_falha_alto(pasta, caso):\n    alvo = Path(pasta) / \"t-colisao\" / \"01-alfa-c1.json\"\n    escrever_atomico(alvo, json.loads(EXEMPLO_DA_ISSUE))\n    try:\n        escrever_atomico(alvo, json.loads(EXEMPLO_DA_ISSUE))\n        caso(\"colis\u00e3o de caminho falha alto, nunca sobrescreve\", False)\n    except FileExistsError:\n        caso(\"colis\u00e3o de caminho falha alto, nunca sobrescreve\", True)\n    caso(\"colis\u00e3o n\u00e3o deixa tempor\u00e1rio para tr\u00e1s\",\n         not list((Path(pasta) / \"t-colisao\").glob(\"*.tmp\")))\n\n\ndef _a_entrada_separa_ambiente_de_etapa_sem_saida(pasta, caso):\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-eisdir\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n                     \"--entrada\", pasta])\n    caso(\"entrada ileg\u00edvel \u00e9 erro de ambiente, sem evid\u00eancia de diagn\u00f3stico falso\",\n         resposta.returncode == 2 and not (Path(pasta) / \"t-eisdir\").exists())\n\n    resposta = _cli([\"materializar\", \"--dir\", pasta, \"--trabalho\", \"t-enoent\",\n                     \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n                     \"--entrada\", str(Path(pasta) / \"nao-existe.json\")])\n    caso(\"entrada inexistente vira para sint\u00e9tico (etapa sem sa\u00edda)\",\n         resposta.returncode == 3)\n\n\ndef _o_intruso_e_a_quebra_de_linha(pasta, caso):\n    pasta_intruso = Path(pasta) / \"t-intruso\"\n    pasta_intruso.mkdir()\n    (pasta_intruso / \"01-alfa-c\uff11\uff10.json\").write_text(\"{}\", encoding=\"utf-8\")\n    _cli([\"sintetico\", \"--dir\", pasta, \"--trabalho\", \"t-intruso\",\n          \"--etapa\", \"alfa\", \"--ordem\", \"1\", \"--teto\", \"3\",\n          \"--motivo\", \"desligada\"])\n    caso(\"intruso com d\u00edgito n\u00e3o-ASCII n\u00e3o dirige a contagem\",\n         (pasta_intruso / \"01-alfa-c1.json\").exists())\n\n    resposta = _cli([\"sintetico\", \"--dir\", f\"{pasta}/qu\\nebra\",\n                     \"--trabalho\", \"t-dir\", \"--etapa\", \"alfa\", \"--ordem\", \"1\",\n                     \"--teto\", \"3\", \"--motivo\", \"desligada\"])\n    caso(\"--dir com quebra de linha \u00e9 erro de uso\", resposta.returncode == 2)\n\n\ndef _o_stdout_quebrado_depois_da_escrita(pasta, caso):\n    if not os.path.exists(\"/dev/full\"):\n        return\n    with open(\"/dev/full\", \"w\") as ralo:\n        resposta = subprocess.run(\n            [sys.executable, str(Path(__file__).resolve()), \"sintetico\",\n             \"--dir\", pasta, \"--trabalho\", \"t-ralo\", \"--etapa\", \"alfa\",\n             \"--ordem\", \"1\", \"--teto\", \"3\", \"--motivo\", \"desligada\"],\n            stdout=ralo, stderr=subprocess.PIPE, text=True,\n            encoding=\"utf-8\", errors=\"replace\", timeout=60)\n    caso(\"stdout quebrado p\u00f3s-escrita: exit 2 e o stderr diz o caminho\",\n         resposta.returncode == 2\n         and \"evid\u00eancia escrita em\" in resposta.stderr\n         and (Path(pasta) / \"t-ralo\" / \"01-alfa-c1.json\").exists())\n\n\ndef _comportamento(pasta):\n    resultados = []\n\n    def caso(rotulo, condicao):\n        resultados.append((rotulo, bool(condicao)))\n\n    _o_codigo_manda_nos_campos(pasta, caso)\n    _a_duracao_e_o_custo_sao_carimbo_do_codigo(pasta, caso)\n    _entrada_ruim_vira_para_sintetico(pasta, caso)\n    _a_escrita_nao_deixa_temporario(pasta, caso)\n    _tres_fantoches_encadeadas(pasta, caso)\n    _o_guia_da_sessao_carrega_a_lei_que_julga(caso)\n    _fantoche_morta_e_json_fundo(pasta, caso)\n    _argumento_fora_do_contrato_e_erro_de_uso(pasta, caso)\n    _a_contagem_de_ciclo_nao_sobrescreve(pasta, caso)\n    _a_colisao_de_caminho_falha_alto(pasta, caso)\n    _a_entrada_separa_ambiente_de_etapa_sem_saida(pasta, caso)\n    _o_intruso_e_a_quebra_de_linha(pasta, caso)\n    _o_stdout_quebrado_depois_da_escrita(pasta, caso)\n    return resultados\n\n\ndef testar() -> int:\n    esquema = carregar_esquema()\n    falhas = []\n\n    for rotulo, evidencia in ACEITA:\n        erros = validar_evidencia(evidencia, esquema)\n        if erros:\n            falhas.append(TESTE_ACEITA_RECUSOU.format(rotulo,\n                                                      \"; \".join(erros)))\n\n    for rotulo, evidencia, trecho in RECUSA:\n        erros = validar_evidencia(evidencia, esquema)\n        if not erros:\n            falhas.append(TESTE_RECUSA_ACEITOU.format(rotulo))\n        elif not any(trecho in erro for erro in erros):\n            falhas.append(TESTE_RECUSA_MOTIVO_ERRADO.format(\n                rotulo, \"; \".join(erros)))\n\n    with tempfile.TemporaryDirectory(prefix=\"evidencia-teste-\") as pasta:\n        comportamento = _comportamento(pasta)\n    falhas += [TESTE_COMPORTAMENTO.format(rotulo)\n               for rotulo, passou in comportamento if not passou]\n\n    total = len(ACEITA) + len(RECUSA) + len(comportamento)\n    if falhas:\n        for falha in falhas:\n            print(TESTE_FALHA.format(falha))\n        print(TESTE_RESUMO_FALHA.format(len(falhas), total))\n        return 1\n    print(TESTE_RESUMO_OK.format(total, len(ACEITA), len(RECUSA),\n                                 len(comportamento)))\n    return 0\n\n\nif __name__ == \"__main__\":\n    for canal in (sys.stdin, sys.stdout, sys.stderr):\n        if not getattr(canal, \"closed\", True) and hasattr(canal, \"reconfigure\"):\n            canal.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    if \"--testar\" in sys.argv:\n        sys.exit(testar())\n    try:\n        sys.exit(main(sys.argv[1:]))\n    except OSError as ambiente:\n        print(ERRO_DE_AMBIENTE.format(ambiente), file=sys.stderr)\n        sys.exit(2)\n"]
#[".agents/evidencia/recibo.schema.json", "{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"title\": \"recibo \u2014 contrato v1\",\n  \"$comment\": \"draft-07 de prop\u00f3sito: o claude 2.1.233 recusa a meta-refer\u00eancia do draft 2020-12 no --json-schema ('no schema with key or ref'), e tudo que este contrato usa existe no draft-07. O contrato da esteira: toda etapa termina escrevendo este JSON. Quem materializa o arquivo \u00e9 sempre o encadeador (c\u00f3digo), nunca o modelo \u2014 etapa, trabalho, quando e ciclo v\u00eam do roteiro, do rel\u00f3gio e da contagem de arquivos. Um escritor s\u00f3: recibos de um trabalho saem de um \u00fanico encadeador, e a mesma etapa nunca escreve em paralelo \u2014 colis\u00e3o de arquivo falha alto, nunca sobrescreve. Os campos origem e motivo s\u00f3 aparecem em recibo sint\u00e9tico, escrito pelo encadeador quando a etapa foi desligada, morreu, devolveu recibo inv\u00e1lido ou esgotou o teto. Vers\u00e3o nova deste contrato \u00e9 arquivo novo (v2), nunca edi\u00e7\u00e3o calada deste.\",\n  \"type\": \"object\",\n  \"additionalProperties\": false,\n  \"required\": [\n    \"etapa\",\n    \"trabalho\",\n    \"quando\",\n    \"veredito\",\n    \"provado\",\n    \"suposto\",\n    \"faltas\",\n    \"ciclo\"\n  ],\n  \"properties\": {\n    \"etapa\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[a-z0-9][a-z0-9-]*$\",\n      \"maxLength\": 64,\n      \"$comment\": \"Nome fixo, min\u00fasculo \u2014 o painel do sistema estudado quebrou em sil\u00eancio por um P mai\u00fasculo. Vira nome de arquivo: o teto de 64 protege o limite do sistema de arquivos.\"\n    },\n    \"trabalho\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[a-z0-9][a-z0-9._-]*$\",\n      \"maxLength\": 64,\n      \"$comment\": \"Vira nome de pasta: sem barra, sem espa\u00e7o, sem ponto inicial, no m\u00e1ximo 64.\"\n    },\n    \"quando\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(Z|[+-][0-9]{2}:[0-9]{2})$\",\n      \"$comment\": \"Al\u00e9m do padr\u00e3o, o validador imp\u00f5e calend\u00e1rio real (fromisoformat do Python): m\u00eas 13 ou 30 de fevereiro n\u00e3o passam.\"\n    },\n    \"veredito\": {\n      \"enum\": [\n        \"segue\",\n        \"para\",\n        \"pergunta\"\n      ],\n      \"$comment\": \"S\u00f3 3 valores. N\u00e3o existe quase.\"\n    },\n    \"provado\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"required\": [\n          \"afirmacao\",\n          \"comando\",\n          \"saida\"\n        ],\n        \"properties\": {\n          \"afirmacao\": {\n            \"type\": \"string\",\n            \"minLength\": 1\n          },\n          \"comando\": {\n            \"type\": \"string\",\n            \"minLength\": 1\n          },\n          \"saida\": {\n            \"type\": \"string\"\n          },\n          \"tempo-limite\": {\n            \"type\": \"integer\",\n            \"minimum\": 1\n          }\n        }\n      },\n      \"$comment\": \"Item s\u00f3 entra com comando + saida \u2014 o que n\u00e3o tem os dois, o modelo escreve em suposto. Item incompleto torna o recibo inteiro inv\u00e1lido, e o encadeador o troca por um para sint\u00e9tico. A prova precisa ser RE-EXECUT\u00c1VEL: a confer\u00eancia roda o comando de novo no diret\u00f3rio da etapa e acusa se o stdout divergir OU se o exit n\u00e3o for 0 \u2014 declare comando idempotente, de sa\u00edda est\u00e1vel (nada de rel\u00f3gio, hash de artefato apagado, subir servi\u00e7o) e que n\u00e3o dependa de efeito de outro item. Armadilha comum: grep e diff respondem com exit 1 quando a resposta honesta \u00e9 'n\u00e3o achei'/'\u00e9 diferente' \u2014 quando a SA\u00cdDA j\u00e1 \u00e9 a prova, encerre com ' || true'. E \u00e2ncora EST\u00c1VEL: prova de git presa a ref m\u00f3vel (origin/<branch de integra\u00e7\u00e3o>..HEAD) envelhece quando a rodada \u00e9 entregue \u2014 ancore em SHA. COMO SE ESCREVE UM ITEM, e cada frase aqui existe porque foi violada e custou uma acusa\u00e7\u00e3o: (1) `comando` \u00e9 COMANDO, nunca prosa \u2014 'os padr\u00f5es sobre git ls-files' n\u00e3o roda; o que descreve a prova \u00e9 a `afirmacao`. (2) `saida` \u00e9 TRANSCRI\u00c7\u00c3O do que o comando imprimiu, nunca resumo, tradu\u00e7\u00e3o ou anota\u00e7\u00e3o sua \u2014 colar, n\u00e3o redigir. (3) Cortou peda\u00e7o da sa\u00edda? Declare o corte com `(...)` em linha pr\u00f3pria: a verifica\u00e7\u00e3o entende esse marcador e confere as pontas. (4) Comando silencioso no sucesso (`diff -q`, `cmp -s`, `grep -q`) declara `saida` VAZIA \u2014 ou ganha um `&& echo ok` para ter o que declarar. Inventar 'OK' \u00e9 acusa\u00e7\u00e3o na certa. (5) Ferramenta que fala por stderr (linter, compilador) precisa do `2>&1` DENTRO do comando declarado: sem ele o cano \u00e9 cego e a sa\u00edda vem vazia. (6) Aus\u00eancia se declara com CONTADOR \u2014 `... | wc -l` devolvendo `0` \u2014, nunca com frase entre par\u00eanteses: n\u00famero \u00e9 compar\u00e1vel, prosa n\u00e3o. N\u00famero que muda entre rodadas N\u00c3O entra na sa\u00edda declarada: dura\u00e7\u00e3o (`em 157s`), rel\u00f3gio, data, e contagem de sa\u00edda viva (`4 de 6 rotinas`, `194 casos`) fazem a prova parar de reproduzir na rodada seguinte. Declare a parte est\u00e1vel da sa\u00edda, ou escolha um comando cuja sa\u00edda n\u00e3o dependa do rel\u00f3gio nem do tamanho de hoje. (7) Prova LENTA declara o teto dela no pr\u00f3prio item \u2014 \\\"tempo-limite\\\": 300, em segundos \u2014, porque a re-execu\u00e7\u00e3o corta em 60 s por padr\u00e3o e mata a prova sem chegar a comparar a sa\u00edda: lenta n\u00e3o \u00e9 errada. (8) Comando cuja sa\u00edda MUDA DE FORMA com o ambiente (n\u00e3o s\u00f3 com o tempo) reprova por engano: `git show --stat` varia de largura conforme o terminal, e checagem de identidade (`gh`, `whoami`) varia conforme a conta ativa na m\u00e1quina que re-executa. Prefira uma forma fixa \u2014 `git show --stat=200,200` trava a largura; identidade de conta \u00e9 afirma\u00e7\u00e3o para o dono verificar, n\u00e3o prova re-execut\u00e1vel por qualquer m\u00e1quina.\"\n    },\n    \"suposto\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"string\",\n        \"minLength\": 1\n      }\n    },\n    \"faltas\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"string\",\n        \"minLength\": 1\n      }\n    },\n    \"proximo\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"$comment\": \"S\u00f3 existe no para, escrito por quem reprovou \u2014 nunca 'tente de novo'.\"\n    },\n    \"pergunta\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"$comment\": \"S\u00f3 existe no veredito pergunta: uma s\u00f3, com a recomenda\u00e7\u00e3o primeiro.\"\n    },\n    \"origem\": {\n      \"enum\": [\n        \"etapa\",\n        \"encadeador\"\n      ],\n      \"$comment\": \"Ausente = o conte\u00fado veio do structured_output da etapa. 'encadeador' = recibo sint\u00e9tico.\"\n    },\n    \"motivo\": {\n      \"enum\": [\n        \"desligada\",\n        \"morta\",\n        \"recibo-invalido\",\n        \"teto-esgotado\"\n      ],\n      \"$comment\": \"Os tr\u00eas estados que a cr\u00edtica achou sem nome, mais o teto. S\u00f3 existe em recibo sint\u00e9tico.\"\n    },\n    \"ciclo\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"required\": [\n        \"i\",\n        \"teto\"\n      ],\n      \"properties\": {\n        \"i\": {\n          \"type\": \"integer\",\n          \"minimum\": 1\n        },\n        \"teto\": {\n          \"type\": \"integer\",\n          \"minimum\": 1\n        }\n      },\n      \"$comment\": \"Informativo. O contador can\u00f4nico \u00e9 a contagem de recibos no diret\u00f3rio, feita pelo encadeador.\"\n    },\n    \"duracao\": {\n      \"type\": \"number\",\n      \"minimum\": 0,\n      \"$comment\": \"opcional; segundos de rel\u00f3gio que a etapa levou, do disparo ao fim \u2014 escrito s\u00f3 pelo encadeador, nunca pelo modelo. Mede a etapa inteira, incluindo a retomada por teto de turnos, porque \u00e9 o tempo que o dono espera. Ausente = n\u00e3o medido: etapa que morreu antes do cron\u00f4metro fechar n\u00e3o vira zero, pelo mesmo motivo do custo. Serve para comparar o antes e o depois de um conserto no motor \u2014 sem ele, 'a reabertura custa caro' fica sempre n\u00e3o provado.\"\n    },\n    \"assinatura\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[0-9a-f]{12}$\",\n      \"$comment\": \"opcional; escrito s\u00f3 pelo encadeador: resumo do comando e do prompt da etapa no momento da prova, doze hexadecimais. A retomada s\u00f3 pula a etapa provada cuja assinatura bate com a do roteiro atual \u2014 evid\u00eancia de comando editado n\u00e3o vale como prova. Ausente = anterior ao campo: a retomada pula pelo veredito e avisa. O modelo n\u00e3o escreve este campo. Decidido pelo dono.\"\n    },\n    \"turnos\": {\n      \"type\": \"integer\",\n      \"minimum\": 1,\n      \"$comment\": \"opcional; escrito s\u00f3 pelo encadeador, com o num_turns que a sess\u00e3o devolveu \u2014 o modelo n\u00e3o escreve este campo. Aprovado pelo dono.\"\n    },\n    \"custo\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"required\": [\n        \"usd\",\n        \"tokens\"\n      ],\n      \"properties\": {\n        \"usd\": {\n          \"type\": \"number\",\n          \"minimum\": 0\n        },\n        \"tokens\": {\n          \"type\": \"object\",\n          \"additionalProperties\": false,\n          \"required\": [\n            \"entrada\",\n            \"saida\",\n            \"cache-lido\",\n            \"cache-criado\"\n          ],\n          \"properties\": {\n            \"entrada\": {\n              \"type\": \"integer\",\n              \"minimum\": 0\n            },\n            \"saida\": {\n              \"type\": \"integer\",\n              \"minimum\": 0\n            },\n            \"cache-lido\": {\n              \"type\": \"integer\",\n              \"minimum\": 0\n            },\n            \"cache-criado\": {\n              \"type\": \"integer\",\n              \"minimum\": 0\n            }\n          }\n        }\n      },\n      \"$comment\": \"opcional; escrito s\u00f3 pelo encadeador, com o total_cost_usd e o usage que a sess\u00e3o devolveu \u2014 o modelo n\u00e3o escreve este campo. O valor \u00e9 a estimativa do pr\u00f3prio CLI e serve para comparar execu\u00e7\u00e3o com execu\u00e7\u00e3o, n\u00e3o para fatura. Ausente = custo n\u00e3o medido: falha de medi\u00e7\u00e3o nunca vira zero. Aprovado pelo dono. Os tokens v\u00eam do acumulado por modelo que a sess\u00e3o devolve (modelUsage), que \u00e9 o que gera o usd \u2014 nunca do usage do \u00faltimo resultado, que \u00e9 por consulta e n\u00e3o se compara com ele. Acumulado presente mas quebrado \u00e9 n\u00e3o medido, nunca o da \u00faltima consulta.\"\n    }\n  },\n  \"allOf\": [\n    {\n      \"if\": {\n        \"required\": [\n          \"veredito\"\n        ],\n        \"properties\": {\n          \"veredito\": {\n            \"const\": \"para\"\n          }\n        }\n      },\n      \"then\": {\n        \"required\": [\n          \"proximo\"\n        ]\n      },\n      \"else\": {\n        \"not\": {\n          \"required\": [\n            \"proximo\"\n          ]\n        }\n      }\n    },\n    {\n      \"if\": {\n        \"required\": [\n          \"veredito\"\n        ],\n        \"properties\": {\n          \"veredito\": {\n            \"const\": \"pergunta\"\n          }\n        }\n      },\n      \"then\": {\n        \"required\": [\n          \"pergunta\"\n        ]\n      },\n      \"else\": {\n        \"not\": {\n          \"required\": [\n            \"pergunta\"\n          ]\n        }\n      }\n    },\n    {\n      \"if\": {\n        \"required\": [\n          \"origem\"\n        ],\n        \"properties\": {\n          \"origem\": {\n            \"const\": \"encadeador\"\n          }\n        }\n      },\n      \"then\": {\n        \"required\": [\n          \"motivo\"\n        ]\n      },\n      \"else\": {\n        \"not\": {\n          \"required\": [\n            \"motivo\"\n          ]\n        }\n      }\n    },\n    {\n      \"if\": {\n        \"required\": [\n          \"motivo\"\n        ],\n        \"properties\": {\n          \"motivo\": {\n            \"enum\": [\n              \"morta\",\n              \"recibo-invalido\",\n              \"teto-esgotado\"\n            ]\n          }\n        }\n      },\n      \"then\": {\n        \"properties\": {\n          \"veredito\": {\n            \"const\": \"para\"\n          }\n        }\n      }\n    },\n    {\n      \"if\": {\n        \"required\": [\n          \"motivo\"\n        ],\n        \"properties\": {\n          \"motivo\": {\n            \"const\": \"desligada\"\n          }\n        }\n      },\n      \"then\": {\n        \"properties\": {\n          \"veredito\": {\n            \"const\": \"segue\"\n          }\n        }\n      }\n    }\n  ]\n}\n"]
#[".agents/gh/gh.py", "import json\nimport os\nimport re\nimport shlex\nimport subprocess\nimport sys\n\nBANDEIRA_DE_TESTE = \"--testar\"\nUSO = (\"roda o `gh` na conta declarada, e devolve o berro leg\u00edvel quando ele \"\n       \"recusa. Importado por quem fala com issue, etiqueta ou quadro \u2014 o \"\n       \"token sai do `gh auth token --user`, e nunca de vari\u00e1vel no disco. \"\n       \"Tamb\u00e9m escreve um bloco marcado no corpo da issue (l\u00ea, grava s\u00f3 o \"\n       \"bloco, rel\u00ea) e o coment\u00e1rio que marca o dono, pela API REST: a \"\n       \"sess\u00e3o na nuvem recusa o GraphQL que `gh issue` usa por baixo\")\n\nGH_PADRAO = \"gh\"\nVARIAVEL_DO_GH = \"ATLAS_GH\"\nVARIAVEL_DA_NUVEM = \"CLAUDE_CODE_REMOTE\"\nVALOR_DA_NUVEM = \"true\"\nSISTEMA_WINDOWS = \"nt\"\nASPAS = \"\\\"'\"\nTEMPO_DO_GH = 60\nLIMITE_DO_ERRO = 300\nNAO_RODOU = \"o gh n\u00e3o rodou\"\nRECUSA_SEM_TOKEN = (\n    \"a conta {conta} foi pedida e o token dela n\u00e3o se obteve pelo \"\n    \"`gh auth token --user`: a opera\u00e7\u00e3o n\u00e3o sai por outra conta. \"\n    \"Entre com `gh auth login` nessa conta\")\n\nMARCA_QUE_ABRE = \"<!-- {} -->\"\nMARCA_QUE_FECHA = \"<!-- /{} -->\"\nTETO_DO_BLOCO = 12_000\nAVISO_DO_TETO = \"\\n\\n_(cortado no teto de {} caracteres do bloco)_\"\nTENTATIVAS_DO_BLOCO = 3\nLIMITE_DO_CORPO_EM_BYTES = 262_144\nCAMPO_DAS_ISSUES = \"issues\"\nCAMPO_DE_QUEM_SE_MARCA = \"quem_se_marca\"\nLOGIN_QUE_SERVE = re.compile(r\"^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$\")\nVALOR_POR_PREENCHER = \"${\"\nFALHA_AO_LER_O_CORPO = \"n\u00e3o li o corpo da issue {issue}: {motivo}\"\nFALHA_AO_GRAVAR_O_CORPO = \"n\u00e3o gravei o corpo da issue {issue}: {motivo}\"\nFALHA_AO_COMENTAR = \"n\u00e3o consegui comentar na issue {issue}: {motivo}\"\nBLOCO_NAO_FICOU = (\n    \"gravei o bloco `{nome}` no corpo da issue {issue} e reli {vezes} \"\n    \"vez(es), e ele N\u00c3O est\u00e1 l\u00e1 como escrevi. Outra escrita no mesmo corpo \u00e9 \"\n    \"a explica\u00e7\u00e3o mais prov\u00e1vel: quem grava por \u00faltimo vence. Leia o corpo e \"\n    \"rode de novo\")\nBLOCO_REGRAVADO = (\n    \"a releitura achou o bloco `{nome}` fora do corpo da issue {issue} depois \"\n    \"de gravado \u2014 outra escrita no mesmo corpo \u2014 e eu o regravei {vezes} \"\n    \"vez(es) a partir do corpo novo\")\nCORPO_CHEIO = (\n    \"n\u00e3o gravei: com o bloco `{nome}`, o corpo da issue {issue} passaria de \"\n    \"{limite} bytes, o teto do rastreador. Pode o corpo antes\")\nAVISO_SEM_QUEM_SE_MARCA = (\n    \"o coment\u00e1rio saiu sem marcar ningu\u00e9m: `issues.quem_se_marca` n\u00e3o est\u00e1 \"\n    \"preenchido em nucleo/executor.json, e sem a marca o dono s\u00f3 o v\u00ea se \"\n    \"abrir a issue\")\n\n\ndef _sem_as_aspas_que_envolvem(token: str) -> str:\n    if len(token) >= 2 and token[0] in ASPAS and token[-1] == token[0]:\n        return token[1:-1]\n    return token\n\n\ndef partir_comando(valor: str, windows: bool = os.name == SISTEMA_WINDOWS) -> list:\n    if not windows:\n        return shlex.split(valor)\n    return [_sem_as_aspas_que_envolvem(t) for t in shlex.split(valor, posix=False)]\n\n\ndef linha_de_comando(*partes) -> str:\n    return \" \".join(f'\"{parte}\"' for parte in partes)\n\n\ndef _comando() -> list:\n    return partir_comando(os.environ.get(VARIAVEL_DO_GH, GH_PADRAO))\n\n\ndef sem_retorno_de_carro(entrada):\n    return entrada.replace(\"\\r\", \"\") if isinstance(entrada, str) else entrada\n\n\ndef rodar(argumentos: list, ambiente: dict = None, entrada=None):\n    try:\n        return subprocess.run(\n            _comando() + argumentos, input=sem_retorno_de_carro(entrada),\n            capture_output=True,\n            text=True, encoding=\"utf-8\", errors=\"replace\", timeout=TEMPO_DO_GH,\n            env=dict(os.environ, **(ambiente or {})))\n    except (OSError, subprocess.SubprocessError):\n        return None\n\n\ndef na_nuvem() -> bool:\n    return os.environ.get(VARIAVEL_DA_NUVEM, \"\").strip().lower() == VALOR_DA_NUVEM\n\n\ndef rota_da_issue(repositorio: str, issue) -> str:\n    return f\"repos/{repositorio}/issues/{issue}\"\n\n\ndef pela_rest(metodo: str, rota: str, dado: dict = None) -> tuple:\n    argumentos = [\"api\", \"--method\", metodo, rota]\n    if dado is None:\n        return argumentos, None\n    texto = {chave: sem_retorno_de_carro(valor) for chave, valor in dado.items()}\n    return argumentos + [\"--input\", \"-\"], json.dumps(texto, ensure_ascii=False)\n\n\ndef token_da_conta(conta: str) -> str:\n    if not conta:\n        return \"\"\n    achou = rodar([\"auth\", \"token\", \"--user\", conta])\n    return achou.stdout.strip() if achou and achou.returncode == 0 else \"\"\n\n\ndef na_conta(conta: str, argumentos: list, entrada=None):\n    token = token_da_conta(conta)\n    if conta and not token:\n        return subprocess.CompletedProcess(\n            argumentos, 1, \"\", RECUSA_SEM_TOKEN.format(conta=conta))\n    return rodar(argumentos, {\"GH_TOKEN\": token} if token else {}, entrada)\n\n\ndef berro(feito) -> str:\n    if feito is None:\n        return NAO_RODOU\n    return ((feito.stderr or feito.stdout).strip()\n            or str(feito.returncode))[:LIMITE_DO_ERRO]\n\n\ndef marcas_do_bloco(nome: str) -> tuple:\n    return MARCA_QUE_ABRE.format(nome), MARCA_QUE_FECHA.format(nome)\n\n\ndef partes_do_bloco(corpo: str, abre: str, fecha: str) -> tuple:\n    inicio = corpo.find(abre)\n    fim = corpo.find(fecha)\n    if inicio < 0 or fim < 0 or fim < inicio:\n        return ()\n    return (corpo[:inicio + len(abre)], corpo[inicio + len(abre):fim],\n            corpo[fim:])\n\n\ndef no_teto(texto: str) -> str:\n    limpo = (texto or \"\").strip()\n    if len(limpo) <= TETO_DO_BLOCO:\n        return limpo\n    aviso = AVISO_DO_TETO.format(TETO_DO_BLOCO)\n    return limpo[:TETO_DO_BLOCO - len(aviso)].rstrip() + aviso\n\n\ndef texto_do_bloco(corpo: str, nome: str):\n    partes = partes_do_bloco(corpo or \"\", *marcas_do_bloco(nome))\n    return partes[1].strip() if partes else None\n\n\ndef corpo_com_o_bloco(corpo: str, nome: str, texto: str) -> str:\n    abre, fecha = marcas_do_bloco(nome)\n    miolo = \"\\n\" + no_teto(texto) + \"\\n\"\n    partes = partes_do_bloco(corpo or \"\", abre, fecha)\n    if partes:\n        return partes[0] + miolo + partes[2]\n    return (corpo or \"\").rstrip(\"\\n\") + \"\\n\\n\" + abre + miolo + fecha + \"\\n\"\n\n\ndef ler_o_corpo(conta: str, repositorio: str, issue) -> tuple:\n    argumentos, _ = pela_rest(\"GET\", rota_da_issue(repositorio, issue))\n    feito = na_conta(conta, argumentos)\n    if feito is None or feito.returncode != 0:\n        return None, FALHA_AO_LER_O_CORPO.format(issue=issue,\n                                                 motivo=berro(feito))\n    try:\n        corpo = json.loads(feito.stdout or \"{}\").get(\"body\")\n    except (ValueError, AttributeError) as falha:\n        return None, FALHA_AO_LER_O_CORPO.format(\n            issue=issue, motivo=f\"{type(falha).__name__}: {falha}\")\n    if not isinstance(corpo, str):\n        return None, FALHA_AO_LER_O_CORPO.format(\n            issue=issue, motivo=\"o rastreador n\u00e3o devolveu o corpo\")\n    return corpo.replace(\"\\r\", \"\"), \"\"\n\n\ndef gravar_o_bloco(conta: str, repositorio: str, issue, nome: str,\n                   texto: str) -> tuple:\n    esperado = no_teto(texto)\n    gravacoes = 0\n    while True:\n        atual, erro = ler_o_corpo(conta, repositorio, issue)\n        if erro:\n            return False, erro\n        if texto_do_bloco(atual, nome) == esperado:\n            return True, (BLOCO_REGRAVADO.format(nome=nome, issue=issue,\n                                                 vezes=gravacoes - 1)\n                          if gravacoes > 1 else \"\")\n        if gravacoes >= TENTATIVAS_DO_BLOCO:\n            return False, BLOCO_NAO_FICOU.format(nome=nome, issue=issue,\n                                                 vezes=gravacoes)\n        proposto = corpo_com_o_bloco(atual, nome, esperado)\n        if len(proposto.encode(\"utf-8\")) > LIMITE_DO_CORPO_EM_BYTES:\n            return False, CORPO_CHEIO.format(nome=nome, issue=issue,\n                                             limite=LIMITE_DO_CORPO_EM_BYTES)\n        argumentos, entrada = pela_rest(\"PATCH\", rota_da_issue(repositorio,\n                                                               issue),\n                                        {\"body\": proposto})\n        feito = na_conta(conta, argumentos, entrada)\n        if feito is None or feito.returncode != 0:\n            return False, FALHA_AO_GRAVAR_O_CORPO.format(issue=issue,\n                                                         motivo=berro(feito))\n        gravacoes += 1\n\n\ndef quem_se_marca(configuracao: dict) -> str:\n    issues = (configuracao or {}).get(CAMPO_DAS_ISSUES)\n    valor = issues.get(CAMPO_DE_QUEM_SE_MARCA) if isinstance(issues, dict) \\\n        else None\n    if not isinstance(valor, str):\n        return \"\"\n    valor = valor.strip().lstrip(\"@\")\n    if VALOR_POR_PREENCHER in valor or not LOGIN_QUE_SERVE.match(valor):\n        return \"\"\n    return valor\n\n\ndef texto_que_marca(texto: str, login: str) -> tuple:\n    if not login:\n        return texto, AVISO_SEM_QUEM_SE_MARCA\n    return f\"@{login} {texto}\", \"\"\n\n\ndef comentar_para_o_dono(conta: str, repositorio: str, issue, texto: str,\n                         login: str) -> tuple:\n    marcado, aviso = texto_que_marca(texto, login)\n    argumentos, entrada = pela_rest(\n        \"POST\", rota_da_issue(repositorio, issue) + \"/comments\",\n        {\"body\": marcado})\n    feito = na_conta(conta, argumentos, entrada)\n    if feito is None or feito.returncode != 0:\n        return False, FALHA_AO_COMENTAR.format(issue=issue,\n                                               motivo=berro(feito)), aviso\n    return True, \"\", aviso\n\n\nFALSO = \"\"\"import json\nimport os\nimport pathlib\nimport sys\n\nCAIXA = pathlib.Path(os.environ[\"GH_TESTE_CAIXA\"])\nCORPO = CAIXA / \"corpo.md\"\nOUTRO = CAIXA / \"outro-escritor.txt\"\nargv = sys.argv[1:]\nif argv[:2] == [\"auth\", \"token\"] and (CAIXA / \"sem-token.txt\").exists():\n    sys.stderr.write(\"token indisponivel\\\\n\")\n    sys.exit(2)\ntoken = os.environ.get(\"GH_TOKEN\", \"\")\n(CAIXA / \"chamadas.txt\").open(\"a\").write(\n    \" \".join(argv) + chr(9)\n    + (token if token.startswith(\"token-\") else \"sem-token\") + chr(10))\nrecebido = b\"\"\nif \"--body-file\" in argv:\n    recebido = sys.stdin.buffer.read()\n    (CAIXA / \"corpo-recebido.bin\").write_bytes(recebido)\nif argv[:2] == [\"auth\", \"token\"]:\n    print(\"token-de-\" + argv[-1])\nelif (CAIXA / \"recusa.txt\").exists():\n    sys.stderr.write(\"nao vai\\\\n\")\n    sys.exit(2)\nelif argv[:3] == [\"api\", \"--method\", \"GET\"]:\n    sys.stdout.reconfigure(encoding=\"utf-8\")\n    print(json.dumps({\"body\": CORPO.read_text(encoding=\"utf-8\")\n                      if CORPO.exists() else \"\"}))\nelif argv[:3] == [\"api\", \"--method\", \"PATCH\"]:\n    if \"--input\" in argv:\n        recebido = sys.stdin.buffer.read()\n        (CAIXA / \"corpo-recebido.bin\").write_bytes(recebido)\n    CORPO.write_text(json.loads(recebido.decode(\"utf-8\"))[\"body\"],\n                     encoding=\"utf-8\")\n    vezes = int(OUTRO.read_text(encoding=\"utf-8\")) if OUTRO.exists() else 0\n    if vezes > 0:\n        CORPO.write_bytes((CAIXA / \"corpo-do-outro.md\").read_bytes())\n        OUTRO.write_text(str(vezes - 1), encoding=\"utf-8\")\nsys.exit(0)\n\"\"\"\n\n\ndef testar() -> int:\n    import tempfile\n    from pathlib import Path\n\n    passou = falhou = 0\n\n    def caso(nome: str, condicao: bool) -> None:\n        nonlocal passou, falhou\n        if condicao:\n            passou += 1\n        else:\n            falhou += 1\n            print(f\"FALHOU: {nome}\")\n\n    os.environ.pop(VARIAVEL_DA_NUVEM, None)\n    with tempfile.TemporaryDirectory() as pasta:\n        caixa = Path(pasta)\n        falso = caixa / \"gh-falso.py\"\n        falso.write_text(FALSO, encoding=\"utf-8\")\n        os.environ[\"GH_TESTE_CAIXA\"] = str(caixa)\n        os.environ[VARIAVEL_DO_GH] = linha_de_comando(sys.executable, falso)\n\n        caso(\"caminho do Windows com espa\u00e7o e contrabarra fica inteiro: o \"\n             \"shlex posix quebrava C:\\\\Program Files em dois e comia as barras, \"\n             \"e o gh falso nunca rodava\",\n             partir_comando(\n                 '\"C:\\\\Program Files\\\\Python314\\\\python.exe\" \"C:\\\\x\\\\gh falso.py\"',\n                 windows=True)\n             == [\"C:\\\\Program Files\\\\Python314\\\\python.exe\", \"C:\\\\x\\\\gh falso.py\"])\n        caso(\"no Linux o mesmo comando entre aspas tamb\u00e9m fica inteiro\",\n             partir_comando('\"/tmp/com espaco/python3\" \"/tmp/x/gh.py\"',\n                            windows=False)\n             == [\"/tmp/com espaco/python3\", \"/tmp/x/gh.py\"])\n        caso(\"a linha de comando que os testes montam vai com aspas em cada \"\n             \"parte \u2014 \u00e9 o que sobrevive aos dois sistemas\",\n             linha_de_comando(\"a b\", \"c\") == '\"a b\" \"c\"')\n\n        caso(\"sem conta declarada n\u00e3o h\u00e1 token \u2014 e o gh usa a conta ativa\",\n             token_da_conta(\"\") == \"\")\n        caso(\"com conta declarada, o token sai do `gh auth token --user`\",\n             token_da_conta(\"alguem\") == \"token-de-alguem\")\n\n        os.environ[\"GH_TOKEN\"] = \"token-do-dono-ficticio\"\n        chamadas_antes = (caixa / \"chamadas.txt\").read_text(encoding=\"utf-8\")\n        (caixa / \"sem-token.txt\").write_text(\"x\", encoding=\"utf-8\")\n        recusado = na_conta(\"alguem\", [\"issue\", \"comment\", \"1\"])\n        chamadas_depois = (caixa / \"chamadas.txt\").read_text(encoding=\"utf-8\")\n        caso(\"conta pedida sem token recusa antes da operacao mesmo com GH_TOKEN herdado\",\n             recusado is not None and recusado.returncode != 0\n             and \"alguem\" in berro(recusado)\n             and \"gh auth login\" in berro(recusado)\n             and chamadas_depois == chamadas_antes)\n        (caixa / \"sem-token.txt\").unlink()\n\n        chamada_com_token = na_conta(\"alguem\", [\"issue\", \"comment\", \"1\"])\n        novas_chamadas = (caixa / \"chamadas.txt\").read_text(\n            encoding=\"utf-8\")[len(chamadas_depois):]\n        caso(\"token obtido prevalece sobre GH_TOKEN herdado na operacao\",\n             chamada_com_token is not None and chamada_com_token.returncode == 0\n             and \"issue comment 1\\ttoken-de-alguem\\n\" in novas_chamadas\n             and \"issue comment 1\\ttoken-do-dono-ficticio\" not in novas_chamadas)\n\n        chamada_sem_conta = na_conta(\"\", [\"issue\", \"comment\", \"1\"])\n        novas_chamadas = (caixa / \"chamadas.txt\").read_text(\n            encoding=\"utf-8\")[len(chamadas_depois + novas_chamadas):]\n        caso(\"conta vazia continua usando o ambiente herdado\",\n             chamada_sem_conta is not None and chamada_sem_conta.returncode == 0\n             and \"issue comment 1\\ttoken-do-dono-ficticio\\n\" in novas_chamadas)\n        os.environ.pop(\"GH_TOKEN\", None)\n\n        na_conta(\"alguem\", [\"issue\", \"view\", \"1\"])\n        chamadas = (caixa / \"chamadas.txt\").read_text(encoding=\"utf-8\")\n        caso(\"o comando roda com o token da conta pedida, sem trocar a ativa\",\n             \"token-de-alguem\" in chamadas)\n\n        rodar([\"issue\", \"edit\", \"1\", \"--body-file\", \"-\"],\n              entrada=\"titulo\\r\\r\\r\\nlinha\\r\\n\\r\\r\\nfim\\n\")\n        recebido = (caixa / \"corpo-recebido.bin\").read_bytes()\n        caso(\"corpo lido do rastreador volta com retorno de carro sobrando, \"\n             \"e a escrita em modo texto soma mais um por linha: o que vai \"\n             \"pelo stdin sai LIMPO, sen\u00e3o cada grava\u00e7\u00e3o engorda o corpo at\u00e9 \"\n             \"o teto do rastreador com caractere que ningu\u00e9m v\u00ea\",\n             b\"\\r\\r\" not in recebido\n             and recebido.replace(b\"\\r\", b\"\") == b\"titulo\\nlinha\\n\\nfim\\n\")\n\n        (caixa / \"recusa.txt\").write_text(\"x\", encoding=\"utf-8\")\n        feito = na_conta(\"alguem\", [\"issue\", \"comment\", \"1\"])\n        caso(\"recusa do gh vira berro leg\u00edvel, nunca sil\u00eancio\",\n             feito is not None and \"nao vai\" in berro(feito))\n        caso(\"berro de comando que nem rodou tamb\u00e9m tem texto\",\n             berro(None) == NAO_RODOU)\n\n        (caixa / \"recusa.txt\").unlink()\n        abre, fecha = marcas_do_bloco(\"o bloco\")\n        corpo = \"# topo\\n\\n## Estado\\nfeito\\n\"\n        caso(\"corpo sem o bloco n\u00e3o tem partes: quem escreve sabe que vai criar\",\n             partes_do_bloco(corpo, abre, fecha) == ())\n        com_ele = corpo_com_o_bloco(corpo, \"o bloco\", \"primeira vers\u00e3o\")\n        caso(\"bloco que n\u00e3o existe nasce no fim, entre as marcas, e o resto do \"\n             \"corpo fica como estava\",\n             com_ele.startswith(corpo.rstrip(\"\\n\"))\n             and texto_do_bloco(com_ele, \"o bloco\") == \"primeira vers\u00e3o\"\n             and com_ele.rstrip(\"\\n\").endswith(fecha))\n        outro = corpo_com_o_bloco(com_ele, \"o vizinho\", \"do vizinho\")\n        trocado = corpo_com_o_bloco(outro, \"o bloco\", \"segunda vers\u00e3o\")\n        caso(\"reescrever o bloco troca a se\u00e7\u00e3o INTEIRA e n\u00e3o toca o bloco \"\n             \"vizinho nem o texto de gente\",\n             texto_do_bloco(trocado, \"o bloco\") == \"segunda vers\u00e3o\"\n             and \"primeira vers\u00e3o\" not in trocado\n             and texto_do_bloco(trocado, \"o vizinho\") == \"do vizinho\"\n             and trocado.startswith(\"# topo\\n\\n## Estado\\nfeito\\n\"))\n        caso(\"marca de fechar antes da de abrir n\u00e3o \u00e9 bloco: escrever ali \"\n             \"apagaria texto de gente\",\n             partes_do_bloco(fecha + \"\\nmeio\\n\" + abre, abre, fecha) == ())\n        longo = no_teto(\"x\" * (TETO_DO_BLOCO * 2))\n        caso(\"texto maior que o teto do bloco sai cortado e diz que cortou \u2014 \"\n             \"o corpo tem teto, e bloco sem teto o enche\",\n             len(longo) <= TETO_DO_BLOCO and longo.endswith(\n                 AVISO_DO_TETO.format(TETO_DO_BLOCO)))\n\n        (caixa / \"corpo.md\").write_text(corpo, encoding=\"utf-8\")\n        ok, dito = gravar_o_bloco(\"alguem\", \"dono/repo\", 7, \"o bloco\", \"vale\")\n        caso(\"gravar o bloco l\u00ea, grava e rel\u00ea: ele fica no corpo da issue\",\n             ok and texto_do_bloco((caixa / \"corpo.md\").read_text(\n                 encoding=\"utf-8\"), \"o bloco\") == \"vale\")\n        chamadas = (caixa / \"chamadas.txt\").read_text(encoding=\"utf-8\")\n        caso(\"o corpo se l\u00ea e se grava pela API REST, na rota da issue, e \"\n             \"nunca por `gh issue view` ou `gh issue edit`: os dois usam \"\n             \"GraphQL, e a sess\u00e3o na nuvem recusa GraphQL\",\n             \"api --method GET repos/dono/repo/issues/7\\t\" in chamadas\n             and \"api --method PATCH repos/dono/repo/issues/7 --input -\"\n             in chamadas\n             and \"issue view 7\" not in chamadas\n             and \"issue edit 7\" not in chamadas)\n        (caixa / \"corpo.md\").write_text(corpo, encoding=\"utf-8\")\n        gravar_o_bloco(\"alguem\", \"dono/repo\", 7, \"o bloco\", \"a\\r\\nb\")\n        enviado = json.loads((caixa / \"corpo-recebido.bin\").read_bytes()\n                             .decode(\"utf-8\"))[\"body\"]\n        caso(\"o corpo que sobe em JSON tamb\u00e9m sai sem retorno de carro: \"\n             \"dentro do JSON ele vira escape, e a limpeza do stdin n\u00e3o o via\",\n             \"\\r\" not in enviado and \"a\\nb\" in enviado)\n\n        _, entrada = pela_rest(\"POST\", \"x\", {\"body\": \"a\u00e7\u00e3o\"})\n        caso(\"o texto vai em UTF-8 leg\u00edvel, n\u00e3o em escape de ASCII\",\n             \"a\u00e7\u00e3o\" in entrada)\n        for valor, esperado in ((\"true\", True), (\"TRUE\", True),\n                                (\"false\", False), (\"\", False)):\n            os.environ[VARIAVEL_DA_NUVEM] = valor\n            caso(f\"`{VARIAVEL_DA_NUVEM}={valor}` diz nuvem {esperado}\",\n                 na_nuvem() is esperado)\n        os.environ.pop(VARIAVEL_DA_NUVEM, None)\n\n        do_outro = corpo_com_o_bloco(corpo, \"o do outro\", \"escrito pelo outro\")\n        (caixa / \"corpo-do-outro.md\").write_text(do_outro, encoding=\"utf-8\")\n        (caixa / \"corpo.md\").write_text(corpo, encoding=\"utf-8\")\n        (caixa / \"outro-escritor.txt\").write_text(\"99\", encoding=\"utf-8\")\n        ok, dito = gravar_o_bloco(\"alguem\", \"dono/repo\", 7, \"o bloco\", \"meu\")\n        caso(\"DOIS ESCRITORES: o segundo grava por cima toda vez, e a \"\n             \"releitura acusa em vez de dar por gravado\",\n             not ok and \"N\u00c3O est\u00e1 l\u00e1\" in dito)\n\n        (caixa / \"corpo.md\").write_text(corpo, encoding=\"utf-8\")\n        (caixa / \"outro-escritor.txt\").write_text(\"1\", encoding=\"utf-8\")\n        ok, dito = gravar_o_bloco(\"alguem\", \"dono/repo\", 7, \"o bloco\", \"meu\")\n        final = (caixa / \"corpo.md\").read_text(encoding=\"utf-8\")\n        caso(\"o segundo grava por cima uma vez: a releitura acusa, regrava a \"\n             \"partir do corpo novo, e o bloco do outro sobrevive\",\n             ok and \"regravei\" in dito\n             and texto_do_bloco(final, \"o bloco\") == \"meu\"\n             and texto_do_bloco(final, \"o do outro\") == \"escrito pelo outro\")\n        (caixa / \"outro-escritor.txt\").unlink()\n\n        (caixa / \"corpo.md\").write_text(\"y\" * LIMITE_DO_CORPO_EM_BYTES,\n                                        encoding=\"utf-8\")\n        antes = (caixa / \"chamadas.txt\").read_text(encoding=\"utf-8\")\n        ok, dito = gravar_o_bloco(\"alguem\", \"dono/repo\", 7, \"o bloco\", \"meu\")\n        depois = (caixa / \"chamadas.txt\").read_text(encoding=\"utf-8\")\n        caso(\"corpo que passaria do teto do rastreador n\u00e3o se grava, e nada \"\n             \"sobe\",\n             not ok and str(LIMITE_DO_CORPO_EM_BYTES) in dito\n             and \"edit\" not in depois[len(antes):])\n\n        caso(\"o login de quem se marca sai da configura\u00e7\u00e3o local\",\n             quem_se_marca({\"issues\": {\"quem_se_marca\": \"a-pessoa\"}})\n             == \"a-pessoa\")\n        caso(\"login com molde por preencher, ausente ou fora do formato n\u00e3o \"\n             \"marca ningu\u00e9m\",\n             quem_se_marca({\"issues\": {\"quem_se_marca\": \"${LOGIN}\"}}) == \"\"\n             and quem_se_marca({}) == \"\"\n             and quem_se_marca({\"issues\": \"x\"}) == \"\"\n             and quem_se_marca({\"issues\": {\"quem_se_marca\": \"a b\"}}) == \"\")\n        texto, aviso = texto_que_marca(\"espera por voc\u00ea\", \"a-pessoa\")\n        caso(\"com login, o coment\u00e1rio abre marcando a pessoa, e n\u00e3o h\u00e1 aviso\",\n             texto.startswith(\"@a-pessoa \") and not aviso)\n        texto, aviso = texto_que_marca(\"espera por voc\u00ea\", \"\")\n        caso(\"sem login, o coment\u00e1rio sai sem marca e o aviso diz o campo\",\n             \"@\" not in texto and \"quem_se_marca\" in aviso)\n\n        os.environ[VARIAVEL_DO_GH] = \"/caminho/que/nao/existe/gh\"\n        caso(\"gh que n\u00e3o existe devolve None, e n\u00e3o estoura na cara de quem \"\n             \"chamou\",\n             rodar([\"auth\", \"status\"]) is None)\n        os.environ.pop(VARIAVEL_DO_GH, None)\n        os.environ.pop(\"GH_TESTE_CAIXA\", None)\n\n    print(f\"{'OK' if not falhou else 'FALHOU'}: {passou + falhou} casos\")\n    return 1 if falhou else 0\n\n\nif __name__ == \"__main__\":\n    for canal in (sys.stdin, sys.stdout, sys.stderr):\n        if not getattr(canal, \"closed\", True) and hasattr(canal, \"reconfigure\"):\n            canal.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    if BANDEIRA_DE_TESTE in sys.argv[1:]:\n        sys.exit(testar())\n    print(USO)\n"]
#[".agents/historico/historico.py", "import argparse\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nimport tempfile\nimport unicodedata\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nfor _acima in Path(__file__).resolve().parents:\n    if (_acima / \".agents\" / \"gh\" / \"gh.py\").is_file():\n        sys.path.insert(0, str(_acima / \".agents\" / \"gh\"))\n        break\nimport gh\n\nBANDEIRA_DE_TESTE = \"--testar\"\nUSO = (\"destila o corpo final de cada issue fechada num hist\u00f3rico local, por \"\n       \"projeto, em conhecimento/issues_encerradas/<projeto>/\"\n       \"<numero>-<assunto>.md, sempre na \u00e1rvore principal \u2014 gravado numa \"\n       \"worktree, ele sumiria com ela. Vale s\u00f3 daqui para frente: o marco \u00e9 o \"\n       \"commit que trouxe o instrumento ao checkout, ou a primeira vez que \"\n       \"ele roda quando n\u00e3o h\u00e1 commit, e o .desde escrito vence os dois. \"\n       \"Confere o texto por forma de \"\n       \"segredo antes de gravar e recusa sem mostrar o valor, e s\u00f3 grava onde \"\n       \"o git ignora. Depois de gravar, pede a ronda do \u00edndice\")\n\nARQUIVO_DO_EXECUTOR = \"nucleo/executor.json\"\nPASTA_DO_HISTORICO = \"conhecimento/issues_encerradas\"\nARQUIVO_DO_MARCO = \".desde\"\nPASTA_SEM_PROJETO = \"sem-projeto\"\nINDEXADOR = \".agents/indice/indexar.py\"\nBANDEIRA_DA_RONDA = \"--ronda\"\nTETO_DO_ASSUNTO = 60\nTETO_DE_COMMITS = 30\nTETO_DA_LISTA = 100\nTEMPO_DO_GIT = 30\nTEMPO_DA_RONDA = 900\nSAIDA_LIMPA = 0\nSAIDA_COM_ACHADO = 1\nSAIDA_NAO_MEDIDA = 2\n\nPREFIXO_DO_TITULO = re.compile(r\"^\\s*\\S+\\s+-\\s+\")\nFORA_DO_ASSUNTO = re.compile(r\"[^a-z0-9]+\")\nNOME_DE_PASTA_QUE_SERVE = re.compile(r\"^[A-Za-z0-9_.-]+$\")\nTITULO_DE_SECAO = re.compile(r\"^#{1,3}\\s+(.+?)\\s*$\")\nLINHA_DE_CRITERIO = re.compile(r\"^\\s*[-*]\\s+\\[( |x|X)\\]\\s+\")\nENDERECO_DO_REPOSITORIO = re.compile(r\"^([^/\\s]+)/([^/\\s]+)$\")\n\nFORMAS_DE_SEGREDO = (\n    (\"chave de API\", re.compile(r\"sk-[A-Za-z0-9_\\-]{16,}\")),\n    (\"token do GitHub\",\n     re.compile(r\"(?:gh[pousr]|github_pat)_[A-Za-z0-9_]{20,}\")),\n    (\"chave da AWS\", re.compile(r\"AKIA[0-9A-Z]{16}\")),\n    (\"chave privada\", re.compile(r\"-----BEGIN [A-Z ]*PRIVATE KEY-----\")),\n    (\"token JWT\",\n     re.compile(r\"eyJ[A-Za-z0-9_\\-]{8,}\\.[A-Za-z0-9_\\-]{8,}\\.\")),\n    (\"token do Slack\", re.compile(r\"xox[baprs]-[A-Za-z0-9\\-]{10,}\")),\n    (\"senha ou token escrito por extenso\",\n     re.compile(r\"(?i)\\b(?:senha|password|passwd|secret|segredo|token)\\b\"\n                r\"\\s*[:=]\\s*(?!\\$\\{)[^\\s`'\\\"]{6,}\")),\n    (\"endere\u00e7o de e-mail\",\n     re.compile(r\"[A-Za-z0-9._%+\\-]+@(?!users\\.noreply\\.github\\.com)\"\n                r\"[A-Za-z0-9.\\-]+\\.[A-Za-z]{2,}\")),\n)\n\nMOTIVO_DO_FECHAMENTO = {\"COMPLETED\": \"conclu\u00edda\", \"NOT_PLANNED\": \"descartada\",\n                        \"DUPLICATE\": \"duplicada\", \"REOPENED\": \"reaberta\"}\nSECOES_DO_PEDIDO = (\"objetivo\", \"o pedido, como veio\")\nSECAO_DO_ESTADO = \"estado\"\nPEDACO_DA_SECAO_DE_DECISAO = \"decis\"\nPEDACO_DA_SECAO_DE_ONDE_MORA = \"onde mora\"\n\nCONSULTA_DA_ISSUE = (\n    \"query($dono: String!, $nome: String!, $numero: Int!) { \"\n    \"repository(owner: $dono, name: $nome) { issue(number: $numero) { \"\n    \"number title body url stateReason closedAt \"\n    \"labels(first: 30) { nodes { name } } \"\n    \"closedByPullRequestsReferences(first: 10, includeClosedPrs: true) { \"\n    \"nodes { number title url mergedAt } } } } }\")\n\nMOLDE_DO_HISTORICO = \"\"\"# {numero} \u2014 {titulo}\n\n- **Projeto:** `{projeto}`\n- **Fechada em:** {quando}, {motivo}\n- **Issue:** {url}\n- **Fechada por:** {fechada_por}\n- **Commits com a marca `(issue {numero})`:** {quantos_commits}\n\n## O que foi pedido\n\n{pedido}\n\n## Os crit\u00e9rios, como estavam no fechamento\n\n{criterios}\n\n{em_branco}\n\n## Decis\u00f5es\n\n{decisoes}\n\n## O estado no fechamento\n\n{estado}\n\n## Onde mora o que se aprendeu\n\n{onde_mora}\n\n## Os commits\n\n{commits}\n\"\"\"\nFECHADA_A_MAO = \"\u00e0 m\u00e3o, sem pedido de incorpora\u00e7\u00e3o que a feche\"\nLINHA_DO_PEDIDO_QUE_FECHOU = \"{url} \u2014 {titulo}{mesclado}\"\nMESCLADO_EM = \", mesclado em {}\"\nLINHA_DO_COMMIT = \"- `{hash}` {assunto}\"\nSEM_SECAO = \"_O corpo final n\u00e3o tinha esta se\u00e7\u00e3o._\"\nSEM_CRITERIO = \"_O corpo final n\u00e3o tinha crit\u00e9rio marc\u00e1vel._\"\nSEM_COMMIT = \"_Nenhum commit traz a marca desta issue._\"\nNENHUM_EM_BRANCO = \"Nenhum crit\u00e9rio em branco no fechamento.\"\nCOM_CRITERIO_EM_BRANCO = (\n    \"**Em branco no fechamento: {quantos}.** A issue fechou com crit\u00e9rio sem \"\n    \"marca, e o hist\u00f3rico n\u00e3o a d\u00e1 por pronta: o fechamento n\u00e3o l\u00ea os \"\n    \"crit\u00e9rios.\")\nSEM_ONDE_MORA = (\n    \"_O corpo final n\u00e3o declarou onde mora o que se aprendeu: credencial, \"\n    \"conta de teste, fato do vizinho e li\u00e7\u00e3o gen\u00e9rica ficaram sem ponteiro._\")\n\nRECUSA_SEM_CONFIGURACAO = (\n    \"n\u00e3o medido: n\u00e3o li {arquivo} ({motivo}) \u2014 \u00e9 dele que saem o reposit\u00f3rio \"\n    \"das issues e os projetos\")\nRECUSA_SEM_REPOSITORIO = (\n    \"n\u00e3o medido: {arquivo} n\u00e3o declara `issues.repositorio` no formato \"\n    \"dono/nome, e sem ele n\u00e3o sei onde as issues fecham\")\nFALHA_AO_LISTAR = \"n\u00e3o medido: n\u00e3o listei as issues fechadas \u2014 {motivo}\"\nFALHA_AO_LER_A_ISSUE = \"n\u00e3o li a issue {numero} \u2014 {motivo}\"\nRECUSA_ANTES_DO_MARCO = (\n    \"a issue {numero} fechou em {quando}, antes do marco {marco}: o hist\u00f3rico \"\n    \"vale s\u00f3 daqui para frente, e ela n\u00e3o se colhe\")\nRECUSA_ABERTA = \"a issue {numero} n\u00e3o est\u00e1 fechada: n\u00e3o h\u00e1 o que colher\"\nRECUSA_SEGREDO = (\n    \"n\u00e3o gravei o hist\u00f3rico da issue {numero}: o texto tem forma de \"\n    \"segredo \u2014 {achados}. O valor n\u00e3o aparece aqui de prop\u00f3sito. Tire-o do \"\n    \"corpo da issue: o valor vai para .credenciais/acessos/, a conta ganha \"\n    \"uma linha sem valor no .credenciais/INVENTARIO.md, e o corpo guarda s\u00f3 \"\n    \"o ponteiro. Depois rode de novo\")\nACHADO_DE_SEGREDO = \"linha {linha}: {forma}\"\nRECUSA_FORA_DO_IGNORE = (\n    \"n\u00e3o gravei o hist\u00f3rico da issue {numero}: o git N\u00c3O ignora {alvo}, e \"\n    \"o que est\u00e1 rastreado sobe para o espelho. Declare a pasta fora do git \"\n    \"antes \u2014 no .gitignore da raiz, ou com o .gitignore que o m\u00f3dulo \"\n    \"instala dentro dela\")\nRECUSA_PASTA_FORA_DO_IGNORE = (\n    \"n\u00e3o medido: o git N\u00c3O ignora {alvo}/, e nem o marco se grava ali \u2014 o \"\n    \"que est\u00e1 rastreado sobe para o espelho. Declare a pasta fora do git \"\n    \"antes: no .gitignore da raiz, ou com o .gitignore que o m\u00f3dulo instala \"\n    \"dentro dela\")\nRECADO_GRAVADO = \"hist\u00f3rico gravado: {caminho} (na \u00e1rvore principal, {raiz})\"\nRECADO_DO_ENSAIO = \"ENSAIO \u2014 o hist\u00f3rico de {caminho} seria:\\n\\n{texto}\"\nRECADO_SEM_PENDENTE = \"nenhuma issue fechada sem hist\u00f3rico desde {marco}\"\nRECADO_PENDENTES = (\n    \"{quantas} issue(s) fechada(s) sem hist\u00f3rico desde {marco}: {lista} \u2014 \"\n    \"rode `python .agents/historico/historico.py --colher`\")\nRECADO_MARCO_NOVO = (\"marco do hist\u00f3rico posto agora, {marco}: as issues \"\n                     \"fechadas antes dele n\u00e3o se colhem\")\nRECADO_MARCO_DA_CHEGADA = (\n    \"marco do hist\u00f3rico posto em {marco}, a data do commit que trouxe o \"\n    \"instrumento a este checkout: as issues fechadas antes dele n\u00e3o se colhem\")\nRECADO_RONDA = \"\u00edndice: {ultima}\"\nRECADO_RONDA_FALHOU = \"\u00edndice: a ronda n\u00e3o rodou ({motivo}) \u2014 rode {comando}\"\nRECADO_SEM_INDICE = \"\u00edndice: o m\u00f3dulo n\u00e3o est\u00e1 instalado, e nada se reindexou\"\n\n\ndef agora_em_utc() -> datetime:\n    return datetime.now(timezone.utc).replace(microsecond=0)\n\n\ndef instante(texto: str):\n    try:\n        return datetime.fromisoformat((texto or \"\").replace(\"Z\", \"+00:00\"))\n    except ValueError:\n        return None\n\n\ndef rodar_git(pasta: Path, *argumentos) -> tuple:\n    try:\n        feito = subprocess.run([\"git\", \"-C\", str(pasta), *argumentos],\n                               capture_output=True, text=True,\n                               encoding=\"utf-8\", errors=\"replace\",\n                               timeout=TEMPO_DO_GIT)\n    except (OSError, subprocess.SubprocessError) as falha:\n        return None, f\"{type(falha).__name__}: {falha}\"\n    return feito.returncode, feito.stdout.strip()\n\n\ndef arvore_principal(cwd: Path) -> Path:\n    codigo, comum = rodar_git(cwd, \"rev-parse\", \"--path-format=absolute\",\n                              \"--git-common-dir\")\n    if codigo != 0 or not comum:\n        return Path(cwd).resolve()\n    pasta = Path(comum)\n    return pasta.parent.resolve() if pasta.name == \".git\" \\\n        else Path(cwd).resolve()\n\n\ndef configuracao(principal: Path, cwd: Path) -> tuple:\n    ultimo_motivo = \"o arquivo n\u00e3o existe\"\n    for raiz in (principal, cwd):\n        alvo = Path(raiz) / ARQUIVO_DO_EXECUTOR\n        try:\n            return json.loads(alvo.read_text(encoding=\"utf-8\")), \"\"\n        except OSError as falha:\n            ultimo_motivo = f\"{type(falha).__name__}\"\n        except ValueError as falha:\n            return None, RECUSA_SEM_CONFIGURACAO.format(\n                arquivo=ARQUIVO_DO_EXECUTOR, motivo=falha)\n    return None, RECUSA_SEM_CONFIGURACAO.format(arquivo=ARQUIVO_DO_EXECUTOR,\n                                                motivo=ultimo_motivo)\n\n\ndef endereco_das_issues(dado: dict) -> tuple:\n    issues = dado.get(\"issues\") if isinstance(dado, dict) else None\n    issues = issues if isinstance(issues, dict) else {}\n    repositorio = issues.get(\"repositorio\")\n    if not isinstance(repositorio, str) or \"${\" in repositorio \\\n            or not ENDERECO_DO_REPOSITORIO.match(repositorio.strip()):\n        return None, RECUSA_SEM_REPOSITORIO.format(\n            arquivo=ARQUIVO_DO_EXECUTOR)\n    conta = issues.get(\"conta_gh\") if isinstance(issues.get(\"conta_gh\"),\n                                                 str) else \"\"\n    return {\"repositorio\": repositorio.strip(), \"conta\": conta}, \"\"\n\n\ndef projetos_cadastrados(dado: dict) -> list:\n    projetos = dado.get(\"projetos\") if isinstance(dado, dict) else None\n    if not isinstance(projetos, dict):\n        return []\n    return [nome for nome, valor in projetos.items() if isinstance(valor, dict)]\n\n\ndef projeto_da_issue(etiquetas: list, cadastrados: list) -> str:\n    postas = set(etiquetas)\n    for nome in cadastrados:\n        if nome in postas and NOME_DE_PASTA_QUE_SERVE.match(nome):\n            return nome\n    return PASTA_SEM_PROJETO\n\n\ndef assunto_do_titulo(titulo: str) -> str:\n    sem_prefixo = PREFIXO_DO_TITULO.sub(\"\", titulo or \"\", count=1)\n    decomposto = unicodedata.normalize(\"NFKD\", sem_prefixo.lower())\n    sem_acento = \"\".join(c for c in decomposto\n                         if not unicodedata.combining(c))\n    kebab = FORA_DO_ASSUNTO.sub(\"-\", sem_acento).strip(\"-\")\n    if len(kebab) > TETO_DO_ASSUNTO:\n        kebab = kebab[:TETO_DO_ASSUNTO].rsplit(\"-\", 1)[0]\n    return kebab or \"sem-assunto\"\n\n\ndef nome_do_arquivo(numero: int, titulo: str) -> str:\n    return f\"{numero}-{assunto_do_titulo(titulo)}.md\"\n\n\ndef secoes_do_corpo(corpo: str) -> list:\n    secoes, titulo, linhas = [], \"\", []\n    for linha in (corpo or \"\").replace(\"\\r\", \"\").split(\"\\n\"):\n        achado = TITULO_DE_SECAO.match(linha)\n        if achado:\n            if titulo or any(l.strip() for l in linhas):\n                secoes.append((titulo, \"\\n\".join(linhas).strip()))\n            titulo, linhas = achado.group(1), []\n        else:\n            linhas.append(linha)\n    if titulo or any(l.strip() for l in linhas):\n        secoes.append((titulo, \"\\n\".join(linhas).strip()))\n    return secoes\n\n\ndef secoes_que(secoes: list, casa) -> str:\n    achadas = [texto for titulo, texto in secoes\n               if casa(titulo.lower()) and texto]\n    return \"\\n\\n\".join(achadas)\n\n\ndef criterios_do_corpo(corpo: str) -> list:\n    return [linha.strip() for linha in (corpo or \"\").replace(\"\\r\", \"\")\n            .split(\"\\n\") if LINHA_DE_CRITERIO.match(linha)]\n\n\ndef em_branco(criterios: list) -> list:\n    return [linha for linha in criterios\n            if LINHA_DE_CRITERIO.match(linha).group(1) == \" \"]\n\n\ndef commits_da_issue(principal: Path, numero: int) -> list:\n    codigo, saida = rodar_git(principal, \"log\", \"--all\", \"-F\",\n                              f\"--grep=(issue {numero})\",\n                              \"--format=%h%x09%s\", f\"-n{TETO_DE_COMMITS}\")\n    if codigo != 0 or not saida:\n        return []\n    return [tuple(linha.split(\"\\t\", 1)) for linha in saida.splitlines()\n            if \"\\t\" in linha]\n\n\ndef fechada_por(issue: dict) -> str:\n    pedidos = ((issue.get(\"closedByPullRequestsReferences\") or {})\n               .get(\"nodes\") or [])\n    if not pedidos:\n        return FECHADA_A_MAO\n    return \"; \".join(LINHA_DO_PEDIDO_QUE_FECHOU.format(\n        url=pedido.get(\"url\", \"\"), titulo=pedido.get(\"title\", \"\"),\n        mesclado=(MESCLADO_EM.format(pedido[\"mergedAt\"][:10])\n                  if pedido.get(\"mergedAt\") else \"\"))\n        for pedido in pedidos)\n\n\ndef historico_da_issue(issue: dict, projeto: str, commits: list) -> str:\n    corpo = issue.get(\"body\") or \"\"\n    secoes = secoes_do_corpo(corpo)\n    criterios = criterios_do_corpo(corpo)\n    brancos = em_branco(criterios)\n    return MOLDE_DO_HISTORICO.format(\n        numero=issue.get(\"number\"), titulo=issue.get(\"title\", \"\"),\n        projeto=projeto, quando=(issue.get(\"closedAt\") or \"\")[:10],\n        motivo=MOTIVO_DO_FECHAMENTO.get(issue.get(\"stateReason\") or \"\",\n                                        issue.get(\"stateReason\") or \"?\"),\n        url=issue.get(\"url\", \"\"), fechada_por=fechada_por(issue),\n        quantos_commits=len(commits),\n        pedido=secoes_que(secoes, lambda t: t.startswith(SECOES_DO_PEDIDO))\n        or SEM_SECAO,\n        criterios=\"\\n\".join(criterios) or SEM_CRITERIO,\n        em_branco=(COM_CRITERIO_EM_BRANCO.format(quantos=len(brancos))\n                   if brancos else NENHUM_EM_BRANCO),\n        decisoes=secoes_que(secoes, lambda t: PEDACO_DA_SECAO_DE_DECISAO in t)\n        or SEM_SECAO,\n        estado=secoes_que(secoes, lambda t: t == SECAO_DO_ESTADO) or SEM_SECAO,\n        onde_mora=secoes_que(\n            secoes, lambda t: t.startswith(PEDACO_DA_SECAO_DE_ONDE_MORA))\n        or SEM_ONDE_MORA,\n        commits=\"\\n\".join(LINHA_DO_COMMIT.format(hash=h, assunto=a)\n                          for h, a in commits) or SEM_COMMIT)\n\n\ndef formas_de_segredo(texto: str) -> list:\n    achados = []\n    for numero, linha in enumerate(texto.split(\"\\n\"), start=1):\n        for forma, padrao in FORMAS_DE_SEGREDO:\n            if padrao.search(linha):\n                achados.append(ACHADO_DE_SEGREDO.format(linha=numero,\n                                                        forma=forma))\n    return achados\n\n\ndef pasta_do_historico(principal: Path) -> Path:\n    return Path(principal) / PASTA_DO_HISTORICO\n\n\ndef chegada_do_instrumento(instrumento: Path, principal: Path):\n    pasta = Path(instrumento).resolve().parent\n    if arvore_principal(pasta) != Path(principal).resolve():\n        return None\n    codigo, saida = rodar_git(pasta, \"log\", \"--diff-filter=A\", \"--format=%cI\",\n                              \"--\", Path(instrumento).name)\n    datas = [instante(linha) for linha in saida.splitlines()] \\\n        if codigo == 0 else []\n    datas = [data for data in datas if data is not None]\n    return min(datas).astimezone(timezone.utc) if datas else None\n\n\ndef marco_do_historico(principal: Path, agora: datetime,\n                       instrumento: Path) -> tuple:\n    arquivo = pasta_do_historico(principal) / ARQUIVO_DO_MARCO\n    try:\n        lido = instante(arquivo.read_text(encoding=\"utf-8\").strip())\n    except OSError:\n        lido = None\n    if lido is not None:\n        return lido, \"\"\n    chegada = chegada_do_instrumento(instrumento, principal)\n    marco = chegada or agora\n    arquivo.parent.mkdir(parents=True, exist_ok=True)\n    arquivo.write_text(marco.isoformat() + \"\\n\", encoding=\"utf-8\")\n    molde = RECADO_MARCO_DA_CHEGADA if chegada else RECADO_MARCO_NOVO\n    return marco, molde.format(marco=marco.isoformat())\n\n\ndef numeros_com_historico(principal: Path) -> set:\n    pasta = pasta_do_historico(principal)\n    numeros = set()\n    for arquivo in pasta.glob(\"*/*.md\") if pasta.is_dir() else []:\n        cabeca = arquivo.name.split(\"-\", 1)[0]\n        if cabeca.isdigit():\n            numeros.add(int(cabeca))\n    return numeros\n\n\ndef fechadas_desde(endereco: dict, marco: datetime) -> tuple:\n    feito = gh.na_conta(endereco[\"conta\"], [\n        \"issue\", \"list\", \"--repo\", endereco[\"repositorio\"], \"--state\",\n        \"closed\", \"--search\", f\"closed:>={marco.date().isoformat()}\",\n        \"--limit\", str(TETO_DA_LISTA), \"--json\", \"number,closedAt\"])\n    if feito is None or feito.returncode != 0:\n        return None, FALHA_AO_LISTAR.format(motivo=gh.berro(feito))\n    try:\n        lidas = json.loads(feito.stdout or \"[]\")\n    except ValueError as falha:\n        return None, FALHA_AO_LISTAR.format(motivo=falha)\n    fechadas = []\n    for issue in lidas if isinstance(lidas, list) else []:\n        quando = instante(issue.get(\"closedAt\"))\n        if isinstance(issue.get(\"number\"), int) and quando is not None \\\n                and quando >= marco:\n            fechadas.append(issue[\"number\"])\n    return sorted(fechadas), \"\"\n\n\ndef ler_a_issue(endereco: dict, numero: int) -> tuple:\n    dono, nome = endereco[\"repositorio\"].split(\"/\", 1)\n    feito = gh.na_conta(endereco[\"conta\"], [\n        \"api\", \"graphql\", \"-f\", f\"query={CONSULTA_DA_ISSUE}\",\n        \"-f\", f\"dono={dono}\", \"-f\", f\"nome={nome}\", \"-F\", f\"numero={numero}\"])\n    if feito is None or feito.returncode != 0:\n        return None, FALHA_AO_LER_A_ISSUE.format(numero=numero,\n                                                 motivo=gh.berro(feito))\n    try:\n        issue = json.loads(feito.stdout)[\"data\"][\"repository\"][\"issue\"]\n    except (ValueError, KeyError, TypeError) as falha:\n        return None, FALHA_AO_LER_A_ISSUE.format(numero=numero, motivo=falha)\n    if not isinstance(issue, dict):\n        return None, FALHA_AO_LER_A_ISSUE.format(\n            numero=numero, motivo=\"o rastreador n\u00e3o devolveu a issue\")\n    return issue, \"\"\n\n\ndef git_ignora(principal: Path, alvo: Path) -> bool:\n    codigo, _ = rodar_git(principal, \"check-ignore\", \"-q\",\n                          str(alvo.relative_to(principal).as_posix()))\n    if codigo == 0:\n        return True\n    return codigo not in (1,) and not (principal / \".git\").exists()\n\n\ndef pedir_a_ronda(principal: Path) -> str:\n    indexador = Path(principal) / INDEXADOR\n    if not indexador.is_file():\n        return RECADO_SEM_INDICE\n    comando = [sys.executable, str(indexador), BANDEIRA_DA_RONDA, \"--cwd\",\n               str(principal)]\n    try:\n        feito = subprocess.run(comando, capture_output=True, text=True,\n                               encoding=\"utf-8\", errors=\"replace\",\n                               timeout=TEMPO_DA_RONDA, cwd=str(principal))\n    except (OSError, subprocess.SubprocessError) as falha:\n        return RECADO_RONDA_FALHOU.format(motivo=type(falha).__name__,\n                                          comando=\" \".join(comando[1:]))\n    linhas = [l for l in (feito.stdout + feito.stderr).splitlines()\n              if l.strip()]\n    if feito.returncode != 0:\n        return RECADO_RONDA_FALHOU.format(\n            motivo=(linhas[-1] if linhas else feito.returncode),\n            comando=\" \".join(comando[1:]))\n    return RECADO_RONDA.format(ultima=linhas[-1] if linhas else \"sem sa\u00edda\")\n\n\ndef colher_uma(principal: Path, endereco: dict, cadastrados: list,\n               numero: int, marco: datetime, ensaio: bool) -> tuple:\n    issue, erro = ler_a_issue(endereco, numero)\n    if erro:\n        return False, erro\n    fechou = instante(issue.get(\"closedAt\"))\n    if fechou is None:\n        return False, RECUSA_ABERTA.format(numero=numero)\n    if fechou < marco:\n        return False, RECUSA_ANTES_DO_MARCO.format(\n            numero=numero, quando=fechou.isoformat(), marco=marco.isoformat())\n    etiquetas = [no.get(\"name\") for no in\n                 (issue.get(\"labels\") or {}).get(\"nodes\") or []]\n    projeto = projeto_da_issue(etiquetas, cadastrados)\n    texto = historico_da_issue(issue, projeto,\n                               commits_da_issue(principal, numero))\n    achados = formas_de_segredo(texto)\n    if achados:\n        return False, RECUSA_SEGREDO.format(numero=numero,\n                                            achados=\"; \".join(achados))\n    alvo = (pasta_do_historico(principal) / projeto\n            / nome_do_arquivo(numero, issue.get(\"title\", \"\")))\n    relativo = alvo.relative_to(principal).as_posix()\n    if ensaio:\n        return True, RECADO_DO_ENSAIO.format(caminho=relativo, texto=texto)\n    if not git_ignora(principal, alvo):\n        return False, RECUSA_FORA_DO_IGNORE.format(numero=numero,\n                                                   alvo=relativo)\n    alvo.parent.mkdir(parents=True, exist_ok=True)\n    alvo.write_text(texto, encoding=\"utf-8\")\n    return True, RECADO_GRAVADO.format(caminho=relativo, raiz=principal)\n\n\ndef preparar(cwd: str, agora: datetime, instrumento: Path = None) -> tuple:\n    principal = arvore_principal(Path(cwd or \".\"))\n    dado, erro = configuracao(principal, Path(cwd or \".\"))\n    if erro:\n        return None, erro\n    endereco, erro = endereco_das_issues(dado)\n    if erro:\n        return None, erro\n    arquivo_do_marco = pasta_do_historico(principal) / ARQUIVO_DO_MARCO\n    if not git_ignora(principal, arquivo_do_marco):\n        return None, RECUSA_PASTA_FORA_DO_IGNORE.format(\n            alvo=arquivo_do_marco.parent.relative_to(principal).as_posix())\n    marco, recado_do_marco_novo = marco_do_historico(\n        principal, agora, Path(instrumento or __file__))\n    return {\"principal\": principal, \"endereco\": endereco, \"marco\": marco,\n            \"recado_do_marco_novo\": recado_do_marco_novo,\n            \"cadastrados\": projetos_cadastrados(dado)}, \"\"\n\n\ndef pendentes(cwd: str = \"\", agora: datetime = None,\n              instrumento: Path = None) -> tuple:\n    contexto, erro = preparar(cwd, agora or agora_em_utc(), instrumento)\n    if erro:\n        return SAIDA_NAO_MEDIDA, erro\n    fechadas, erro = fechadas_desde(contexto[\"endereco\"], contexto[\"marco\"])\n    if erro:\n        return SAIDA_NAO_MEDIDA, erro\n    faltam = [n for n in fechadas\n              if n not in numeros_com_historico(contexto[\"principal\"])]\n    marco = contexto[\"marco\"].isoformat()\n    if not faltam:\n        return SAIDA_LIMPA, (contexto[\"recado_do_marco_novo\"]\n                             or RECADO_SEM_PENDENTE.format(marco=marco))\n    return SAIDA_COM_ACHADO, RECADO_PENDENTES.format(\n        quantas=len(faltam), marco=marco,\n        lista=\", \".join(f\"#{n}\" for n in faltam))\n\n\ndef colher(numeros=(), cwd: str = \"\", ensaio: bool = False,\n           agora: datetime = None, reindexar: bool = True,\n           instrumento: Path = None) -> tuple:\n    contexto, erro = preparar(cwd, agora or agora_em_utc(), instrumento)\n    if erro:\n        return SAIDA_NAO_MEDIDA, [erro]\n    alvos = [int(n) for n in numeros or []]\n    if not alvos:\n        fechadas, erro = fechadas_desde(contexto[\"endereco\"],\n                                        contexto[\"marco\"])\n        if erro:\n            return SAIDA_NAO_MEDIDA, [erro]\n        ja = numeros_com_historico(contexto[\"principal\"])\n        alvos = [n for n in fechadas if n not in ja]\n    if not alvos:\n        pasta = pasta_do_historico(contexto[\"principal\"])\n        arquivo = pasta / \"LEIAME.md\"\n        if git_ignora(contexto[\"principal\"], arquivo) and not arquivo.exists():\n            pasta.mkdir(parents=True, exist_ok=True)\n            arquivo.write_text(\n                \"Aqui moram os hist\u00f3ricos das issues encerradas, por projeto.\\n\",\n                encoding=\"utf-8\")\n        return SAIDA_LIMPA, [RECADO_SEM_PENDENTE.format(\n            marco=contexto[\"marco\"].isoformat())]\n    recados, gravou, falhou = [], False, False\n    for numero in alvos:\n        certo, recado = colher_uma(contexto[\"principal\"], contexto[\"endereco\"],\n                                   contexto[\"cadastrados\"], numero,\n                                   contexto[\"marco\"], ensaio)\n        recados.append(recado)\n        gravou = gravou or (certo and not ensaio)\n        falhou = falhou or not certo\n    if gravou and reindexar:\n        recados.append(pedir_a_ronda(contexto[\"principal\"]))\n    return (SAIDA_NAO_MEDIDA if falhou else SAIDA_LIMPA), recados\n\n\nGH_DE_MENTIRA = \"\"\"import json\nimport os\nimport pathlib\nimport sys\n\nCAIXA = pathlib.Path(os.environ[\"HISTORICO_TESTE_CAIXA\"])\nsys.stdout.reconfigure(encoding=\"utf-8\")\nargv = sys.argv[1:]\n(CAIXA / \"chamadas.txt\").open(\"a\", encoding=\"utf-8\").write(\n    \" \".join(argv) + chr(10))\nif argv[:2] == [\"auth\", \"token\"]:\n    print(\"token-de-\" + argv[-1])\nelif argv[:2] == [\"issue\", \"list\"]:\n    print((CAIXA / \"fechadas.json\").read_text(encoding=\"utf-8\"))\nelif argv[:2] == [\"api\", \"graphql\"]:\n    numero = [a for a in argv if a.startswith(\"numero=\")][0].split(\"=\")[1]\n    issue = json.loads((CAIXA / (\"issue-\" + numero + \".json\"))\n                       .read_text(encoding=\"utf-8\"))\n    print(json.dumps({\"data\": {\"repository\": {\"issue\": issue}}}))\nsys.exit(0)\n\"\"\"\n\nINDEXADOR_DE_MENTIRA = \"\"\"import pathlib\nimport sys\npathlib.Path(sys.argv[0]).with_name(\"ronda-pedida.txt\").write_text(\n    \" \".join(sys.argv[1:]), encoding=\"utf-8\")\nprint(\"ronda: 1 alvo com mudan\u00e7a, indexado\")\n\"\"\"\n\nCORPO_FICTICIO = \"\"\"**Sess\u00e3o:** conclu\u00edda\n\n## Objetivo\nO relat\u00f3rio da vitrine fict\u00edcia fecha com o total certo.\n\n## Crit\u00e9rio de aceita\u00e7\u00e3o\n- [x] o total bate \u2014 prova: `rodar-o-relatorio` \u2192 total 42\n- [ ] o estorno aparece na linha dele\n\n## Decis\u00f5es do dono\n- 01/01: o estorno fica para depois, porque ningu\u00e9m o usa hoje.\n\n## Estado\nFeito: o total. Falta: o estorno.\n\n## Onde mora o que se aprendeu\n- conta de teste da vitrine: linha no `.credenciais/INVENTARIO.md`, papel \"cliente\"\n\"\"\"\n\n\ndef _repositorio(pasta: Path) -> Path:\n    pasta.mkdir(parents=True, exist_ok=True)\n    for argumentos in ([\"init\", \"-q\", \"-b\", \"principal\"],\n                       [\"config\", \"user.email\", \"prova@exemplo\"],\n                       [\"config\", \"user.name\", \"Prova\"]):\n        subprocess.run([\"git\", \"-C\", str(pasta), *argumentos], check=True,\n                       capture_output=True)\n    (pasta / \".gitignore\").write_text(\n        \"/\" + PASTA_DO_HISTORICO + \"/\\n/nucleo/executor.json\\n\",\n        encoding=\"utf-8\")\n    (pasta / \"nucleo\").mkdir(exist_ok=True)\n    (pasta / ARQUIVO_DO_EXECUTOR).write_text(json.dumps({\n        \"issues\": {\"repositorio\": \"dono-ficticio/quadro\", \"conta_gh\": \"robo\"},\n        \"projetos\": {\"vitrine\": {\"repositorio\": \"vitrine\"},\n                     \"balcao\": {\"repositorio\": \"balcao\"}}}),\n        encoding=\"utf-8\")\n    subprocess.run([\"git\", \"-C\", str(pasta), \"add\", \".\"], check=True,\n                   capture_output=True)\n    subprocess.run([\"git\", \"-C\", str(pasta), \"commit\", \"-q\", \"-m\",\n                    \"o total da vitrine bate (issue 7)\"], check=True,\n                   capture_output=True)\n    return pasta\n\n\ndef _issue(numero: int, fechou: str, corpo: str = CORPO_FICTICIO,\n           etiquetas=(\"vitrine\",), pedidos=()) -> dict:\n    return {\"number\": numero,\n            \"title\": \"vitrine - O relat\u00f3rio fecha com o total certo\",\n            \"body\": corpo, \"url\": f\"https://exemplo.invalido/issues/{numero}\",\n            \"stateReason\": \"COMPLETED\", \"closedAt\": fechou,\n            \"labels\": {\"nodes\": [{\"name\": nome} for nome in etiquetas]},\n            \"closedByPullRequestsReferences\": {\"nodes\": list(pedidos)}}\n\n\nCAMINHO_EM_QUEM_INSTALA = \".agents/historico/historico.py\"\nCAMINHO_NA_CASA = \"modulos/historico/.agents/historico/historico.py\"\n\n\ndef _commit_em(pasta: Path, quando: str, mensagem: str) -> None:\n    datado = dict(os.environ, GIT_AUTHOR_DATE=quando,\n                  GIT_COMMITTER_DATE=quando)\n    subprocess.run([\"git\", \"-C\", str(pasta), \"add\", \"-A\"], check=True,\n                   capture_output=True)\n    subprocess.run([\"git\", \"-C\", str(pasta), \"commit\", \"-q\", \"-m\", mensagem],\n                   check=True, capture_output=True, env=datado)\n\n\ndef _instrumento_no_checkout(pasta: Path, caminho: str,\n                             chegou_em: str = \"\") -> Path:\n    instrumento = pasta / caminho\n    instrumento.parent.mkdir(parents=True, exist_ok=True)\n    instrumento.write_text(\"print('instrumento de prova')\\n\",\n                           encoding=\"utf-8\")\n    if chegou_em:\n        _commit_em(pasta, chegou_em, \"o hist\u00f3rico chega\")\n    return instrumento\n\n\ndef _marco_lido(principal: Path):\n    arquivo = pasta_do_historico(principal) / ARQUIVO_DO_MARCO\n    return instante(arquivo.read_text(encoding=\"utf-8\").strip()) \\\n        if arquivo.is_file() else None\n\n\ndef testar() -> int:\n    passou = falhou = 0\n\n    def caso(nome: str, condicao) -> None:\n        nonlocal passou, falhou\n        if condicao:\n            passou += 1\n        else:\n            falhou += 1\n            print(f\"FALHOU: {nome}\")\n\n    caso(\"o assunto do arquivo sai do t\u00edtulo sem o prefixo do projeto, sem \"\n         \"acento e em kebab\",\n         nome_do_arquivo(7, \"vitrine_fixa - Relat\u00f3rio: o total \u00e9 CERTO!\")\n         == \"7-relatorio-o-total-e-certo.md\")\n    caso(\"assunto longo corta na palavra, n\u00e3o no meio dela\",\n         len(assunto_do_titulo(\"x - \" + \"palavra \" * 30)) <= TETO_DO_ASSUNTO\n         and not assunto_do_titulo(\"x - \" + \"palavra \" * 30).endswith(\"-\"))\n    caso(\"o projeto sai da etiqueta que \u00e9 tamb\u00e9m chave do cadastro\",\n         projeto_da_issue([\"bug\", \"balcao\"], [\"vitrine\", \"balcao\"])\n         == \"balcao\")\n    caso(\"sem etiqueta cadastrada, a issue vai para a pasta sem projeto\",\n         projeto_da_issue([\"bug\"], [\"vitrine\"]) == PASTA_SEM_PROJETO)\n    criterios = criterios_do_corpo(CORPO_FICTICIO)\n    caso(\"os crit\u00e9rios saem como estavam, marcados e em branco\",\n         criterios == [\"- [x] o total bate \u2014 prova: `rodar-o-relatorio` \u2192 \"\n                       \"total 42\", \"- [ ] o estorno aparece na linha dele\"]\n         and len(em_branco(criterios)) == 1)\n    valor_falso = \"ghp_\" + \"a1B2c3D4e5F6g7H8i9J0\" * 2\n    achados = formas_de_segredo(f\"linha limpa\\ntoken novo {valor_falso}\\n\")\n    caso(\"texto com token falso \u00e9 acusado pela linha e pela forma, e o \"\n         \"recado n\u00e3o carrega o valor\",\n         achados == [\"linha 2: token do GitHub\"]\n         and valor_falso not in \"; \".join(achados))\n    caso(\"CONTROLE: vari\u00e1vel por nome e texto comum n\u00e3o s\u00e3o segredo\",\n         formas_de_segredo(\"token: `${GH_TOKEN}`\\no total bate\\n\") == [])\n    caso(\"senha escrita por extenso tamb\u00e9m \u00e9 acusada\",\n         formas_de_segredo(\"senha: abobrinha123\") != [])\n\n    with tempfile.TemporaryDirectory(prefix=\"historico-\") as pasta:\n        base = Path(pasta)\n        principal = _repositorio(base / \"principal\")\n        irma = base / \"irma\"\n        subprocess.run([\"git\", \"-C\", str(principal), \"worktree\", \"add\", \"-q\",\n                        \"-b\", \"trabalho\", str(irma)], check=True,\n                       capture_output=True)\n        caso(\"de dentro da worktree, a \u00e1rvore principal \u00e9 a raiz de onde ela \"\n             \"saiu\",\n             arvore_principal(irma) == principal.resolve())\n\n        caixa = base / \"caixa\"\n        caixa.mkdir()\n        (caixa / \"gh.py\").write_text(GH_DE_MENTIRA, encoding=\"utf-8\")\n        guardado = dict(os.environ)\n        os.environ[\"HISTORICO_TESTE_CAIXA\"] = str(caixa)\n        os.environ[gh.VARIAVEL_DO_GH] = gh.linha_de_comando(sys.executable,\n                                                           caixa / \"gh.py\")\n        try:\n            antes = datetime(2030, 1, 1, tzinfo=timezone.utc)\n            depois = \"2030-01-02T10:00:00Z\"\n            (caixa / \"fechadas.json\").write_text(json.dumps([\n                {\"number\": 7, \"closedAt\": depois},\n                {\"number\": 8, \"closedAt\": depois},\n                {\"number\": 3, \"closedAt\": \"2029-12-31T10:00:00Z\"}]),\n                encoding=\"utf-8\")\n            (caixa / \"issue-7.json\").write_text(json.dumps(_issue(\n                7, depois, pedidos=[{\n                    \"number\": 70, \"title\": \"o total certo\",\n                    \"url\": \"https://exemplo.invalido/pull/70\",\n                    \"mergedAt\": depois}])), encoding=\"utf-8\")\n            (caixa / \"issue-8.json\").write_text(json.dumps(_issue(\n                8, depois, etiquetas=(\"balcao\",))), encoding=\"utf-8\")\n            (caixa / \"issue-3.json\").write_text(json.dumps(_issue(\n                3, \"2029-12-31T10:00:00Z\")), encoding=\"utf-8\")\n            (caixa / \"issue-9.json\").write_text(json.dumps(_issue(\n                9, depois, corpo=CORPO_FICTICIO + f\"\\n{valor_falso}\\n\")),\n                encoding=\"utf-8\")\n\n            codigo, recado = pendentes(cwd=str(irma), agora=antes)\n            caso(\"a primeira medida p\u00f5e o marco e j\u00e1 acusa as issues \"\n                 \"fechadas depois dele sem hist\u00f3rico \u2014 a de antes n\u00e3o conta\",\n                 codigo == SAIDA_COM_ACHADO and \"#7\" in recado\n                 and \"#8\" in recado and \"#3\" not in recado\n                 and (principal / PASTA_DO_HISTORICO / ARQUIVO_DO_MARCO)\n                 .is_file())\n\n            codigo, recados = colher([7], cwd=str(irma), agora=antes)\n            gravado = (principal / PASTA_DO_HISTORICO / \"vitrine\"\n                       / \"7-o-relatorio-fecha-com-o-total-certo.md\")\n            texto = gravado.read_text(encoding=\"utf-8\") \\\n                if gravado.is_file() else \"\"\n            caso(\"a issue fechada por pedido de incorpora\u00e7\u00e3o vira hist\u00f3rico \"\n                 \"na pasta do projeto dela, na \u00e1rvore PRINCIPAL\",\n                 codigo == SAIDA_LIMPA and gravado.is_file()\n                 and not (irma / PASTA_DO_HISTORICO / \"vitrine\").exists())\n            caso(\"o hist\u00f3rico traz os crit\u00e9rios como estavam e aponta o que \"\n                 \"ficou em branco, sem dar a issue por pronta\",\n                 \"- [ ] o estorno aparece na linha dele\" in texto\n                 and \"Em branco no fechamento: 1\" in texto)\n            caso(\"e traz o pedido que a fechou, o commit pela marca, a \"\n                 \"decis\u00e3o e o ponteiro de onde mora o que se aprendeu\",\n                 \"https://exemplo.invalido/pull/70\" in texto\n                 and \"o total da vitrine bate (issue 7)\" in texto\n                 and \"o estorno fica para depois\" in texto\n                 and \".credenciais/INVENTARIO.md\" in texto)\n            caso(\"o recado prova que gravou na \u00e1rvore principal\",\n                 str(principal) in \" \".join(recados))\n\n            (principal / INDEXADOR).parent.mkdir(parents=True)\n            (principal / INDEXADOR).write_text(INDEXADOR_DE_MENTIRA,\n                                               encoding=\"utf-8\")\n            codigo, recados = colher([8], cwd=str(irma), agora=antes)\n            caso(\"a issue fechada \u00e0 m\u00e3o, sem pedido, tamb\u00e9m vira hist\u00f3rico, \"\n                 \"e diz que fechou \u00e0 m\u00e3o\",\n                 codigo == SAIDA_LIMPA\n                 and FECHADA_A_MAO in (principal / PASTA_DO_HISTORICO\n                                       / \"balcao\" / nome_do_arquivo(\n                                           8, _issue(8, depois)[\"title\"]))\n                 .read_text(encoding=\"utf-8\"))\n            caso(\"depois de gravar, o \u00edndice recebe o pedido da ronda\",\n                 (principal / INDEXADOR).with_name(\"ronda-pedida.txt\")\n                 .is_file() and \"\u00edndice: ronda\" in \" \".join(recados))\n\n            codigo, recado = pendentes(cwd=str(irma), agora=antes)\n            caso(\"com o hist\u00f3rico nascido, o aviso para de acusar\",\n                 codigo == SAIDA_LIMPA and \"#7\" not in recado)\n\n            principal_vazia = _repositorio(base / \"principal-vazia\")\n            irma_vazia = base / \"irma-vazia\"\n            subprocess.run([\"git\", \"-C\", str(principal_vazia), \"worktree\",\n                            \"add\", \"-q\", \"-b\", \"vazia\", str(irma_vazia)],\n                           check=True, capture_output=True)\n            caixa_vazia = base / \"caixa-vazia\"\n            caixa_vazia.mkdir()\n            (caixa_vazia / \"fechadas.json\").write_text(\"[]\", encoding=\"utf-8\")\n            os.environ[\"HISTORICO_TESTE_CAIXA\"] = str(caixa_vazia)\n            try:\n                codigo, recados = colher(cwd=str(irma_vazia), agora=antes,\n                                        reindexar=False)\n                leiame = pasta_do_historico(principal_vazia) / \"LEIAME.md\"\n                caso(\"colher sem issue pendente cria LEIAME com uma linha \"\n                     \"na \u00e1rvore principal\",\n                     codigo == SAIDA_LIMPA and leiame.is_file()\n                     and len(leiame.read_text(encoding=\"utf-8\").splitlines()) == 1)\n                leiame.write_text(\n                    \"Texto escolhido por quem mant\u00e9m a pasta.\\n\",\n                    encoding=\"utf-8\")\n                codigo, recados = colher(cwd=str(irma_vazia), agora=antes,\n                                        reindexar=False)\n                caso(\"colher preserva o LEIAME j\u00e1 escrito\",\n                     codigo == SAIDA_LIMPA\n                     and leiame.read_text(encoding=\"utf-8\")\n                     == \"Texto escolhido por quem mant\u00e9m a pasta.\\n\")\n            finally:\n                os.environ[\"HISTORICO_TESTE_CAIXA\"] = str(caixa)\n\n            codigo, recados = colher([3], cwd=str(irma), agora=antes)\n            caso(\"issue fechada antes do marco n\u00e3o se colhe: o hist\u00f3rico vale \"\n                 \"s\u00f3 daqui para frente\",\n                 codigo == SAIDA_NAO_MEDIDA and \"antes do marco\" in recados[0])\n\n            codigo, recados = colher([9], cwd=str(irma), agora=antes)\n            caso(\"corpo com valor de credencial falso \u00e9 recusado ANTES de \"\n                 \"gravar, e o recado n\u00e3o mostra o valor\",\n                 codigo == SAIDA_NAO_MEDIDA and \"forma de segredo\" in recados[0]\n                 and valor_falso not in recados[0]\n                 and not list((principal / PASTA_DO_HISTORICO)\n                              .glob(\"*/9-*.md\")))\n\n            (principal / \".gitignore\").write_text(\"/nucleo/executor.json\\n\",\n                                                  encoding=\"utf-8\")\n            (caixa / \"issue-10.json\").write_text(json.dumps(_issue(\n                10, depois)), encoding=\"utf-8\")\n            codigo, recados = colher([10], cwd=str(irma), agora=antes)\n            caso(\"pasta que o git n\u00e3o ignora n\u00e3o recebe hist\u00f3rico: o que \u00e9 \"\n                 \"rastreado sobe para o espelho\",\n                 codigo == SAIDA_NAO_MEDIDA and \"N\u00c3O ignora\" in recados[0]\n                 and not list((principal / PASTA_DO_HISTORICO)\n                              .glob(\"*/10-*.md\")))\n            (principal / \".gitignore\").write_text(\n                \"/\" + PASTA_DO_HISTORICO + \"/\\n/nucleo/executor.json\\n\",\n                encoding=\"utf-8\")\n\n            codigo, recados = colher([7], cwd=str(irma), agora=antes,\n                                     ensaio=True)\n            caso(\"o ensaio mostra o hist\u00f3rico e n\u00e3o grava\",\n                 codigo == SAIDA_LIMPA and \"ENSAIO\" in recados[0])\n\n            chegada = \"2029-12-30T10:00:00+00:00\"\n            primeira_vez = datetime(2030, 1, 5, tzinfo=timezone.utc)\n            tarde = _repositorio(base / \"chegou-antes\")\n            instrumento = _instrumento_no_checkout(\n                tarde, CAMINHO_EM_QUEM_INSTALA, chegada)\n            codigo, recado = pendentes(cwd=str(tarde), agora=primeira_vez,\n                                       instrumento=instrumento)\n            caso(\"checkout que recebe o instrumento tarde: o marco \u00e9 o commit \"\n                 \"que o trouxe, e a issue fechada entre a chegada e a \"\n                 \"primeira execu\u00e7\u00e3o entra na conta\",\n                 codigo == SAIDA_COM_ACHADO and \"#3\" in recado\n                 and _marco_lido(tarde) == instante(chegada))\n\n            instrumento.unlink()\n            _commit_em(tarde, \"2030-01-03T10:00:00+00:00\", \"o hist\u00f3rico sai\")\n            _instrumento_no_checkout(tarde, CAMINHO_EM_QUEM_INSTALA,\n                                     \"2030-01-04T10:00:00+00:00\")\n            (pasta_do_historico(tarde) / ARQUIVO_DO_MARCO).unlink(\n                missing_ok=True)\n            pendentes(cwd=str(tarde), agora=primeira_vez,\n                      instrumento=instrumento)\n            caso(\"instrumento que saiu e voltou conta a primeira chegada: a \"\n                 \"sobra aparece como pend\u00eancia, a falta sumiria calada\",\n                 _marco_lido(tarde) == instante(chegada))\n\n            escolhido = \"2030-01-01T00:00:00+00:00\"\n            (pasta_do_historico(tarde) / ARQUIVO_DO_MARCO).write_text(\n                escolhido + \"\\n\", encoding=\"utf-8\")\n            codigo, recado = pendentes(cwd=str(tarde), agora=primeira_vez,\n                                       instrumento=instrumento)\n            caso(\"CONTROLE: o .desde escrito vence a data do commit \u2014 \u00e9 a \"\n                 \"escolha de quem o escreveu\",\n                 \"#3\" not in recado and \"#7\" in recado\n                 and _marco_lido(tarde) == instante(escolhido))\n\n            casa = _repositorio(base / \"casa\")\n            da_casa = _instrumento_no_checkout(casa, CAMINHO_NA_CASA,\n                                               \"2030-01-03T10:00:00+00:00\")\n            codigo, recado = pendentes(cwd=str(casa), agora=primeira_vez,\n                                       instrumento=da_casa)\n            caso(\"na casa a fonte mora em outro caminho, e a chegada sai do \"\n                 \"caminho do pr\u00f3prio instrumento; o recado diz de onde veio \"\n                 \"o marco\",\n                 codigo == SAIDA_LIMPA and \"commit que trouxe\" in recado\n                 and _marco_lido(casa) == instante(\"2030-01-03T10:00:00Z\"))\n\n            sem_commit = _repositorio(base / \"sem-commit\")\n            solto = _instrumento_no_checkout(sem_commit,\n                                             CAMINHO_EM_QUEM_INSTALA)\n            codigo, recado = pendentes(cwd=str(sem_commit),\n                                       agora=primeira_vez, instrumento=solto)\n            caso(\"CONTROLE: instrumento instalado e ainda sem commit cai no \"\n                 \"comportamento de hoje \u2014 o marco \u00e9 a primeira execu\u00e7\u00e3o\",\n                 codigo == SAIDA_LIMPA and \"#3\" not in recado\n                 and _marco_lido(sem_commit) == primeira_vez)\n\n            alheio = _repositorio(base / \"alheio\")\n            codigo, recado = pendentes(cwd=str(alheio), agora=primeira_vez,\n                                       instrumento=instrumento)\n            caso(\"CONTROLE: o instrumento de outro reposit\u00f3rio n\u00e3o d\u00e1 a \"\n                 \"chegada a este checkout \u2014 cai no comportamento de hoje\",\n                 \"#3\" not in recado and _marco_lido(alheio) == primeira_vez)\n        finally:\n            os.environ.clear()\n            os.environ.update(guardado)\n\n        sem_linha = _repositorio(base / \"sem-linha\")\n        (sem_linha / \".gitignore\").write_text(\"/nucleo/executor.json\\n\",\n                                              encoding=\"utf-8\")\n        codigo, recado = pendentes(cwd=str(sem_linha))\n        caso(\"raiz cujo git n\u00e3o ignora a pasta n\u00e3o recebe nem o marco: a \"\n             \"medida diz que n\u00e3o mediu e nada nasce solto no git status\",\n             codigo == SAIDA_NAO_MEDIDA and \"N\u00c3O ignora\" in recado\n             and not (sem_linha / PASTA_DO_HISTORICO).exists())\n\n        sem_endereco = _repositorio(base / \"sem-endereco\")\n        (sem_endereco / ARQUIVO_DO_EXECUTOR).write_text(\"{}\",\n                                                         encoding=\"utf-8\")\n        codigo, recado = pendentes(cwd=str(sem_endereco))\n        caso(\"sem o reposit\u00f3rio das issues declarado, a medida diz que n\u00e3o \"\n             \"mediu, em vez de dizer que n\u00e3o h\u00e1 pend\u00eancia\",\n             codigo == SAIDA_NAO_MEDIDA and \"issues.repositorio\" in recado)\n\n    print(f\"{'OK' if not falhou else 'FALHOU'}: {passou + falhou} casos\")\n    return 1 if falhou else 0\n\n\ndef montar_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(description=USO)\n    parser.add_argument(\"--pendentes\", action=\"store_true\",\n                        help=\"diz quantas issues fecharam depois do marco e \"\n                             \"ainda n\u00e3o t\u00eam hist\u00f3rico; sai 1 se houver\")\n    parser.add_argument(\"--colher\", action=\"store_true\",\n                        help=\"grava o hist\u00f3rico das pendentes, ou s\u00f3 das \"\n                             \"pedidas em --issue\")\n    parser.add_argument(\"--issue\", action=\"append\", type=int, default=[],\n                        help=\"o n\u00famero de uma issue fechada; repita a \"\n                             \"bandeira\")\n    parser.add_argument(\"--ensaio\", action=\"store_true\",\n                        help=\"mostra o hist\u00f3rico sem gravar\")\n    parser.add_argument(\"--cwd\", default=\".\")\n    parser.add_argument(BANDEIRA_DE_TESTE, action=\"store_true\")\n    return parser\n\n\ndef main() -> int:\n    if BANDEIRA_DE_TESTE in sys.argv[1:]:\n        return testar()\n    a = montar_parser().parse_args()\n    if a.colher or a.issue:\n        codigo, recados = colher(a.issue, a.cwd, a.ensaio)\n        for recado in recados:\n            print(recado)\n        return codigo\n    codigo, recado = pendentes(a.cwd)\n    print(recado)\n    return codigo\n\n\nif __name__ == \"__main__\":\n    for canal in (sys.stdin, sys.stdout, sys.stderr):\n        if not getattr(canal, \"closed\", True) and hasattr(canal, \"reconfigure\"):\n            canal.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    sys.exit(main())\n"]
#[".agents/indice/buscar.py", "import argparse\nimport json\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nBANDEIRA_DE_TESTE = \"--testar\"\nUSO = (\"busca no acervo pelo ck no modo l\u00e9xico (BM25: termo e palavra, \"\n       \"ranqueados), com \u00edndice em arquivo dentro de cada alvo e nenhum \"\n       \"servi\u00e7o de p\u00e9. \u00c9 a porta normal para o acervo: n\u00e3o depende de \"\n       \"cliente MCP e nunca pede o modo por significado, que baixaria modelo. \"\n       \"Sem o ck no PATH, avisa numa linha e cai no grep\")\n\nARQUIVO_DOS_ALVOS = \".agents/indice/alvos.json\"\nCAMPO_DOS_ALVOS = \"alvos\"\nCAMPO_DO_QUE_IGNORAR = \"ignorar\"\nPROGRAMA_DO_CK = \"ck\"\nPASTA_DO_INDICE_DO_CK = \".ck\"\nLINHAS_QUE_O_CK_GRAVA = (\".ck/\", \".ckignore\")\nAMOSTRAS_DO_QUE_O_CK_GRAVA = {\".ck/\": \".ck/manifest.json\",\n                              \".ckignore\": \".ckignore\"}\nCOMO_INSTALAR_O_CK = (\"baixe o zip da sua plataforma nas vers\u00f5es de \"\n                      \"github.com/BeaconBay/ck, confira o SHA-256 e ponha o \"\n                      \"`ck` no PATH (ou `cargo install ck-search`)\")\nPREFIXO_LONGO_DO_WINDOWS = \"\\\\\\\\?\\\\\"\nQUANTOS_POR_PADRAO = 5\nTETO_TOTAL_POR_PADRAO = 30\nTETO_MINIMO = 1\nTETO_DO_GIT = 30\nTEMPO_DA_BUSCA = 600\nLETRAS_DO_TRECHO = 160\nLETRAS_MINIMAS_DA_PALAVRA = 3\nTETO_DE_BYTES_DO_GREP = 1_000_000\nAMOSTRA_DE_BINARIO = 4096\nPASTAS_QUE_O_GREP_PULA = {\"node_modules\", \"venv\", \"__pycache__\", \"vendor\",\n                          \"dist\", \"build\", \"target\"}\nLINHA_DO_GIT_GREP = re.compile(r\"^(.*?):(\\d+):(.*)$\")\nPALAVRA = re.compile(r\"[\\w.\\-]+\")\nSEM_ACHADO_NO_CK = \"No matches\"\n\nRECUSA_SEM_PERGUNTA = \"sem pergunta: diga o que voc\u00ea quer achar, entre aspas\"\nRECUSA_TETO_INVALIDO = (\"--teto-total \u00e9 o teto de trechos na resposta e \"\n                        \"precisa ser {} ou mais: {} n\u00e3o corta, desliga a \"\n                        \"conta \u2014 e resposta sem teto declarado despeja o \"\n                        \"contexto da sess\u00e3o sem ningu\u00e9m pedir\")\nCORTADO_NO_TETO = (\"\\ncortado no teto de {}: havia {} trecho(s). O resto n\u00e3o \"\n                   \"foi impresso \u2014 pe\u00e7a mais com --teto-total, ou estreite \"\n                   \"com --alvo e --quantos\")\nRECUSA_ALVO_DESCONHECIDO = (\"alvo que n\u00e3o existe nem est\u00e1 declarado: {}. Os \"\n                            \"declarados em {}:\\n{}\")\nALVO_AUSENTE = \"  n\u00e3o medido: {} n\u00e3o existe no disco \u2014 alvo declarado em outra \u00e1rvore\"\nAVISO_SEM_CK = (\"sem o `ck` no PATH: a busca cai no grep, por palavra e sem o \"\n                \"ranking do BM25. Para instalar: \" + COMO_INSTALAR_O_CK)\nAVISO_DO_DENSO = (\"--denso n\u00e3o muda nada: o motor \u00e9 l\u00e9xico, e o modo por \"\n                  \"significado do ck baixaria modelo\")\nNAO_MEDIDO_SEM_DENSO = (\"n\u00e3o medido: o motor \u00e9 l\u00e9xico e n\u00e3o tem denso nem \"\n                        \"h\u00edbrido para comparar; a r\u00e9gua medida est\u00e1 em \"\n                        \"conhecimento/indice.md\")\nEXCLUDE_ACRESCENTADO = (\"  {}: {} acrescentado(s) \u2014 o \u00edndice do ck n\u00e3o \"\n                        \"aparece no git de {}\")\nGIT_NAO_RESPONDEU = (\"  n\u00e3o medido: o git de {} n\u00e3o respondeu ({}) \u2014 o .ck/ \"\n                     \"pode aparecer no git status dele\")\nVAZIA = \"  {} \u2014 nenhum trecho casou com a pergunta: tente outra palavra\"\nCABECA = \"BUSCA {} \u2014 \\\"{}\\\" em {} alvo(s)\"\nMODO_LEXICO = \"l\u00e9xica pelo ck (BM25: termo e palavra)\"\nMODO_GREP = \"por grep (sem o ck)\"\nLINHA_DO_ALVO = \"  {}\"\nLINHA_DO_ACHADO = \"    [{:.3f}] {}:{}\"\nLINHA_DO_TRECHO = \"           {}\"\nRODAPE = (\"\\nA pontua\u00e7\u00e3o mede palavra em comum, n\u00e3o significado: o BM25 do ck \"\n          \"ou, no grep, a fra\u00e7\u00e3o das palavras da pergunta que a linha tem.\")\nFALHOU_A_CHAMADA = \"n\u00e3o consegui buscar em {}: {}\"\n\n\ndef configuracao(cwd: str = \"\") -> dict:\n    alvo = Path(cwd or \".\") / ARQUIVO_DOS_ALVOS\n    try:\n        return json.loads(alvo.read_text(encoding=\"utf-8\"))\n    except (OSError, json.JSONDecodeError):\n        return {}\n\n\ndef o_ck() -> str:\n    return shutil.which(PROGRAMA_DO_CK) or \"\"\n\n\ndef com_barra(caminho) -> str:\n    return os.path.normcase(os.path.normpath(str(caminho))).replace(\n        \"\\\\\", \"/\").rstrip(\"/\")\n\n\ndef git_da_pasta(pasta, *argumentos) -> tuple:\n    feito = subprocess.run([\"git\", *argumentos], capture_output=True,\n                           text=True, encoding=\"utf-8\", errors=\"replace\",\n                           timeout=TETO_DO_GIT, cwd=str(pasta))\n    return feito.returncode, feito.stdout\n\n\ndef raizes_do_git(cwd: str = \"\") -> list:\n    try:\n        codigo, saida = git_da_pasta(cwd or \".\", \"rev-parse\",\n                                     \"--path-format=absolute\",\n                                     \"--git-common-dir\")\n    except (OSError, subprocess.SubprocessError):\n        return []\n    comum = saida.strip()\n    return [Path(comum).parent] if codigo == 0 and comum else []\n\n\ndef alvos_declarados(dado: dict, cwd: str = \"\", raizes=None) -> list:\n    raizes = raizes_do_git(cwd) if raizes is None else raizes\n    base = Path(raizes[0]) if raizes else Path(cwd or \".\")\n    declarados = []\n    for alvo in dado.get(CAMPO_DOS_ALVOS) or []:\n        caminho = Path(alvo).expanduser()\n        declarados.append((caminho if caminho.is_absolute()\n                           else base / caminho).resolve())\n    return declarados\n\n\ndef formas_do_pedido(pedido: str, cwd: str, raizes) -> list:\n    caminho = Path(pedido).expanduser()\n    if caminho.is_absolute():\n        return [caminho]\n    return [Path(cwd or \".\") / caminho] + [Path(r) / caminho for r in raizes]\n\n\ndef escolher_alvos(pedido: str, declarados: list, cwd: str = \"\",\n                   raizes=()) -> list:\n    presentes = [p for p in declarados if p.is_dir()]\n    if not pedido:\n        return presentes or ([] if declarados else [Path(cwd or \".\").resolve()])\n    formas = formas_do_pedido(pedido, cwd, raizes)\n    iguais = {com_barra(forma) for forma in formas}\n    exatos = [p for p in presentes if com_barra(p) in iguais]\n    if exatos:\n        return exatos\n    fim = \"/\" + com_barra(pedido).strip(\"/\")\n    pelo_fim = [p for p in presentes if com_barra(p).endswith(fim)]\n    if pelo_fim:\n        return pelo_fim\n    return [forma.resolve() for forma in formas[:1] if forma.is_dir()]\n\n\ndef ignorado_pelo_git(pasta: Path, amostra: str) -> bool:\n    codigo, _ = git_da_pasta(pasta, \"check-ignore\", \"-q\", amostra)\n    return codigo == 0\n\n\ndef esconder_do_git(pasta: Path) -> str:\n    try:\n        codigo, _ = git_da_pasta(pasta, \"rev-parse\", \"--is-inside-work-tree\")\n        if codigo != 0:\n            return \"\"\n        faltam = [linha for linha in LINHAS_QUE_O_CK_GRAVA\n                  if not ignorado_pelo_git(\n                      pasta, AMOSTRAS_DO_QUE_O_CK_GRAVA[linha])]\n        if not faltam:\n            return \"\"\n        codigo, saida = git_da_pasta(pasta, \"rev-parse\",\n                                     \"--path-format=absolute\", \"--git-path\",\n                                     \"info/exclude\")\n    except (OSError, subprocess.SubprocessError) as erro:\n        return GIT_NAO_RESPONDEU.format(pasta, type(erro).__name__)\n    if codigo != 0 or not saida.strip():\n        return GIT_NAO_RESPONDEU.format(pasta, f\"git saiu {codigo}\")\n    exclude = Path(saida.strip())\n    atual = exclude.read_text(encoding=\"utf-8\") if exclude.is_file() else \"\"\n    novas = [linha for linha in faltam if linha not in atual.splitlines()]\n    if not novas:\n        return \"\"\n    exclude.parent.mkdir(parents=True, exist_ok=True)\n    emenda = \"\" if not atual or atual.endswith(\"\\n\") else \"\\n\"\n    with exclude.open(\"a\", encoding=\"utf-8\", newline=\"\\n\") as saida_do_arquivo:\n        saida_do_arquivo.write(emenda + \"\\n\".join(novas) + \"\\n\")\n    return EXCLUDE_ACRESCENTADO.format(exclude, \", \".join(novas), pasta)\n\n\ndef exclusoes_do_ck(dado: dict) -> list:\n    nomes = [str(padrao).strip(\"*/\") for padrao\n             in dado.get(CAMPO_DO_QUE_IGNORAR) or []]\n    return [parte for nome in nomes if nome\n            for parte in (\"--exclude\", nome)]\n\n\ndef relativo_ao_alvo(caminho: str, pasta: Path) -> str:\n    limpo = caminho[len(PREFIXO_LONGO_DO_WINDOWS):] \\\n        if caminho.startswith(PREFIXO_LONGO_DO_WINDOWS) else caminho\n    try:\n        return os.path.relpath(limpo, str(pasta)).replace(\"\\\\\", \"/\")\n    except ValueError:\n        return limpo.replace(\"\\\\\", \"/\")\n\n\ndef achado_do_ck(linha: str, pasta: Path) -> dict:\n    dado = json.loads(linha)\n    return {\"arquivo\": relativo_ao_alvo(dado.get(\"path\", \"?\"), pasta),\n            \"linha\": (dado.get(\"span\") or {}).get(\"line_start\", \"?\"),\n            \"trecho\": dado.get(\"snippet\", \"\"),\n            \"pontos\": float(dado.get(\"score\") or 0.0)}\n\n\ndef buscar_pelo_ck(ck: str, pasta: Path, pergunta: str, quantos: int,\n                   exclusoes=()) -> list:\n    if not (pasta / PASTA_DO_INDICE_DO_CK).is_dir():\n        recado = esconder_do_git(pasta)\n        if recado:\n            print(recado, file=sys.stderr)\n    feito = subprocess.run(\n        [ck, \"--lex\", \"--jsonl\", \"-q\", \"--topk\", str(quantos), *exclusoes,\n         pergunta, str(pasta)],\n        capture_output=True, text=True, encoding=\"utf-8\", errors=\"replace\",\n        timeout=TEMPO_DA_BUSCA, cwd=str(pasta))\n    if feito.returncode != 0:\n        if SEM_ACHADO_NO_CK in feito.stderr + feito.stdout:\n            return []\n        raise ValueError((feito.stderr or feito.stdout).strip()[-300:]\n                         or f\"o ck saiu {feito.returncode}\")\n    return [achado_do_ck(linha, pasta) for linha in feito.stdout.splitlines()\n            if linha.strip().startswith(\"{\")]\n\n\ndef palavras_da_pergunta(pergunta: str) -> list:\n    palavras = [p for p in PALAVRA.findall(pergunta.lower())\n                if len(p) >= LETRAS_MINIMAS_DA_PALAVRA]\n    return list(dict.fromkeys(palavras)) or [pergunta.lower().strip()]\n\n\ndef linhas_pelo_git_grep(pasta: Path, palavras: list):\n    argumentos = [\"grep\", \"-n\", \"-I\", \"-i\", \"-F\", \"--no-color\", \"--untracked\"]\n    for palavra in palavras:\n        argumentos += [\"-e\", palavra]\n    codigo, saida = git_da_pasta(pasta, *argumentos, \"--\", \".\")\n    if codigo not in (0, 1):\n        raise ValueError(f\"git grep saiu {codigo}\")\n    for linha in saida.splitlines():\n        casou = LINHA_DO_GIT_GREP.match(linha)\n        if casou:\n            yield casou.group(1), int(casou.group(2)), casou.group(3)\n\n\ndef arquivos_de_texto(pasta: Path):\n    for raiz, pastas, arquivos in os.walk(pasta):\n        pastas[:] = [p for p in pastas if not p.startswith(\".\")\n                     and p not in PASTAS_QUE_O_GREP_PULA]\n        for nome in arquivos:\n            caminho = Path(raiz) / nome\n            try:\n                if caminho.stat().st_size > TETO_DE_BYTES_DO_GREP:\n                    continue\n                conteudo = caminho.read_bytes()\n            except OSError:\n                continue\n            if b\"\\0\" in conteudo[:AMOSTRA_DE_BINARIO]:\n                continue\n            yield caminho, conteudo.decode(\"utf-8\", errors=\"replace\")\n\n\ndef linhas_pelo_python(pasta: Path, palavras: list):\n    for caminho, texto in arquivos_de_texto(pasta):\n        relativo = caminho.relative_to(pasta).as_posix()\n        for numero, linha in enumerate(texto.splitlines(), 1):\n            minuscula = linha.lower()\n            if any(palavra in minuscula for palavra in palavras):\n                yield relativo, numero, linha\n\n\ndef dentro_do_git(pasta: Path) -> bool:\n    try:\n        codigo, saida = git_da_pasta(pasta, \"rev-parse\",\n                                     \"--is-inside-work-tree\")\n    except (OSError, subprocess.SubprocessError):\n        return False\n    return codigo == 0 and saida.strip() == \"true\"\n\n\ndef buscar_pelo_grep(pasta: Path, pergunta: str, quantos: int) -> list:\n    palavras = palavras_da_pergunta(pergunta)\n    linhas = (linhas_pelo_git_grep(pasta, palavras) if dentro_do_git(pasta)\n              else linhas_pelo_python(pasta, palavras))\n    achados = []\n    for arquivo, numero, linha in linhas:\n        minuscula = linha.lower()\n        casadas = sum(1 for palavra in palavras if palavra in minuscula)\n        achados.append({\"arquivo\": arquivo, \"linha\": numero, \"trecho\": linha,\n                        \"pontos\": casadas / len(palavras)})\n    achados.sort(key=lambda a: (-a[\"pontos\"], a[\"arquivo\"], a[\"linha\"]))\n    return achados[:quantos]\n\n\ndef uma_linha(texto: str) -> str:\n    return \" \".join((texto or \"\").split())[:LETRAS_DO_TRECHO]\n\n\ndef buscar(pergunta: str, dado: dict, alvo: str = \"\",\n           quantos: int = QUANTOS_POR_PADRAO,\n           teto_total: int = TETO_TOTAL_POR_PADRAO, cwd: str = \"\",\n           localizar=o_ck, raizes=None) -> int:\n    if not (pergunta or \"\").strip():\n        print(RECUSA_SEM_PERGUNTA, file=sys.stderr)\n        return 2\n    if teto_total < TETO_MINIMO:\n        print(RECUSA_TETO_INVALIDO.format(TETO_MINIMO, teto_total),\n              file=sys.stderr)\n        return 2\n    raizes = raizes_do_git(cwd) if raizes is None else raizes\n    declarados = alvos_declarados(dado, cwd, raizes)\n    alvos = escolher_alvos(alvo, declarados, cwd, raizes)\n    if not alvos:\n        print(RECUSA_ALVO_DESCONHECIDO.format(\n            alvo, ARQUIVO_DOS_ALVOS,\n            \"\\n\".join(f\"  {p}\" for p in declarados) or \"  (nenhum)\"),\n            file=sys.stderr)\n        return 2\n    if not alvo:\n        for ausente in [p for p in declarados if not p.is_dir()]:\n            print(ALVO_AUSENTE.format(ausente), file=sys.stderr)\n    ck = localizar()\n    if not ck:\n        print(AVISO_SEM_CK, file=sys.stderr)\n    print(CABECA.format(MODO_LEXICO if ck else MODO_GREP, pergunta,\n                        len(alvos)))\n    achou = mostrados = 0\n    for pasta in alvos:\n        try:\n            achados = (buscar_pelo_ck(ck, pasta, pergunta, quantos,\n                                      exclusoes_do_ck(dado)) if ck\n                       else buscar_pelo_grep(pasta, pergunta, quantos))\n        except (OSError, subprocess.SubprocessError, ValueError) as erro:\n            print(FALHOU_A_CHAMADA.format(pasta, erro), file=sys.stderr)\n            continue\n        if not achados:\n            print(VAZIA.format(pasta))\n            continue\n        if mostrados < teto_total:\n            print(LINHA_DO_ALVO.format(pasta))\n        for item in achados:\n            achou += 1\n            if mostrados >= teto_total:\n                continue\n            mostrados += 1\n            print(LINHA_DO_ACHADO.format(item[\"pontos\"], item[\"arquivo\"],\n                                         item[\"linha\"]))\n            print(LINHA_DO_TRECHO.format(uma_linha(item[\"trecho\"])))\n    if achou > mostrados:\n        print(CORTADO_NO_TETO.format(teto_total, achou))\n    if achou:\n        print(RODAPE)\n    return 0 if achou else 1\n\n\ndef testar() -> int:\n    import contextlib\n    import io\n    import tempfile\n    falhas, rodados = [], []\n\n    def caso(rotulo, passou):\n        rodados.append(rotulo)\n        if not passou:\n            falhas.append(rotulo)\n\n    def repositorio(pasta: Path, gitignore: str = \"\") -> None:\n        (pasta / \"docs\").mkdir(parents=True)\n        (pasta / \"docs\" / \"a.md\").write_text(\n            \"# Regra\\n\\nA regra dezesseis cobra destino da entrega.\\n\",\n            encoding=\"utf-8\")\n        if gitignore:\n            (pasta / \".gitignore\").write_text(gitignore, encoding=\"utf-8\")\n        git_da_pasta(pasta, \"init\", \"-q\")\n        git_da_pasta(pasta, \"add\", \".\")\n        git_da_pasta(pasta, \"-c\", \"user.email=a@b\", \"-c\", \"user.name=a\",\n                     \"commit\", \"-qm\", \"x\")\n\n    def saida_de(*argumentos, **nomeados):\n        fora, erro = io.StringIO(), io.StringIO()\n        with contextlib.redirect_stdout(fora), contextlib.redirect_stderr(erro):\n            codigo = buscar(*argumentos, **nomeados)\n        return codigo, fora.getvalue(), erro.getvalue()\n\n    with tempfile.TemporaryDirectory(prefix=\"buscar-\") as base:\n        base = Path(base)\n        vizinho = base / \"vizinho\"\n        repositorio(vizinho, gitignore=\"*.log\\n\")\n        (vizinho / \".ck\").mkdir()\n        (vizinho / \".ck\" / \"manifest.json\").write_text(\"{}\", encoding=\"utf-8\")\n        (vizinho / \".ckignore\").write_text(\"*.png\\n\", encoding=\"utf-8\")\n        recado = esconder_do_git(vizinho)\n        _, status = git_da_pasta(vizinho, \"status\", \"--short\")\n        exclude = (vizinho / \".git\" / \"info\" / \"exclude\").read_text(\n            encoding=\"utf-8\").splitlines()\n        caso(\"vizinho com git: as duas linhas v\u00e3o ao exclude dele, e o git \"\n             \"status fica limpo\",\n             bool(recado) and status.strip() == \"\"\n             and all(linha in exclude for linha in LINHAS_QUE_O_CK_GRAVA))\n        caso(\"o .gitignore rastreado do vizinho n\u00e3o muda\",\n             (vizinho / \".gitignore\").read_text(encoding=\"utf-8\") == \"*.log\\n\")\n        caso(\"a segunda vez n\u00e3o duplica a linha\",\n             esconder_do_git(vizinho) == \"\"\n             and (vizinho / \".git\" / \"info\" / \"exclude\").read_text(\n                 encoding=\"utf-8\").splitlines().count(\".ck/\") == 1)\n\n        raiz = base / \"raiz\"\n        repositorio(raiz, gitignore=\".ck/\\n.ckignore\\n\")\n        antes = (raiz / \".git\" / \"info\" / \"exclude\").read_text(\n            encoding=\"utf-8\")\n        caso(\"reposit\u00f3rio cujo .gitignore j\u00e1 esconde o .ck: o exclude n\u00e3o \"\n             \"muda\",\n             esconder_do_git(raiz) == \"\"\n             and (raiz / \".git\" / \"info\" / \"exclude\").read_text(\n                 encoding=\"utf-8\") == antes)\n\n        solta = base / \"solta\"\n        solta.mkdir()\n        (solta / \"nota.md\").write_text(\"destino da entrega sem git\\n\",\n                                       encoding=\"utf-8\")\n        caso(\"pasta sem git: nada se escreve\", esconder_do_git(solta) == \"\"\n             and sorted(p.name for p in solta.iterdir()) == [\"nota.md\"])\n\n        sem_ck = lambda: \"\"\n        codigo, fora, erro = saida_de(\"destino entrega\", {}, str(solta),\n                                      cwd=str(base), localizar=sem_ck,\n                                      raizes=[])\n        caso(\"sem o ck, a busca avisa numa linha e cai no grep em Python, \"\n             \"sem erro\",\n             codigo == 0 and erro.count(\"\\n\") == 1 and \"grep\" in erro\n             and \"nota.md:1\" in fora and MODO_GREP in fora)\n        codigo, fora, erro = saida_de(\"destino entrega\",\n                                      {\"alvos\": [str(vizinho)]}, \"vizinho\",\n                                      cwd=str(base), localizar=sem_ck,\n                                      raizes=[])\n        caso(\"sem o ck, num alvo com git, o grep \u00e9 o git grep e o alvo \"\n             \"declarado casa pelo fim do caminho\",\n             codigo == 0 and \"docs/a.md:3\" in fora)\n        codigo, _, erro = saida_de(\"x\", {\"alvos\": [str(vizinho)]},\n                                   \"nao-existe\", cwd=str(base),\n                                   localizar=sem_ck, raizes=[])\n        caso(\"alvo que n\u00e3o existe nem est\u00e1 declarado \u00e9 recusado pelo nome, \"\n             \"com a lista dos declarados\",\n             codigo == 2 and \"nao-existe\" in erro and str(vizinho) in erro)\n        muitos = base / \"muitos\"\n        muitos.mkdir()\n        (muitos / \"tres.md\").write_text(\"destino\\ndestino\\ndestino\\n\",\n                                        encoding=\"utf-8\")\n        codigo, fora, _ = saida_de(\"destino\", {}, str(muitos), quantos=5,\n                                   teto_total=1, cwd=str(base),\n                                   localizar=sem_ck, raizes=[])\n        caso(\"teto-total corta e diz quanto havia\",\n             codigo == 0 and \"cortado no teto de 1: havia 3\" in fora\n             and fora.count(\"tres.md:\") == 1)\n\n        achado = achado_do_ck(json.dumps({\n            \"path\": PREFIXO_LONGO_DO_WINDOWS + str(vizinho / \"docs\" / \"a.md\"),\n            \"span\": {\"line_start\": 3}, \"snippet\": \"A regra\", \"score\": 0.5}),\n            vizinho)\n        caso(\"o achado do ck vira arquivo relativo ao alvo e linha, sem o \"\n             \"prefixo longo do Windows\",\n             achado[\"arquivo\"] == \"docs/a.md\" and achado[\"linha\"] == 3)\n        caso(\"o ignorar dos alvos vira --exclude do ck pelo nome da pasta\",\n             exclusoes_do_ck({\"ignorar\": [\"**/vendor/**\"]})\n             == [\"--exclude\", \"vendor\"])\n\n        if o_ck():\n            novo = base / \"novo\"\n            repositorio(novo)\n            codigo, fora, _ = saida_de(\"destino entrega\", {}, str(novo),\n                                       cwd=str(base), raizes=[])\n            _, status = git_da_pasta(novo, \"status\", \"--short\")\n            caso(\"com o ck, a busca l\u00e9xica indexa na primeira vez, devolve \"\n                 \"arquivo:linha e o trecho, e o git do alvo fica limpo\",\n                 codigo == 0 and \"docs/a.md:\" in fora and MODO_LEXICO in fora\n                 and (novo / PASTA_DO_INDICE_DO_CK).is_dir()\n                 and status.strip() == \"\")\n        else:\n            print(\"n\u00e3o medido: o ck n\u00e3o est\u00e1 no PATH \u2014 o caso da busca real \"\n                  \"n\u00e3o rodou\")\n\n    if falhas:\n        for f in falhas:\n            print(f\"FALHOU: {f}\")\n        print(f\"FALHOU: {len(falhas)} de {len(rodados)} casos\")\n        return 1\n    print(f\"OK: a busca do \u00edndice \u2014 {len(rodados)} casos\")\n    return 0\n\n\ndef montar_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(description=USO)\n    parser.add_argument(\"pergunta\", nargs=\"?\", default=\"\",\n                        help=\"o termo exato ou as palavras que o trecho tem\")\n    parser.add_argument(\"--alvo\", default=\"\",\n                        help=\"busca s\u00f3 neste alvo: o fim do caminho de um \"\n                             \"declarado ou uma pasta (padr\u00e3o: todos os \"\n                             \"declarados)\")\n    parser.add_argument(\"--quantos\", type=int, default=QUANTOS_POR_PADRAO,\n                        help=\"trechos por alvo\")\n    parser.add_argument(\"--teto-total\", type=int,\n                        default=TETO_TOTAL_POR_PADRAO,\n                        help=\"teto de trechos na resposta inteira, somando \"\n                             \"os alvos; o que passar do teto n\u00e3o \u00e9 impresso \"\n                             \"e a resposta diz quanto havia\")\n    parser.add_argument(\"--denso\", action=\"store_true\",\n                        help=\"n\u00e3o muda nada: o motor \u00e9 l\u00e9xico\")\n    parser.add_argument(\"--medir\", action=\"store_true\",\n                        help=\"n\u00e3o medido: o motor \u00e9 l\u00e9xico\")\n    parser.add_argument(\"--cwd\", default=\".\")\n    parser.add_argument(BANDEIRA_DE_TESTE, action=\"store_true\")\n    return parser\n\n\ndef main() -> int:\n    if BANDEIRA_DE_TESTE in sys.argv[1:]:\n        return testar()\n    a = montar_parser().parse_args()\n    if a.medir:\n        print(NAO_MEDIDO_SEM_DENSO)\n        return 1\n    if a.denso:\n        print(AVISO_DO_DENSO, file=sys.stderr)\n    return buscar(a.pergunta, configuracao(a.cwd), a.alvo, a.quantos,\n                  a.teto_total, a.cwd)\n\n\nif __name__ == \"__main__\":\n    for canal in (sys.stdin, sys.stdout, sys.stderr):\n        if not getattr(canal, \"closed\", True) and hasattr(canal, \"reconfigure\"):\n            canal.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    sys.exit(main())\n"]
#[".agents/indice/docker-compose.gpu.yml", "services:\n  embeddings:\n    deploy:\n      resources:\n        reservations:\n          devices:\n            - driver: nvidia\n              count: all\n              capabilities: [gpu]\n"]
#[".agents/indice/docker-compose.yml", "services:\n  vetores:\n    image: milvusdb/milvus:${INDICE_VERSAO_MILVUS:-v2.5.27}\n    command: [\"milvus\", \"run\", \"standalone\"]\n    restart: unless-stopped\n    security_opt:\n      - seccomp:unconfined\n    environment:\n      ETCD_USE_EMBED: \"true\"\n      ETCD_DATA_DIR: /var/lib/milvus/etcd\n      ETCD_CONFIG_PATH: /milvus/configs/embedEtcd.yaml\n      COMMON_STORAGETYPE: local\n    volumes:\n      - dados-vetores:/var/lib/milvus\n      - ./embedEtcd.yaml:/milvus/configs/embedEtcd.yaml\n    ports:\n      - \"${INDICE_PORTA_MILVUS:-19530}:19530\"\n      - \"${INDICE_PORTA_SAUDE:-9091}:9091\"\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:9091/healthz\"]\n      interval: 30s\n      timeout: 10s\n      retries: 5\n      start_period: 60s\n\n  embeddings:\n    image: ollama/ollama:${INDICE_VERSAO_OLLAMA:-latest}\n    restart: unless-stopped\n    volumes:\n      - dados-embeddings:/root/.ollama\n    ports:\n      - \"${INDICE_PORTA_OLLAMA:-11434}:11434\"\n\nvolumes:\n  dados-vetores:\n  dados-embeddings:\n"]
